Tutor.registerIndex("sci-elem", [
{"id":"sci-e3-01","kind":"unit","title":"과학자처럼 탐구하기","text":"과학자들이 자연을 알아내는 방법인 관찰, 측정, 분류, 예상, 추리, 의사소통을 직접 연습해 봐요. 여러 감각을 써서 안전하게 관찰하고 기록할 수 있어요. 자와 초시계 같은 도구로 길이와 시간을 바르게 잴 수 있어요. 누가 해도 같은 결과가 나오는 기준으로 물체를 분류할 수 있어요. 규칙을 찾아 결과를 예상하고, 관찰한 사실로 보이지 않는 것을 추리할 수…","keywords":["관찰","감각 기관","측정","단위","분류","분류 기준","예상","추리","의사소통"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-01","grade":"e3"},
{"id":"sci-e3-01#c0","kind":"concept","title":"관찰: 감각으로 자세히 살펴보기","text":"관찰은 눈, 코, 귀, 손 같은 감각 기관을 써서 대상을 자세히 살펴보는 거예요. 귤 하나도 여러 감각으로 관찰할 수 있어요. 감각 · 귤을 관찰한 내용 눈(보기) · 주황색이고 둥글어요. 껍질에 작은 점이 많아요. 코(냄새) · 새콤한 냄새가 나요. 손(만지기) · 껍질이 울퉁불퉁하고","keywords":["관찰","감각 기관"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-01","grade":"e3"},
{"id":"sci-e3-01#c1","kind":"concept","title":"측정: 도구로 재어 수로 나타내기","text":"측정은 자, 초시계, 저울 같은 도구를 써서 길이, 시간, 무게 등을 재고 수와 단위로 나타내는 거예요. \"연필이 길어요\"라고 하면 사람마다 생각하는 길이가 달라요. 하지만 \"연필의 길이는 15 cm예요\"라고 하면 누구나 똑같이 알 수 있어요. 그래서 과학자는 측정을 해요. 자로 길이를","keywords":["측정","단위"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-e3","unit":"sci-e3-01","grade":"e3"},
{"id":"sci-e3-01#c2","kind":"concept","title":"분류: 기준을 정해 무리 짓기","text":"분류는 여러 대상을 공통된 특징에 따라 무리 지어 나누는 거예요. 나누는 데 쓰는 질문을 분류 기준이라고 해요. 좋은 분류 기준은 누가 해도 같은 결과가 나오는 기준이에요. 좋은 기준 · 알맞지 않은 기준 다리가 있는가? · 귀여운가? 길이가 10 cm보다 긴가? · 큰가? 색깔이 빨간","keywords":["분류","분류 기준"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-e3","unit":"sci-e3-01","grade":"e3"},
{"id":"sci-e3-01#c3","kind":"concept","title":"예상: 규칙으로 결과를 미리 생각하기","text":"예상은 관찰하거나 측정한 결과에서 규칙을 찾아, 아직 해 보지 않은 결과를 미리 생각해 보는 거예요. 예를 들어 같은 컵으로 물을 부을 때마다 그릇의 물 높이를 재었어요. 부은 컵 수 · 1컵 · 2컵 · 3컵 물 높이 · 2 cm · 4 cm · 6 cm 한 컵을 부을 때마다 물 높이","keywords":["관찰","측정","예상"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-e3","unit":"sci-e3-01","grade":"e3"},
{"id":"sci-e3-01#c4","kind":"concept","title":"추리: 보이지 않는 것을 짐작하기","text":"추리는 관찰한 사실과 이미 알고 있는 경험을 바탕으로, 직접 보이지 않는 것을 짐작하는 거예요. 관찰한 사실: 아침에 보니 운동장 땅이 젖어 있고 물웅덩이가 있어요. 경험: 비가 오면 땅이 젖고 웅덩이가 생겨요. 추리: 밤사이 비가 내렸을 거예요. 밤에 비가 오는 것을 직접 보지는 못했","keywords":["관찰","추리"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-e3","unit":"sci-e3-01","grade":"e3"},
{"id":"sci-e3-01#c5","kind":"concept","title":"의사소통: 탐구한 것을 다른 사람에게 전하기","text":"의사소통은 탐구한 과정과 결과를 그림, 표, 글, 그래프 등으로 다른 사람에게 전하고, 다른 사람의 생각도 듣는 거예요. 그림: 생김새를 보여 줄 때 좋아요. 표: 여러 결과를 한눈에 비교할 때 좋아요. 글: 무엇을 어떻게 했는지, 무엇을 알게 되었는지 설명할 때 좋아요. 이름 · 종이","keywords":["예상","의사소통"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-e3","unit":"sci-e3-01","grade":"e3"},
{"id":"sci-e3-01#t0","kind":"term","title":"관찰","text":"눈, 코, 귀, 손 같은 감각 기관으로 대상을 자세히 살펴보는 거예요. 모르는 것은 맛보지 않아요.","keywords":["관찰"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-01","grade":"e3"},
{"id":"sci-e3-01#t1","kind":"term","title":"감각 기관","text":"보고(눈), 듣고(귀), 냄새 맡고(코), 맛보고(혀), 만져서(피부) 느끼는 몸의 부분이에요.","keywords":["감각 기관"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-e3","unit":"sci-e3-01","grade":"e3"},
{"id":"sci-e3-01#t2","kind":"term","title":"측정","text":"자, 초시계, 저울 같은 도구로 길이·시간·무게 등을 재어 수와 단위로 나타내는 거예요.","keywords":["측정"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-e3","unit":"sci-e3-01","grade":"e3"},
{"id":"sci-e3-01#t3","kind":"term","title":"단위","text":"잰 양이 무엇의 몇 배인지 나타내는 기준이에요. 예: 길이는 cm·m, 시간은 초·분","keywords":["단위"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-e3","unit":"sci-e3-01","grade":"e3"},
{"id":"sci-e3-01#t4","kind":"term","title":"분류","text":"여러 대상을 공통된 특징에 따라 무리 지어 나누는 거예요.","keywords":["분류"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-e3","unit":"sci-e3-01","grade":"e3"},
{"id":"sci-e3-01#t5","kind":"term","title":"분류 기준","text":"분류할 때 쓰는 질문이에요. 누가 해도 같은 결과가 나와야 해요. 예: \"다리가 있는가?\"","keywords":["분류 기준"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-e3","unit":"sci-e3-01","grade":"e3"},
{"id":"sci-e3-01#t6","kind":"term","title":"예상","text":"관찰·측정 결과에서 찾은 규칙으로 아직 해 보지 않은 결과를 미리 생각하는 거예요.","keywords":["예상"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-e3","unit":"sci-e3-01","grade":"e3"},
{"id":"sci-e3-01#t7","kind":"term","title":"추리","text":"관찰한 사실과 경험을 바탕으로 직접 보이지 않는 것을 짐작하는 거예요. 예: 젖은 땅을 보고 비가 왔다고 짐작하기","keywords":["추리"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-e3","unit":"sci-e3-01","grade":"e3"},
{"id":"sci-e3-01#t8","kind":"term","title":"의사소통","text":"탐구한 과정과 결과를 그림·표·글 등으로 다른 사람에게 전하고 생각을 나누는 거예요.","keywords":["의사소통"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-e3","unit":"sci-e3-01","grade":"e3"},
{"id":"sci-e3-01#f0","kind":"faq","title":"예상이랑 추리는 뭐가 달라요?","text":"예상은 찾은 규칙으로 아직 해 보지 않은 결과를 미리 생각하는 것이에요. 추리는 관찰한 사실과 경험으로 지금 직접 보이지 않는 것을 짐작하는 것이에요. \"4컵을 부으면 물 높이가 8 cm쯤 될 거야.\"는 예상, \"땅이 젖었으니 밤에 비가 왔을 거야.\"는 추리예요.","keywords":["예상","추리"],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-01","grade":"e3"},
{"id":"sci-e3-01#f1","kind":"faq","title":"자의 끝부분에 물체를 맞추면 안 돼요?","text":"많은 자는 맨 끝 모서리와 0 눈금 사이에 빈 곳이 조금 있어요. 끝 모서리에 맞추면 실제보다 짧게 잴 수 있어요. 꼭 0 눈금을 찾아 맞추세요. 0 눈금이 닳아서 보이지 않으면 1 cm 눈금에 맞추고 나중에 1을 빼면 돼요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-e3","unit":"sci-e3-01","grade":"e3"},
{"id":"sci-e3-01#f2","kind":"faq","title":"관찰할 때 왜 맛을 보면 안 돼요?","text":"처음 보는 열매, 버섯, 가루 가운데에는 먹으면 몸에 해로운 것이 있어요. 겉모습만으로는 알 수 없어서 위험해요. 그래서 무엇인지 모르는 것은 절대 맛보지 않고, 눈·코·귀·손으로 관찰해요.","keywords":["관찰"],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-e3","unit":"sci-e3-01","grade":"e3"},
{"id":"sci-e3-01#m0","kind":"mistake","title":"자주 하는 실수","text":"자의 0 눈금이 아닌 곳에서 시작했는데 끝 눈금을 그대로 길이라고 읽는 실수 — 끝 눈금에서 시작 눈금을 빼요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e3","unit":"sci-e3-01","grade":"e3"},
{"id":"sci-e3-01#m1","kind":"mistake","title":"자주 하는 실수","text":"\"귀여운가?\", \"큰가?\"처럼 사람마다 판단이 다른 것을 분류 기준으로 쓰는 실수 — 누가 해도 같은 결과가 나오는 기준을 써요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e3","unit":"sci-e3-01","grade":"e3"},
{"id":"sci-e3-01#m2","kind":"mistake","title":"자주 하는 실수","text":"눈으로 본 사실(관찰)과 그것으로 짐작한 것(추리)을 섞어 쓰는 실수 — \"보았다\"와 \"~일 것이다\"를 나누어 기록해요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e3","unit":"sci-e3-01","grade":"e3"},
{"id":"sci-e3-02","kind":"unit","title":"힘과 우리 생활","text":"물체를 밀고 당길 때의 힘, 수평 잡기와 저울로 무게를 비교하는 방법, 지레와 빗면을 쓸 때 드는 힘의 변화를 알아봐요. 물체를 밀거나 당기면 물체에 어떤 변화가 생기는지 말할 수 있어요. 수평 잡기로 두 물체의 무게를 비교할 수 있어요. 용수철저울과 전자저울로 무게를 바르게 잴 수 있어요. 지레와 빗면을 쓰면 물체를 들어 올릴 때 드는 힘이 달라진다는 …","keywords":["힘","받침점","수평","저울","용수철저울","전자저울","영점 조절","지레","빗면"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-02","grade":"e3"},
{"id":"sci-e3-02#c0","kind":"concept","title":"밀기와 당기기: 힘이 하는 일","text":"문을 열려고 밀거나, 서랍을 열려고 당길 때 우리는 물체에 힘을 줘요. 물체에 힘을 주면 이런 변화가 생겨요. 멈춰 있던 물체가 움직이기 시작해요. (공을 차면 굴러가요.) 움직이던 물체가 빨라지거나 느려지거나 멈춰요. (굴러오는 공을 손으로 막으면 멈춰요.) 움직이는 방향이 바뀌어요.","keywords":["힘"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-02","grade":"e3"},
{"id":"sci-e3-02#c1","kind":"concept","title":"수평 잡기로 무게 비교하기","text":"긴 나무판자 가운데를 받침대 위에 올려놓으면 시소처럼 돼요. 판자를 받치는 곳을 받침점이라고 해요. 두 물체를 받침점에서 같은 거리에 올려놓으면 판자가 기울어지면 내려간 쪽 물체가 더 무거워요. 판자가 어느 쪽으로도 기울지 않고 수평을 이루면 두 물체의 무게가 같아요. ⚠️ 받침점에서 ","keywords":["받침점","수평"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-e3","unit":"sci-e3-02","grade":"e3"},
{"id":"sci-e3-02#c2","kind":"concept","title":"저울이 필요한 까닭","text":"두 물체를 양손에 들어 보거나 수평 잡기를 하면 어느 쪽이 더 무거운지는 알 수 있어요. 하지만 이 방법에는 아쉬운 점이 있어요. 손으로 들어 보는 것은 사람마다 느낌이 달라서 정확하지 않아요. 무게가 비슷하면 어느 쪽이 무거운지 알기 어려워요. 얼마나 더 무거운지는 알 수 없어요. 저","keywords":["수평","저울"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-e3","unit":"sci-e3-02","grade":"e3"},
{"id":"sci-e3-02#c3","kind":"concept","title":"용수철저울과 전자저울 쓰는 법","text":"용수철저울은 용수철이 늘어나는 정도로 무게를 재는 저울이에요. 물체가 무거울수록 용수철이 더 많이 늘어나요. 아무것도 걸지 않았을 때 표시 자가 0에 오도록 맞춰요(영점 조절). 고리에 물체를 걸어요. 표시 자와 눈높이를 맞추어 눈금을 읽어요. 전자저울은 무게가 숫자로 바로 나타나는 저","keywords":["저울","용수철저울","전자저울","영점 조절"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-e3","unit":"sci-e3-02","grade":"e3"},
{"id":"sci-e3-02#c4","kind":"concept","title":"지레를 쓰면 드는 힘이 달라져요","text":"무거운 돌을 손으로 들기는 어렵지만, 긴 막대 밑에 받침을 대고 막대 끝을 누르면 돌을 쉽게 들어 올릴 수 있어요. 이렇게 막대와 받침을 써서 물체를 움직이는 도구를 지레라고 해요. 나무 막대와 받침으로 직접 해 보면 이런 것을 알 수 있어요. 지레를 쓰면 손으로 직접 들 때보다 힘이 ","keywords":["힘","지레"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-e3","unit":"sci-e3-02","grade":"e3"},
{"id":"sci-e3-02#c5","kind":"concept","title":"빗면을 쓰면 드는 힘이 달라져요","text":"빗면은 비스듬하게 기울어진 면이에요. 무거운 상자를 트럭에 실을 때, 곧바로 들어 올리는 것보다 판자를 비스듬히 걸쳐 놓고 빗면을 따라 끌어 올리면 힘이 적게 들어요. 빗면의 기울기를 바꾸어 용수철저울로 드는 힘을 재어 보면 방법 · 드는 힘 곧바로 들어 올리기 · 가장 커요 가파른 빗","keywords":["힘","저울","용수철저울","빗면"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-e3","unit":"sci-e3-02","grade":"e3"},
{"id":"sci-e3-02#t0","kind":"term","title":"힘","text":"물체를 밀거나 당길 때 물체에 작용하는 것이에요. 힘을 주면 물체의 움직임이나 모양이 바뀌어요.","keywords":["힘"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-02","grade":"e3"},
{"id":"sci-e3-02#t1","kind":"term","title":"받침점","text":"시소나 판자를 아래에서 받쳐 주는 곳이에요.","keywords":["받침점"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-e3","unit":"sci-e3-02","grade":"e3"},
{"id":"sci-e3-02#t2","kind":"term","title":"수평","text":"판자가 어느 쪽으로도 기울지 않고 반듯한 상태예요. 받침점에서 같은 거리에 놓은 두 물체가 수평을 이루면 무게가 같아요.","keywords":["수평"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-e3","unit":"sci-e3-02","grade":"e3"},
{"id":"sci-e3-02#t3","kind":"term","title":"저울","text":"물체의 무게를 재는 도구예요. 무게를 g, kg 같은 단위와 수로 나타내요.","keywords":["저울"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-e3","unit":"sci-e3-02","grade":"e3"},
{"id":"sci-e3-02#t4","kind":"term","title":"용수철저울","text":"물체를 걸면 용수철이 늘어나는 정도로 무게를 재는 저울이에요. 무거울수록 많이 늘어나요.","keywords":["용수철저울"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-e3","unit":"sci-e3-02","grade":"e3"},
{"id":"sci-e3-02#t5","kind":"term","title":"전자저울","text":"물체를 올리면 무게가 숫자로 바로 나타나는 저울이에요. 평평한 곳에 놓고 0을 확인한 뒤 써요.","keywords":["전자저울"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-e3","unit":"sci-e3-02","grade":"e3"},
{"id":"sci-e3-02#t6","kind":"term","title":"영점 조절","text":"아무것도 올리거나 걸지 않았을 때 저울이 0을 가리키도록 맞추는 것이에요.","keywords":["영점 조절"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-e3","unit":"sci-e3-02","grade":"e3"},
{"id":"sci-e3-02#t7","kind":"term","title":"지레","text":"막대와 받침을 써서 물체를 들어 올리거나 움직이는 도구예요. 예: 시소, 병따개, 장도리","keywords":["지레"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-e3","unit":"sci-e3-02","grade":"e3"},
{"id":"sci-e3-02#t8","kind":"term","title":"빗면","text":"비스듬하게 기울어진 면이에요. 물체를 빗면을 따라 올리면 곧바로 들 때보다 힘이 적게 들어요. 예: 경사로","keywords":["빗면"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-e3","unit":"sci-e3-02","grade":"e3"},
{"id":"sci-e3-02#f0","kind":"faq","title":"크기가 크면 무조건 더 무거워요?","text":"아니에요. 커다란 풍선은 작은 쇠구슬보다 훨씬 가벼워요. 크기만 보고 무게를 알 수는 없어요. 그래서 수평 잡기나 저울로 무게를 직접 비교해요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-02","grade":"e3"},
{"id":"sci-e3-02#f1","kind":"faq","title":"용수철저울은 왜 눈높이를 맞춰서 읽어요?","text":"눈금을 위에서 내려다보거나 아래에서 올려다보면 표시 자가 실제와 다른 눈금에 있는 것처럼 보여요. 표시 자와 눈의 높이를 같게 하고 똑바로 보아야 정확하게 읽을 수 있어요.","keywords":["저울","용수철저울"],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-e3","unit":"sci-e3-02","grade":"e3"},
{"id":"sci-e3-02#f2","kind":"faq","title":"빗면을 쓰면 힘이 덜 드는데 왜 다 빗면으로 안 올려요?","text":"빗면이 완만할수록 힘은 적게 들지만 움직이는 거리가 길어져요. 아주 완만한 빗면을 만들려면 긴 판자와 넓은 자리가 필요하지요. 그래서 상황에 맞게 알맞은 기울기의 빗면을 골라 써요.","keywords":["힘","빗면"],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-e3","unit":"sci-e3-02","grade":"e3"},
{"id":"sci-e3-02#m0","kind":"mistake","title":"자주 하는 실수","text":"크기가 큰 물체가 무조건 더 무겁다고 생각하는 실수 — 무게는 크기로 알 수 없어요. 수평 잡기나 저울로 비교해요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e3","unit":"sci-e3-02","grade":"e3"},
{"id":"sci-e3-02#m1","kind":"mistake","title":"자주 하는 실수","text":"수평 잡기를 할 때 받침점에서 다른 거리에 놓고 무게를 비교하는 실수 — 꼭 같은 거리에 놓아요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e3","unit":"sci-e3-02","grade":"e3"},
{"id":"sci-e3-02#m2","kind":"mistake","title":"자주 하는 실수","text":"저울에 물체를 올리기 전에 0을 확인하지 않는 실수 — 영점이 맞지 않으면 무게가 틀리게 나와요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e3","unit":"sci-e3-02","grade":"e3"},
{"id":"sci-e3-03","kind":"unit","title":"동물의 생활","text":"주변 동물을 관찰해 특징에 따라 분류하고, 사는 곳에 따라 다른 생김새와 생활 방식을 알아봐요. 주변에 사는 동물의 생김새를 관찰하고 말할 수 있어요. 다리·날개·더듬이 같은 특징을 기준으로 동물을 분류할 수 있어요. 땅, 물, 하늘, 사막, 극지방에 사는 동물의 생김새와 움직이는 방법을 사는 곳과 관련지어 말할 수 있어요. 동물의 특징을 본떠 만든 생활…","keywords":["더듬이","곤충","지느러미","아가미","물갈퀴","깃털","지방층","극지방"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-03","grade":"e3"},
{"id":"sci-e3-03#c0","kind":"concept","title":"주변에 사는 동물 관찰하기","text":"화단, 공원, 놀이터에서도 여러 동물을 만날 수 있어요. 돋보기로 자세히 관찰해 보면 동물마다 생김새가 달라요. 동물 · 관찰한 생김새 달팽이 · 등에 나선 모양 껍데기가 있어요. 머리에 더듬이가 두 쌍 있고, 긴 더듬이 끝에 눈이 있어요. 다리 없이 배를 바닥에 붙이고 기어가요. 개미","keywords":["더듬이","곤충","깃털"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-03","grade":"e3"},
{"id":"sci-e3-03#c1","kind":"concept","title":"특징에 따라 동물 분류하기","text":"동물을 분류할 때는 누가 해도 같은 결과가 나오는 기준을 써요. \"다리가 있는가?\", \"날개가 있는가?\", \"더듬이가 있는가?\" 같은 것이 좋은 기준이에요. \"다리가 있는가?\"로 분류하기 그렇다 · 그렇지 않다 개미, 참새, 고양이, 개구리 · 달팽이, 지렁이, 뱀, 붕어 \"날개가 있는","keywords":["더듬이"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-e3","unit":"sci-e3-03","grade":"e3"},
{"id":"sci-e3-03#c2","kind":"concept","title":"땅에서 사는 동물","text":"땅에서 사는 동물은 땅 위에 사는 동물과 땅속에 사는 동물이 있어요. 땅 위에 사는 동물 고양이, 토끼, 다람쥐: 다리로 걷거나 뛰어다녀요. 뱀: 다리가 없어서 몸을 구부렸다 펴며 기어서 움직여요. 땅속에 사는 동물 두더지: 삽처럼 넓고 튼튼한 앞발로 흙을 파서 굴을 만들어요. 지렁이:","keywords":[],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-e3","unit":"sci-e3-03","grade":"e3"},
{"id":"sci-e3-03#c3","kind":"concept","title":"물에서 사는 동물과 날아다니는 동물","text":"물에서 사는 동물 붕어, 고등어: 물속에서 지느러미를 움직여 헤엄쳐요. 몸이 미끈하고 앞뒤가 날렵해서 물속에서 잘 나아가요. 아가미로 물속에서 숨을 쉬어요. 오리: 발가락 사이에 얇은 막인 물갈퀴가 있어서 물을 잘 밀어 헤엄쳐요. 게: 물가나 갯벌에서 다리로 옆으로 걸어 다녀요. 날아다","keywords":["곤충","지느러미","아가미","물갈퀴","깃털"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-e3","unit":"sci-e3-03","grade":"e3"},
{"id":"sci-e3-03#c4","kind":"concept","title":"사막과 극지방에 사는 동물","text":"아주 덥고 물이 적은 사막이나 아주 추운 극지방에 사는 동물도 있어요. 이 동물들은 그곳에서 살아가기 알맞은 생김새와 생활 방식을 가지고 있어요. 사막에 사는 동물 낙타: 등의 혹에 지방을 저장해 먹이가 없어도 오래 견뎌요. 발바닥이 넓어서 모래에 잘 빠지지 않아요. 긴 속눈썹과 여닫을","keywords":["깃털","지방층","극지방"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-e3","unit":"sci-e3-03","grade":"e3"},
{"id":"sci-e3-03#c5","kind":"concept","title":"동물의 특징을 본떠 만든 물건","text":"사람들은 동물의 특징을 본떠 생활에 쓰이는 물건을 만들기도 해요. 동물의 특징 · 본떠 만든 물건 오리 발의 물갈퀴 · 헤엄칠 때 신는 오리발 문어 다리의 빨판 · 벽에 붙이는 흡착판 물건을 움켜쥐는 수리의 발 · 물건을 집어 올리는 집게 물총새의 뾰족한 부리 · 공기를 잘 가르는 고속","keywords":["물갈퀴"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-e3","unit":"sci-e3-03","grade":"e3"},
{"id":"sci-e3-03#t0","kind":"term","title":"더듬이","text":"머리에 달린 가늘고 긴 부분이에요. 주변을 느끼는 데 써요. 예: 개미, 나비, 달팽이","keywords":["더듬이"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-03","grade":"e3"},
{"id":"sci-e3-03#t1","kind":"term","title":"곤충","text":"몸이 머리, 가슴, 배 세 부분으로 나뉘고 다리가 6개인 동물이에요. 예: 개미, 나비, 잠자리","keywords":["곤충"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-e3","unit":"sci-e3-03","grade":"e3"},
{"id":"sci-e3-03#t2","kind":"term","title":"지느러미","text":"물고기 몸에 붙은 얇은 부분이에요. 움직여서 물속에서 헤엄쳐요.","keywords":["지느러미"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-e3","unit":"sci-e3-03","grade":"e3"},
{"id":"sci-e3-03#t3","kind":"term","title":"아가미","text":"물고기가 물속에서 숨을 쉬는 몸의 부분이에요.","keywords":["아가미"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-e3","unit":"sci-e3-03","grade":"e3"},
{"id":"sci-e3-03#t4","kind":"term","title":"물갈퀴","text":"오리나 개구리 발가락 사이에 있는 얇은 막이에요. 물을 잘 밀어 헤엄치게 해 줘요.","keywords":["물갈퀴"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-e3","unit":"sci-e3-03","grade":"e3"},
{"id":"sci-e3-03#t5","kind":"term","title":"깃털","text":"새의 몸을 덮고 있는 털이에요. 몸을 따뜻하게 하고 나는 데 도움을 줘요.","keywords":["깃털"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-e3","unit":"sci-e3-03","grade":"e3"},
{"id":"sci-e3-03#t6","kind":"term","title":"지방층","text":"피부 아래에 지방이 두껍게 쌓인 층이에요. 북극곰이나 펭귄이 추위를 견디게 해 줘요.","keywords":["지방층"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-e3","unit":"sci-e3-03","grade":"e3"},
{"id":"sci-e3-03#t7","kind":"term","title":"극지방","text":"지구의 북쪽 끝과 남쪽 끝 둘레의 아주 추운 곳이에요. 북극곰은 북극, 펭귄은 주로 남극 둘레에 살아요.","keywords":["극지방"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-e3","unit":"sci-e3-03","grade":"e3"},
{"id":"sci-e3-03#f0","kind":"faq","title":"닭은 잘 못 나는데 왜 날개가 있는 무리에 넣어요?","text":"분류 기준이 \"날 수 있는가?\"가 아니라 \"날개가 있는가?\"이기 때문이에요. 닭은 멀리 날지는 못해도 날개가 분명히 있어요. 분류할 때는 기준을 그대로 따져야 해요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-03","grade":"e3"},
{"id":"sci-e3-03#f1","kind":"faq","title":"거미도 곤충이에요?","text":"아니에요. 곤충은 몸이 머리·가슴·배 세 부분으로 나뉘고 다리가 6개예요. 거미는 몸이 두 부분으로 나뉘고 다리가 8개라서 곤충이 아니에요.","keywords":["곤충"],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-e3","unit":"sci-e3-03","grade":"e3"},
{"id":"sci-e3-03#f2","kind":"faq","title":"낙타 혹에는 물이 들어 있는 거 아니에요?","text":"많은 사람이 그렇게 알고 있지만, 낙타의 혹에는 지방이 들어 있어요. 낙타는 이 지방 덕분에 먹이가 없어도 오래 견딜 수 있어요. 낙타가 물을 오래 마시지 않고 견디는 것은 몸의 다른 특징 덕분이에요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-e3","unit":"sci-e3-03","grade":"e3"},
{"id":"sci-e3-03#m0","kind":"mistake","title":"자주 하는 실수","text":"낙타의 혹에 물이 들어 있다고 생각하는 실수 — 혹에는 지방이 들어 있어요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e3","unit":"sci-e3-03","grade":"e3"},
{"id":"sci-e3-03#m1","kind":"mistake","title":"자주 하는 실수","text":"\"날개가 있는가?\"로 분류할 때 날지 못하는 닭을 \"그렇지 않다\"에 넣는 실수 — 기준은 날 수 있는지가 아니라 날개가 있는지예요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e3","unit":"sci-e3-03","grade":"e3"},
{"id":"sci-e3-03#m2","kind":"mistake","title":"자주 하는 실수","text":"지렁이나 달팽이에게 다리가 있다고 생각하는 실수 — 둘 다 다리가 없어요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e3","unit":"sci-e3-03","grade":"e3"},
{"id":"sci-e3-04","kind":"unit","title":"식물의 생활","text":"여러 식물의 잎을 관찰해 기준을 정해 분류하고, 들·산·물·사막 등 사는 곳에 따라 다른 생김새와 생활 방식을 알아봐요. 잎의 모양, 가장자리, 잎맥을 살펴 식물을 관찰할 수 있어요. 잎의 특징으로 누가 해도 같은 결과가 나오는 기준을 정해 식물을 분류할 수 있어요. 들과 산, 물, 사막에 사는 식물의 생김새를 사는 곳과 관련지어 말할 수 있어요. 식물의…","keywords":["잎맥","톱니 모양","풀","나무","잎자루","물에 떠서 사는 식물","물에 잠겨 사는 식물","사막"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-04","grade":"e3"},
{"id":"sci-e3-04#c0","kind":"concept","title":"잎을 자세히 관찰하기","text":"식물마다 잎의 생김새가 달라요. 잎을 관찰할 때는 세 가지를 살펴봐요. 모양: 둥근 모양, 길쭉한 모양, 손바닥 모양, 바늘 모양 … 가장자리: 매끈한가, 톱날처럼 뾰족뾰족한 톱니 모양인가 잎맥: 잎에 있는 가는 줄이에요. 그물 모양으로 퍼져 있는가, 나란히 뻗어 있는가 식물 · 모양 ","keywords":["잎맥","톱니 모양","풀","나무"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-04","grade":"e3"},
{"id":"sci-e3-04#c1","kind":"concept","title":"잎의 특징으로 식물 분류하기","text":"잎을 분류할 때도 누가 해도 같은 결과가 나오는 기준을 써요. \"잎의 가장자리가 톱니 모양인가?\"로 분류하기 그렇다 · 그렇지 않다 벚나무, 단풍나무 · 감나무, 강아지풀 \"잎맥이 나란히 뻗어 있는가?\"로 분류하기 그렇다 · 그렇지 않다 강아지풀 · 벚나무, 감나무, 단풍나무 좋은 기준","keywords":["잎맥","톱니 모양","풀","나무"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-e3","unit":"sci-e3-04","grade":"e3"},
{"id":"sci-e3-04#c2","kind":"concept","title":"들과 산에 사는 식물","text":"들과 산에는 여러 가지 풀과 나무가 살아요. 풀과 나무는 모두 땅에 뿌리를 내리고, 줄기와 잎이 있어요. · 풀 · 나무 예 · 민들레, 강아지풀, 토끼풀 · 소나무, 단풍나무, 감나무 키 · 대부분 작아요 · 대부분 커요 줄기 · 가늘고 부드러워요 · 굵고 단단해요 나무는 여러 해 동","keywords":["풀","나무"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-e3","unit":"sci-e3-04","grade":"e3"},
{"id":"sci-e3-04#c3","kind":"concept","title":"물에 사는 식물","text":"강이나 연못에 사는 식물은 사는 모습에 따라 넷으로 나누어 볼 수 있어요. 사는 모습 · 예 · 생김새 물가에 사는 식물 · 갈대, 부들 · 뿌리는 물가의 흙에 내리고, 줄기와 잎은 물 밖으로 높이 자라요. 잎이 물에 떠 있는 식물 · 수련 · 뿌리는 물속 흙에 내리고, 넓은 잎이 물 ","keywords":["잎자루","물에 떠서 사는 식물","물에 잠겨 사는 식물"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-e3","unit":"sci-e3-04","grade":"e3"},
{"id":"sci-e3-04#c4","kind":"concept","title":"사막에 사는 식물","text":"사막은 비가 거의 오지 않아 아주 건조한 곳이에요. 사막에 사는 식물은 물을 아끼고 저장하기 알맞은 생김새를 가지고 있어요. 선인장 줄기가 굵어요. 굵은 줄기 속에 물을 많이 저장해요. 잎이 가시 모양으로 변했어요. 넓은 잎보다 물이 덜 빠져나가고, 동물이 함부로 먹지 못하게 막아 줘요","keywords":["사막"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-e3","unit":"sci-e3-04","grade":"e3"},
{"id":"sci-e3-04#c5","kind":"concept","title":"식물의 특징을 본떠 만든 물건","text":"사람들은 식물의 특징을 본떠 생활에 쓰이는 물건을 만들기도 해요. 식물의 특징 · 본떠 만든 물건 도꼬마리나 우엉 열매의 작은 갈고리 (옷이나 동물 털에 잘 붙어요) · 신발이나 가방을 여미는 찍찍이 물방울이 스며들지 않고 굴러떨어지는 연잎 · 물에 잘 젖지 않는 옷감이나 페인트 빙글빙","keywords":["나무"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-e3","unit":"sci-e3-04","grade":"e3"},
{"id":"sci-e3-04#t0","kind":"term","title":"잎맥","text":"잎에 있는 가는 줄이에요. 그물 모양으로 퍼진 것도 있고, 나란히 뻗은 것도 있어요.","keywords":["잎맥"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-04","grade":"e3"},
{"id":"sci-e3-04#t1","kind":"term","title":"톱니 모양","text":"잎의 가장자리가 톱날처럼 뾰족뾰족한 모양이에요. 예: 벚나무 잎, 단풍나무 잎","keywords":["톱니 모양"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-e3","unit":"sci-e3-04","grade":"e3"},
{"id":"sci-e3-04#t2","kind":"term","title":"풀","text":"줄기가 가늘고 부드러우며 대부분 키가 작은 식물이에요. 예: 민들레, 강아지풀","keywords":["풀"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-e3","unit":"sci-e3-04","grade":"e3"},
{"id":"sci-e3-04#t3","kind":"term","title":"나무","text":"줄기가 굵고 단단하며 여러 해 동안 사는 식물이에요. 예: 소나무, 감나무","keywords":["나무"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-e3","unit":"sci-e3-04","grade":"e3"},
{"id":"sci-e3-04#t4","kind":"term","title":"잎자루","text":"잎과 줄기를 이어 주는 가는 부분이에요. 부레옥잠의 잎자루는 볼록하고 속에 공기가 들어 있어요.","keywords":["잎자루"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-e3","unit":"sci-e3-04","grade":"e3"},
{"id":"sci-e3-04#t5","kind":"term","title":"물에 떠서 사는 식물","text":"뿌리를 흙에 내리지 않고 식물 전체가 물에 떠서 사는 식물이에요. 예: 부레옥잠, 개구리밥","keywords":["물에 떠서 사는 식물"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-e3","unit":"sci-e3-04","grade":"e3"},
{"id":"sci-e3-04#t6","kind":"term","title":"물에 잠겨 사는 식물","text":"식물 전체가 물속에 잠겨서 사는 식물이에요. 줄기와 잎이 가늘고 부드러워요. 예: 검정말, 나사말","keywords":["물에 잠겨 사는 식물"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-e3","unit":"sci-e3-04","grade":"e3"},
{"id":"sci-e3-04#t7","kind":"term","title":"사막","text":"비가 거의 오지 않아 아주 건조한 곳이에요. 선인장처럼 물을 저장하는 식물이 살아요.","keywords":["사막"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-e3","unit":"sci-e3-04","grade":"e3"},
{"id":"sci-e3-04#f0","kind":"faq","title":"선인장은 잎이 없는 거예요?","text":"선인장의 가시가 바로 잎이 변한 것이에요. 넓은 잎이 있으면 물이 쉽게 빠져나가는데, 가시처럼 가늘게 변해서 물을 아낄 수 있어요. 대신 초록색 굵은 줄기가 잎이 하던 일을 많이 맡아 해요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-04","grade":"e3"},
{"id":"sci-e3-04#f1","kind":"faq","title":"물에 사는 식물은 뿌리가 없어요?","text":"아니에요. 물에 사는 식물도 대부분 뿌리가 있어요. 갈대나 수련은 물 밑 흙에 뿌리를 내리고, 부레옥잠이나 개구리밥은 뿌리가 물속에 늘어져 있어요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-e3","unit":"sci-e3-04","grade":"e3"},
{"id":"sci-e3-04#f2","kind":"faq","title":"풀과 나무는 어떻게 구별해요?","text":"줄기를 보면 돼요. 나무는 줄기가 굵고 단단하며 여러 해 동안 자라면서 굵어져요. 풀은 줄기가 가늘고 부드러워요. 키도 대부분 나무가 풀보다 커요.","keywords":["풀","나무"],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-e3","unit":"sci-e3-04","grade":"e3"},
{"id":"sci-e3-04#m0","kind":"mistake","title":"자주 하는 실수","text":"\"잎이 크다\", \"잎이 예쁘다\"처럼 사람마다 판단이 다른 것을 분류 기준으로 쓰는 실수 — 모양·가장자리·잎맥처럼 누가 보아도 같은 특징을 써요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e3","unit":"sci-e3-04","grade":"e3"},
{"id":"sci-e3-04#m1","kind":"mistake","title":"자주 하는 실수","text":"물에 사는 식물을 모두 \"물에 떠서 사는 식물\"이라고 하는 실수 — 물가, 잎이 떠 있는, 떠서 사는, 잠겨 사는 식물로 나누어 봐요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e3","unit":"sci-e3-04","grade":"e3"},
{"id":"sci-e3-04#m2","kind":"mistake","title":"자주 하는 실수","text":"선인장 가시를 잎과 상관없는 것으로 생각하는 실수 — 가시는 잎이 변한 것이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e3","unit":"sci-e3-04","grade":"e3"},
{"id":"sci-e3-05","kind":"unit","title":"생물의 한살이","text":"곤충이 알에서 어른벌레가 되는 과정을 관찰하고, 씨가 싹 트고 식물이 자라는 조건을 실험으로 찾아봐요. 배추흰나비의 한살이를 알, 애벌레, 번데기, 어른벌레 순서로 말할 수 있어요. 번데기 단계가 있는 곤충과 없는 곤충, 알을 낳는 동물과 새끼를 낳는 동물의 한살이를 비교할 수 있어요. 한 가지 조건만 다르게 하는 실험으로 씨가 싹 트고 식물이 자라는 조…","keywords":["한살이","애벌레","허물","번데기","어른벌레","완전 탈바꿈","불완전 탈바꿈","떡잎","한해살이 식물","여러해살이 식물"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-05","grade":"e3"},
{"id":"sci-e3-05#c0","kind":"concept","title":"배추흰나비의 한살이","text":"생물이 태어나서 자라고, 자손을 남기고, 죽기까지의 과정을 한살이라고 해요. 배추흰나비는 알 → 애벌레 → 번데기 → 어른벌레 순서로 한살이를 거쳐요. 단계 · 모습 알 · 배추나 케일 잎 뒷면에 붙어 있어요. 길이가 1 mm쯤인 노란색 길쭉한 모양이에요. 애벌레 · 알에서 나오면 먼저","keywords":["한살이","애벌레","허물","번데기","어른벌레"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-05","grade":"e3"},
{"id":"sci-e3-05#c1","kind":"concept","title":"번데기가 있는 곤충과 없는 곤충","text":"곤충마다 한살이 과정이 조금씩 달라요. 번데기 단계를 거치는 곤충 — 알 → 애벌레 → 번데기 → 어른벌레 배추흰나비, 벌, 무당벌레, 사슴벌레, 장수풍뎅이, 파리, 모기 이런 한살이를 완전 탈바꿈이라고 해요. 번데기 단계를 거치지 않는 곤충 — 알 → 애벌레 → 어른벌레 잠자리, 메뚜","keywords":["한살이","애벌레","허물","번데기","어른벌레","완전 탈바꿈","불완전 탈바꿈"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-e3","unit":"sci-e3-05","grade":"e3"},
{"id":"sci-e3-05#c2","kind":"concept","title":"알을 낳는 동물과 새끼를 낳는 동물","text":"동물은 알을 낳는 동물과 새끼를 낳는 동물로 나눌 수 있어요. 알을 낳는 동물 · 새끼를 낳는 동물 닭, 오리, 개구리, 연어, 거북, 곤충 · 개, 고양이, 소, 토끼, 사람, 고래 닭의 한살이: 알 → (어미 닭이 21일쯤 품으면) 병아리 → 큰 병아리 → 다 자란 닭. 다 자란 암","keywords":["한살이"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-e3","unit":"sci-e3-05","grade":"e3"},
{"id":"sci-e3-05#c3","kind":"concept","title":"씨가 싹 트는 데 필요한 조건","text":"씨에서 뿌리와 싹이 나오는 것을 싹 트기라고 해요. 씨가 싹 트려면 무엇이 필요한지 실험으로 알아봐요. 실험할 때는 알아보려는 조건 한 가지만 다르게 하고, 나머지 조건은 모두 같게 해요. 그래야 결과가 어느 조건 때문인지 알 수 있어요. 물이 필요할까? · 물을 준 것 · 물을 주지 ","keywords":[],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-e3","unit":"sci-e3-05","grade":"e3"},
{"id":"sci-e3-05#c4","kind":"concept","title":"식물이 자라는 데 필요한 조건","text":"싹이 튼 뒤 식물이 잘 자라려면 무엇이 필요할까요? 싹이 튼 강낭콩 화분으로 실험해 봐요. 이번에도 한 가지 조건만 다르게 해요. 물이 필요할까? (두 화분 모두 햇빛이 드는 곳에 두기) 물을 준 화분: 잎이 많아지고 줄기가 굵어지며 잘 자라요. 물을 주지 않은 화분: 잎과 줄기가 시들","keywords":[],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-e3","unit":"sci-e3-05","grade":"e3"},
{"id":"sci-e3-05#c5","kind":"concept","title":"식물의 한살이: 한해살이와 여러해살이","text":"강낭콩의 한살이를 관찰해 봐요. 씨 → 뿌리가 먼저 나오고, 떡잎 2장이 땅 위로 나와 벌어져요(싹) → 떡잎 사이에서 본잎이 나오고 잎과 줄기가 자라요 → 꽃이 피어요 → 꽃이 진 자리에 꼬투리(열매)가 생기고 그 안에 씨가 생겨요. 이 씨를 심으면 다시 한살이가 시작돼요. · 한해살","keywords":["한살이","떡잎","한해살이 식물","여러해살이 식물"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-e3","unit":"sci-e3-05","grade":"e3"},
{"id":"sci-e3-05#t0","kind":"term","title":"한살이","text":"생물이 태어나서 자라고, 자손을 남기고, 죽기까지의 과정이에요.","keywords":["한살이"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-05","grade":"e3"},
{"id":"sci-e3-05#t1","kind":"term","title":"애벌레","text":"알에서 나와 어른벌레가 되기 전까지의 곤충이에요. 먹고 허물을 벗으며 자라요.","keywords":["애벌레"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-e3","unit":"sci-e3-05","grade":"e3"},
{"id":"sci-e3-05#t2","kind":"term","title":"허물","text":"애벌레가 자라면서 벗어 버리는 껍질이에요. 배추흰나비 애벌레는 허물을 네 번 벗어요.","keywords":["허물"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-e3","unit":"sci-e3-05","grade":"e3"},
{"id":"sci-e3-05#t3","kind":"term","title":"번데기","text":"애벌레가 어른벌레가 되기 전에 거치는 단계예요. 먹지 않고 거의 움직이지 않아요.","keywords":["번데기"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-e3","unit":"sci-e3-05","grade":"e3"},
{"id":"sci-e3-05#t4","kind":"term","title":"어른벌레","text":"다 자란 곤충이에요. 짝짓기를 하고 알을 낳아요.","keywords":["어른벌레"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-e3","unit":"sci-e3-05","grade":"e3"},
{"id":"sci-e3-05#t5","kind":"term","title":"완전 탈바꿈","text":"알 → 애벌레 → 번데기 → 어른벌레처럼 번데기 단계를 거치는 한살이예요. 예: 배추흰나비, 벌, 무당벌레","keywords":["완전 탈바꿈"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-e3","unit":"sci-e3-05","grade":"e3"},
{"id":"sci-e3-05#t6","kind":"term","title":"불완전 탈바꿈","text":"알 → 애벌레 → 어른벌레처럼 번데기 단계가 없는 한살이예요. 예: 잠자리, 메뚜기, 매미","keywords":["불완전 탈바꿈"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-e3","unit":"sci-e3-05","grade":"e3"},
{"id":"sci-e3-05#t7","kind":"term","title":"떡잎","text":"씨가 싹 틀 때 가장 먼저 나오는 잎이에요. 강낭콩은 떡잎이 2장이에요.","keywords":["떡잎"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-e3","unit":"sci-e3-05","grade":"e3"},
{"id":"sci-e3-05#t8","kind":"term","title":"한해살이 식물","text":"한 해 안에 한살이를 마치고 죽는 식물이에요. 예: 강낭콩, 벼, 옥수수","keywords":["한해살이 식물"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-e3","unit":"sci-e3-05","grade":"e3"},
{"id":"sci-e3-05#t9","kind":"term","title":"여러해살이 식물","text":"여러 해 동안 살면서 해마다 꽃이 피고 열매를 맺는 식물이에요. 예: 사과나무, 개나리, 민들레","keywords":["여러해살이 식물"],"ref":{"tab":"terms","idx":9},"subject":"sci","course":"sci-e3","unit":"sci-e3-05","grade":"e3"},
{"id":"sci-e3-05#f0","kind":"faq","title":"씨가 싹 틀 때 햇빛이 꼭 있어야 해요?","text":"강낭콩 같은 많은 씨는 햇빛이 없어도 물과 알맞은 온도가 있으면 싹이 터요. 씨 속 떡잎에 싹 틀 때 쓸 양분이 있기 때문이에요. 하지만 싹이 튼 뒤 잘 자라려면 햇빛이 꼭 필요해요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-05","grade":"e3"},
{"id":"sci-e3-05#f1","kind":"faq","title":"애벌레랑 번데기는 같은 거예요?","text":"아니에요. 애벌레는 잎을 먹고 기어 다니며 허물을 벗고 자라는 단계예요. 번데기는 애벌레가 다 자란 뒤 먹지 않고 거의 움직이지 않으면서 어른벌레의 몸으로 바뀌는 단계예요.","keywords":["애벌레","번데기"],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-e3","unit":"sci-e3-05","grade":"e3"},
{"id":"sci-e3-05#f2","kind":"faq","title":"실험할 때 왜 한 가지만 다르게 해요?","text":"두 가지 이상을 한꺼번에 다르게 하면, 결과가 달라졌을 때 어느 것 때문인지 알 수 없어요. 예를 들어 물과 온도를 함께 바꾸면 싹이 트지 않은 까닭이 물이 없어서인지, 추워서인지 모르지요. 그래서 알아보려는 조건 하나만 다르게 하고 나머지는 같게 해요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-e3","unit":"sci-e3-05","grade":"e3"},
{"id":"sci-e3-05#m0","kind":"mistake","title":"자주 하는 실수","text":"씨가 싹 트려면 햇빛이 꼭 필요하다고 생각하는 실수 — 싹 트는 데는 물과 알맞은 온도가 필요하고, 햇빛은 싹이 튼 뒤 자랄 때 필요해요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e3","unit":"sci-e3-05","grade":"e3"},
{"id":"sci-e3-05#m1","kind":"mistake","title":"자주 하는 실수","text":"모든 곤충이 번데기 단계를 거친다고 생각하는 실수 — 잠자리, 메뚜기, 매미는 번데기 단계가 없어요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e3","unit":"sci-e3-05","grade":"e3"},
{"id":"sci-e3-05#m2","kind":"mistake","title":"자주 하는 실수","text":"실험에서 여러 조건을 한꺼번에 다르게 하는 실수 — 알아보려는 조건 한 가지만 다르게 하고 나머지는 같게 해요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e3","unit":"sci-e3-05","grade":"e3"},
{"id":"sci-e3-06","kind":"unit","title":"물체와 물질","text":"물체를 이루는 물질의 성질을 비교하고, 고체·액체·기체의 특징과 물질을 알맞게 쓰는 방법을 알아봐요. 물체와 물질의 뜻을 구별할 수 있어요. 금속·플라스틱·나무·고무·유리의 성질을 비교하고, 성질에 맞게 물체를 만드는 까닭을 말할 수 있어요. 고체·액체·기체의 성질을 모양과 부피로 설명할 수 있어요.","keywords":["물체","물질","성질","부피","고체","액체","기체"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-06","grade":"e3"},
{"id":"sci-e3-06#c0","kind":"concept","title":"물체와 물질","text":"우리 주변에서 모양이 있고 공간을 차지하는 것을 물체라고 해요. 컵, 책상, 연필, 숟가락은 모두 물체예요. 물체를 만드는 재료는 물질이라고 해요. 유리컵은 유리라는 물질로, 나무 책상은 나무라는 물질로 만들었지요. 물체 · 만든 물질 유리컵 · 유리 숟가락 · 금속 고무장갑 · 고무 ","keywords":["물체","물질"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-06","grade":"e3"},
{"id":"sci-e3-06#c1","kind":"concept","title":"여러 가지 물질의 성질","text":"물질마다 성질(그 물질만의 특징)이 달라요. 손으로 만져 보고, 구부려 보고, 물에 넣어 보면 차이를 알 수 있어요. 물질 · 이런 성질이 있어요 금속 · 단단하고 튼튼해요. 반짝이는 것이 많고, 물에 넣으면 가라앉아요. 플라스틱 · 가볍고, 여러 가지 색깔과 모양으로 만들기 쉬워요. ","keywords":["물질","성질"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-e3","unit":"sci-e3-06","grade":"e3"},
{"id":"sci-e3-06#c2","kind":"concept","title":"물질의 성질에 맞게 쓰기","text":"같은 물체라도 어떤 물질로 만드느냐에 따라 좋은 점과 아쉬운 점이 달라져요. 컵을 예로 들어 볼까요? 컵 · 좋은 점 · 아쉬운 점 유리컵 · 투명해서 안에 든 것이 잘 보여요 · 떨어뜨리면 깨지기 쉬워요 플라스틱 컵 · 가볍고 잘 깨지지 않아요 · 쉽게 긁히고 흠집이 나요 금속 컵 ·","keywords":["물체","물질","성질"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-e3","unit":"sci-e3-06","grade":"e3"},
{"id":"sci-e3-06#c3","kind":"concept","title":"고체: 모양과 부피가 일정해요","text":"나무 블록, 돌, 숟가락처럼 담는 그릇이 바뀌어도 모양과 부피가 변하지 않는 물질의 상태를 고체라고 해요. (부피: 물질이 차지하는 공간의 크기) 나무 블록을 둥근 그릇에 넣어도, 네모난 그릇에 넣어도 블록의 모양과 크기는 그대로예요. 고체는 손으로 잡을 수 있어요. 💡 모래나 소금처","keywords":["물질","부피","고체"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-e3","unit":"sci-e3-06","grade":"e3"},
{"id":"sci-e3-06#c4","kind":"concept","title":"액체: 모양은 바뀌고 부피는 그대로예요","text":"물, 우유, 주스, 식용유처럼 흐르는 물질의 상태를 액체라고 해요. 액체는 담는 그릇에 따라 모양이 바뀌어요. 물을 둥근 컵에 부으면 둥근 모양, 네모난 그릇에 부으면 네모난 모양이 되지요. 하지만 부피는 변하지 않아요. 계량컵에 물 200 mL를 담아 여러 모양의 그릇에 차례로 옮겼다","keywords":["물질","부피","액체"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-e3","unit":"sci-e3-06","grade":"e3"},
{"id":"sci-e3-06#c5","kind":"concept","title":"기체: 공간을 차지하고 그릇을 가득 채워요","text":"공기처럼 눈에 보이지 않고 손으로 잡을 수 없지만 공간을 차지하는 물질의 상태를 기체라고 해요. 공간을 차지해요: 빈 컵을 거꾸로 엎어 물속에 똑바로 밀어 넣으면 컵 안으로 물이 다 들어오지 못해요. 컵 안의 공기가 자리를 차지하고 있기 때문이에요. 컵 바닥에 구멍을 뚫으면 공기가 빠져","keywords":["물질","고체","액체","기체"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-e3","unit":"sci-e3-06","grade":"e3"},
{"id":"sci-e3-06#t0","kind":"term","title":"물체","text":"모양이 있고 공간을 차지하는 것이에요. 예: 컵, 책상, 숟가락","keywords":["물체"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-06","grade":"e3"},
{"id":"sci-e3-06#t1","kind":"term","title":"물질","text":"물체를 만드는 재료예요. 예: 유리, 나무, 금속, 플라스틱, 고무","keywords":["물질"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-e3","unit":"sci-e3-06","grade":"e3"},
{"id":"sci-e3-06#t2","kind":"term","title":"성질","text":"그 물질만이 가진 특징이에요. 예: 고무는 잘 늘어나고, 유리는 투명해요.","keywords":["성질"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-e3","unit":"sci-e3-06","grade":"e3"},
{"id":"sci-e3-06#t3","kind":"term","title":"부피","text":"물질이 차지하는 공간의 크기예요.","keywords":["부피"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-e3","unit":"sci-e3-06","grade":"e3"},
{"id":"sci-e3-06#t4","kind":"term","title":"고체","text":"담는 그릇이 바뀌어도 모양과 부피가 변하지 않는 물질의 상태예요. 예: 돌, 나무 블록","keywords":["고체"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-e3","unit":"sci-e3-06","grade":"e3"},
{"id":"sci-e3-06#t5","kind":"term","title":"액체","text":"담는 그릇에 따라 모양은 바뀌지만 부피는 변하지 않는 물질의 상태예요. 예: 물, 우유","keywords":["액체"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-e3","unit":"sci-e3-06","grade":"e3"},
{"id":"sci-e3-06#t6","kind":"term","title":"기체","text":"눈에 잘 보이지 않지만 공간을 차지하고, 담긴 그릇을 가득 채우는 물질의 상태예요. 예: 공기","keywords":["기체"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-e3","unit":"sci-e3-06","grade":"e3"},
{"id":"sci-e3-06#f0","kind":"faq","title":"컵은 물체예요, 물질이에요?","text":"컵은 물체예요. 모양이 있고 물을 담는 쓰임새가 있지요. 컵을 만든 재료인 유리, 플라스틱, 금속, 종이가 물질이에요. \"무엇으로 만들었나요?\"의 대답이 물질이라고 기억하면 쉬워요.","keywords":["물체","물질"],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-06","grade":"e3"},
{"id":"sci-e3-06#f1","kind":"faq","title":"공기는 안 보이는데 어떻게 있는 줄 알아요?","text":"풍선을 불면 부풀어 오르고, 부채질을 하면 바람이 느껴지지요. 엎은 컵을 물속에 넣으면 물이 컵 안으로 다 들어오지 못해요. 이런 일은 눈에 보이지 않는 공기가 공간을 차지하고 있기 때문에 일어나요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-e3","unit":"sci-e3-06","grade":"e3"},
{"id":"sci-e3-06#f2","kind":"faq","title":"플라스틱은 모두 물에 떠요?","text":"물에 뜨는 플라스틱이 많지만 모두 그렇지는 않아요. 플라스틱도 종류가 여러 가지라서 가라앉는 것도 있어요. 그래서 \"플라스틱은 물에 뜨는 것이 많아요\"라고 말하는 것이 정확해요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-e3","unit":"sci-e3-06","grade":"e3"},
{"id":"sci-e3-06#m0","kind":"mistake","title":"자주 하는 실수","text":"물체와 물질을 거꾸로 말하는 실수 — 컵·책상처럼 모양과 쓰임새가 있는 것이 물체, 유리·나무처럼 만드는 재료가 물질이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e3","unit":"sci-e3-06","grade":"e3"},
{"id":"sci-e3-06#m1","kind":"mistake","title":"자주 하는 실수","text":"액체를 길쭉한 그릇에 옮겨 높이가 높아지면 양이 늘었다고 생각하는 실수 — 액체는 모양만 바뀌고 부피는 그대로예요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e3","unit":"sci-e3-06","grade":"e3"},
{"id":"sci-e3-06#m2","kind":"mistake","title":"자주 하는 실수","text":"빈 컵 안에는 아무것도 없다고 생각하는 실수 — 눈에 보이지 않는 공기(기체)가 가득 차 있어요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e3","unit":"sci-e3-06","grade":"e3"},
{"id":"sci-e3-07","kind":"unit","title":"지구와 바다","text":"공기로 둘러싸인 지구의 육지와 바다를 비교하고, 바닷물의 특징과 바닷가 지형, 갯벌의 가치를 알아봐요. 지구를 둘러싼 공기가 우리에게 주는 도움을 말할 수 있어요. 지구 표면의 육지와 바다를 비교하고, 바닷물과 강물·호숫물의 차이를 설명할 수 있어요. 바닷가의 여러 지형과 밀물·썰물을 알고, 갯벌의 가치와 보전 방법을 말할 수 있어요.","keywords":["대기","육지","증발","파도","모래사장","절벽","밀물","썰물","갯벌"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-07","grade":"e3"},
{"id":"sci-e3-07#c0","kind":"concept","title":"지구를 둘러싼 공기","text":"지구는 눈에 보이지 않는 공기로 둘러싸여 있어요. 지구를 둘러싼 공기 전체를 대기라고 해요. 공기는 우리에게 이런 도움을 줘요. 사람과 동물, 식물이 숨을 쉬며 살 수 있어요. 바람이 불고 구름이 생기고 비나 눈이 내리는 날씨 변화가 생겨요. 지구의 온도를 알맞게 지켜 줘서 낮과 밤의 ","keywords":["대기"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-07","grade":"e3"},
{"id":"sci-e3-07#c1","kind":"concept","title":"육지와 바다","text":"지구 표면은 흙과 바위로 된 육지와 물로 덮인 바다로 이루어져 있어요. 지구본이나 세계 지도를 보면 파란색으로 칠한 바다가 훨씬 넓어요. 지구 표면을 똑같이 10칸으로 나눈다면 바다가 7칸쯤, 육지가 3칸쯤이에요. 곧 바다가 육지보다 넓어요. 우주에서 찍은 지구 사진이 파랗게 보이는 것","keywords":["육지"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-e3","unit":"sci-e3-07","grade":"e3"},
{"id":"sci-e3-07#c2","kind":"concept","title":"바닷물과 육지의 물","text":"강물이나 호숫물은 짜지 않지만 바닷물은 짠맛이 나요. 바닷물에는 소금 같은 물질이 녹아 있기 때문이에요. 이것은 실험으로 확인할 수 있어요. 바닷물과 수돗물을 각각 접시에 같은 양만큼 담아 햇볕이 잘 드는 곳에 두면, 시간이 지나 물이 모두 날아간 뒤(증발) 차이가 나요. · 물이 날아","keywords":["육지","증발"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-e3","unit":"sci-e3-07","grade":"e3"},
{"id":"sci-e3-07#c3","kind":"concept","title":"파도와 바닷가의 여러 지형","text":"바다에서는 바람이 불어 바닷물 표면이 출렁이며 파도가 생겨요. 파도는 바닷가로 밀려와 오랜 시간 동안 바닷가의 모습을 바꿔 놓아요. 지형 · 모습 모래사장 · 고운 모래가 넓게 쌓인 곳. 파도가 실어 온 모래가 쌓여 생겨요 갯벌 · 바닷물이 빠졌을 때 드러나는 고운 흙(펄)으로 된 넓은","keywords":["파도","모래사장","절벽","갯벌"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-e3","unit":"sci-e3-07","grade":"e3"},
{"id":"sci-e3-07#c4","kind":"concept","title":"밀물과 썰물","text":"바닷가에서 하루 동안 바닷물을 지켜보면 바닷물의 높이가 높아졌다 낮아졌다 해요. 밀물: 바닷물이 육지 쪽으로 밀려 들어와 바닷물의 높이가 높아지는 것 썰물: 바닷물이 바다 쪽으로 빠져나가 바닷물의 높이가 낮아지는 것 밀물과 썰물은 날마다 되풀이되고, 우리나라 서해안에서는 보통 하루에 두","keywords":["육지","밀물","썰물","갯벌"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-e3","unit":"sci-e3-07","grade":"e3"},
{"id":"sci-e3-07#c5","kind":"concept","title":"갯벌의 가치와 보전","text":"갯벌은 밀물 때는 바닷물에 잠기고 썰물 때는 드러나는, 고운 흙으로 된 넓은 땅이에요. 우리나라 서해안과 남해안에 넓게 펼쳐져 있어요. 갯벌은 이런 점에서 소중해요. 여러 생물의 집: 게, 조개, 갯지렁이, 짱뚱어 같은 생물이 살고, 먼 길을 날아가는 철새가 쉬며 먹이를 먹어요. 오염 ","keywords":["육지","밀물","썰물","갯벌"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-e3","unit":"sci-e3-07","grade":"e3"},
{"id":"sci-e3-07#t0","kind":"term","title":"대기","text":"지구를 둘러싸고 있는 공기 전체예요.","keywords":["대기"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-07","grade":"e3"},
{"id":"sci-e3-07#t1","kind":"term","title":"육지","text":"지구 표면에서 흙과 바위로 된, 물에 덮이지 않은 땅이에요.","keywords":["육지"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-e3","unit":"sci-e3-07","grade":"e3"},
{"id":"sci-e3-07#t2","kind":"term","title":"증발","text":"물이 눈에 보이지 않게 공기 중으로 날아가는 것이에요. 예: 젖은 빨래가 마르는 것","keywords":["증발"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-e3","unit":"sci-e3-07","grade":"e3"},
{"id":"sci-e3-07#t3","kind":"term","title":"파도","text":"바람이 불어 바닷물 표면이 출렁이며 밀려오고 밀려가는 것이에요.","keywords":["파도"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-e3","unit":"sci-e3-07","grade":"e3"},
{"id":"sci-e3-07#t4","kind":"term","title":"모래사장","text":"고운 모래가 넓게 쌓여 있는 바닷가예요.","keywords":["모래사장"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-e3","unit":"sci-e3-07","grade":"e3"},
{"id":"sci-e3-07#t5","kind":"term","title":"절벽","text":"파도가 오랫동안 바위를 깎아서 생긴 가파른 낭떠러지예요.","keywords":["절벽"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-e3","unit":"sci-e3-07","grade":"e3"},
{"id":"sci-e3-07#t6","kind":"term","title":"밀물","text":"바닷물이 육지 쪽으로 밀려 들어와 바닷물의 높이가 높아지는 것이에요.","keywords":["밀물"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-e3","unit":"sci-e3-07","grade":"e3"},
{"id":"sci-e3-07#t7","kind":"term","title":"썰물","text":"바닷물이 바다 쪽으로 빠져나가 바닷물의 높이가 낮아지는 것이에요.","keywords":["썰물"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-e3","unit":"sci-e3-07","grade":"e3"},
{"id":"sci-e3-07#t8","kind":"term","title":"갯벌","text":"밀물 때는 바닷물에 잠기고 썰물 때는 드러나는, 고운 흙으로 된 넓은 땅이에요.","keywords":["갯벌"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-e3","unit":"sci-e3-07","grade":"e3"},
{"id":"sci-e3-07#f0","kind":"faq","title":"바닷물은 왜 짜요?","text":"바닷물에는 소금 같은 물질이 녹아 있기 때문이에요. 바닷물을 접시에 담아 물을 모두 증발시키면 하얀 물질이 남는 것으로 확인할 수 있어요. 강물과 호숫물에는 이런 물질이 아주 적어서 짜지 않아요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-07","grade":"e3"},
{"id":"sci-e3-07#f1","kind":"faq","title":"밀물과 썰물이 헷갈려요. 쉽게 외우는 방법이 있어요?","text":"바닷물이 육지 쪽으로 \"밀고\" 들어오면 밀물, 바닷물이 \"썰렁하게\" 빠져나가 갯벌이 드러나면 썰물이라고 기억해 보세요. 밀물 때 바닷물 높이가 높아지고, 썰물 때 낮아져요.","keywords":["밀물","썰물"],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-e3","unit":"sci-e3-07","grade":"e3"},
{"id":"sci-e3-07#f2","kind":"faq","title":"공기는 보이지도 않는데 정말 지구를 둘러싸고 있어요?","text":"네. 바람이 부는 것, 구름이 생기고 비가 오는 것, 우리가 숨을 쉴 수 있는 것은 모두 지구를 둘러싼 공기 덕분이에요. 눈에 보이지 않을 뿐 공기는 지구를 두껍게 감싸고 있어요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-e3","unit":"sci-e3-07","grade":"e3"},
{"id":"sci-e3-07#m0","kind":"mistake","title":"자주 하는 실수","text":"육지가 바다보다 넓다고 생각하는 실수 — 지구 표면을 10칸으로 나누면 바다가 7칸쯤으로 훨씬 넓어요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e3","unit":"sci-e3-07","grade":"e3"},
{"id":"sci-e3-07#m1","kind":"mistake","title":"자주 하는 실수","text":"바닷물을 끓이면 짠맛이 사라진다고 생각하는 실수 — 물만 날아가고 소금 같은 물질은 남아요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e3","unit":"sci-e3-07","grade":"e3"},
{"id":"sci-e3-07#m2","kind":"mistake","title":"자주 하는 실수","text":"밀물과 썰물을 거꾸로 말하는 실수 — 바닷물이 들어와 높아지면 밀물, 빠져나가 낮아지면 썰물이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e3","unit":"sci-e3-07","grade":"e3"},
{"id":"sci-e3-08","kind":"unit","title":"소리의 성질","text":"소리가 나는 물체의 떨림과 소리의 세기·높낮이를 알아보고, 소리가 전달되는 방법과 소음 줄이기를 배워요. 소리가 나는 물체는 떨린다는 것을 설명할 수 있어요. 큰 소리와 작은 소리, 높은 소리와 낮은 소리를 비교할 수 있어요. 소리가 고체·액체·기체를 통해 전달된다는 것을 알고, 생활 속 소음을 줄이는 방법을 실천할 수 있어요.","keywords":["떨림","소리의 세기","소리의 높낮이","실 전화","소음","방음벽"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-08","grade":"e3"},
{"id":"sci-e3-08#c0","kind":"concept","title":"소리가 나는 물체는 떨려요","text":"소리가 나는 물체를 살펴보면 모두 떨리고 있어요. 고무줄을 팽팽하게 당기고 튕기면 고무줄이 빠르게 떨리면서 소리가 나요. 목에 손을 가볍게 대고 \"아—\" 하고 소리를 내면 목이 떨리는 것이 느껴져요. 소리가 나는 북 위에 작은 종이 조각을 올려놓으면 종이 조각이 통통 튀어요. 떨림을 멈","keywords":["떨림"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-08","grade":"e3"},
{"id":"sci-e3-08#c1","kind":"concept","title":"큰 소리와 작은 소리","text":"소리의 크고 작은 정도를 소리의 세기라고 해요. 북을 세게 치면 북 위의 종이 조각이 높이 튀고 큰 소리가 나요. 약하게 치면 종이 조각이 낮게 튀고 작은 소리가 나요. 곧, 물체가 크게 떨릴수록 큰 소리가 나고, 작게 떨릴수록 작은 소리가 나요. 치는 힘 · 떨림 · 소리 세게 · 크","keywords":["떨림","소리의 세기"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-e3","unit":"sci-e3-08","grade":"e3"},
{"id":"sci-e3-08#c2","kind":"concept","title":"높은 소리와 낮은 소리","text":"소리의 높고 낮은 정도를 소리의 높낮이라고 해요. 높낮이는 소리의 크기와는 달라요. 작은 소리도 높을 수 있고, 큰 소리도 낮을 수 있어요. 물체의 길이와 굵기에 따라 소리의 높낮이가 달라져요. 길이: 실로폰은 짧은 음판을 치면 높은 소리, 긴 음판을 치면 낮은 소리가 나요. 빨대 피리","keywords":["소리의 높낮이"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-e3","unit":"sci-e3-08","grade":"e3"},
{"id":"sci-e3-08#c3","kind":"concept","title":"소리는 여러 물질을 통해 전달돼요","text":"소리는 물체의 떨림이 둘레의 물질을 타고 전해져서 우리 귀에 들려요. 소리는 기체, 액체, 고체를 통해 모두 전달돼요. 전달하는 물질 · 예 기체(공기) · 친구의 말소리가 공기를 통해 귀에 들려요 액체(물) · 물속에 귀를 담그고 있어도 물속에서 두드리는 소리가 들려요 고체 · 책상에","keywords":["떨림","실 전화"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-e3","unit":"sci-e3-08","grade":"e3"},
{"id":"sci-e3-08#c4","kind":"concept","title":"소음을 줄여요","text":"듣기 싫거나 너무 커서 생활에 방해가 되는 소리를 소음이라고 해요. 공사장 소리, 큰 자동차 경적, 아파트 위층에서 쿵쿵 뛰는 소리 같은 것이에요. 소음을 오래 들으면 짜증이 나고, 공부에 집중하기 어렵고, 귀가 나빠질 수도 있어요. 소음은 이렇게 줄일 수 있어요. 소리가 나는 곳에서 ","keywords":["소음","방음벽"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-e3","unit":"sci-e3-08","grade":"e3"},
{"id":"sci-e3-08#t0","kind":"term","title":"떨림","text":"물체가 빠르게 흔들리는 것이에요. 소리가 나는 물체는 모두 떨려요.","keywords":["떨림"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-08","grade":"e3"},
{"id":"sci-e3-08#t1","kind":"term","title":"소리의 세기","text":"소리가 크고 작은 정도예요. 물체가 크게 떨릴수록 큰 소리가 나요.","keywords":["소리의 세기"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-e3","unit":"sci-e3-08","grade":"e3"},
{"id":"sci-e3-08#t2","kind":"term","title":"소리의 높낮이","text":"소리가 높고 낮은 정도예요. 예: 실로폰의 짧은 음판은 높은 소리, 긴 음판은 낮은 소리가 나요.","keywords":["소리의 높낮이"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-e3","unit":"sci-e3-08","grade":"e3"},
{"id":"sci-e3-08#t3","kind":"term","title":"실 전화","text":"두 종이컵을 실로 이어 만든 장난감 전화예요. 컵의 떨림이 팽팽한 실을 타고 전해져요.","keywords":["실 전화"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-e3","unit":"sci-e3-08","grade":"e3"},
{"id":"sci-e3-08#t4","kind":"term","title":"소음","text":"듣기 싫거나 너무 커서 생활에 방해가 되는 소리예요. 예: 공사장 소리, 위층에서 뛰는 소리","keywords":["소음"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-e3","unit":"sci-e3-08","grade":"e3"},
{"id":"sci-e3-08#t5","kind":"term","title":"방음벽","text":"도로나 기찻길 옆에 세워 소음이 사는 곳으로 넘어오지 않도록 막는 벽이에요.","keywords":["방음벽"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-e3","unit":"sci-e3-08","grade":"e3"},
{"id":"sci-e3-08#f0","kind":"faq","title":"소리의 크기와 높낮이는 어떻게 달라요?","text":"소리의 크기(세기)는 \"얼마나 크게 들리나\", 높낮이는 \"얼마나 높게(가늘게) 들리나\"예요. 같은 실로폰 음판을 세게 치면 크기만 커지고 높낮이는 그대로예요. 다른 길이의 음판을 치면 높낮이가 달라져요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-08","grade":"e3"},
{"id":"sci-e3-08#f1","kind":"faq","title":"왜 짧은 음판은 높은 소리가 나요?","text":"짧은 음판은 긴 음판보다 더 빠르게 떨려요. 물체가 빠르게 떨릴수록 높은 소리가 나요. 그래서 짧고 가는 것은 높은 소리, 길고 굵은 것은 낮은 소리가 나요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-e3","unit":"sci-e3-08","grade":"e3"},
{"id":"sci-e3-08#f2","kind":"faq","title":"위층에서 뛰는 소리는 왜 아래층에 잘 들려요?","text":"뛰는 발이 바닥을 두드리면 떨림이 생기고, 이 떨림이 바닥과 벽 같은 고체를 타고 아래층까지 잘 전해지기 때문이에요. 집 안에서 조용히 걷고 바닥에 매트를 깔면 소음을 줄일 수 있어요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-e3","unit":"sci-e3-08","grade":"e3"},
{"id":"sci-e3-08#m0","kind":"mistake","title":"자주 하는 실수","text":"큰 소리와 높은 소리를 같은 것으로 생각하는 실수 — 크기(세기)는 떨림의 크기, 높낮이는 물체의 길이·굵기에 따라 달라져요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e3","unit":"sci-e3-08","grade":"e3"},
{"id":"sci-e3-08#m1","kind":"mistake","title":"자주 하는 실수","text":"소리는 공기를 통해서만 전달된다고 생각하는 실수 — 물(액체)과 책상·실(고체)을 통해서도 전달돼요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e3","unit":"sci-e3-08","grade":"e3"},
{"id":"sci-e3-08#m2","kind":"mistake","title":"자주 하는 실수","text":"실로폰의 긴 음판이 높은 소리를 낸다고 생각하는 실수 — 짧은 음판이 높은 소리, 긴 음판이 낮은 소리를 내요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e3","unit":"sci-e3-08","grade":"e3"},
{"id":"sci-e3-09","kind":"unit","title":"감염병과 건강한 생활","text":"다른 사람에게 옮는 감염병의 예와 퍼지는 과정을 알고, 감염병을 막는 건강한 생활 습관을 익혀요. 감염병의 뜻을 알고 생활 속 감염병의 예를 말할 수 있어요. 감염병이 사람에게서 사람에게로 옮는 여러 과정을 설명할 수 있어요. 올바른 손 씻기, 기침 예절 같은 감염병 예방 수칙을 실천할 수 있어요.","keywords":["감염병","유행","침방울","환기","기침 예절","예방 접종","예방 수칙"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-09","grade":"e3"},
{"id":"sci-e3-09#c0","kind":"concept","title":"감염병이란?","text":"감염병은 눈에 보이지 않을 만큼 아주 작은 세균이나 바이러스 같은 것이 몸속에 들어와 생기는 병 가운데, 다른 사람에게 옮을 수 있는 병이에요. 우리 생활에서 볼 수 있는 감염병에는 이런 것이 있어요. 감염병 · 이런 모습이 나타나요 감기 · 콧물, 기침, 목이 아파요 독감 · 갑자기 ","keywords":["감염병","유행"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-09","grade":"e3"},
{"id":"sci-e3-09#c1","kind":"concept","title":"감염병이 옮는 여러 길","text":"감염병을 일으키는 아주 작은 것들은 여러 길로 다른 사람에게 옮아 가요. 손: 병균이 묻은 손으로 눈·코·입을 만지거나, 그 손으로 문손잡이를 만지면 다음 사람에게 옮아요. 침방울: 기침이나 재채기를 하면 작은 침방울이 튀어 가까이 있는 사람에게 옮아요. 공기: 어떤 감염병(예: 수두)","keywords":["감염병","침방울"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-e3","unit":"sci-e3-09","grade":"e3"},
{"id":"sci-e3-09#c2","kind":"concept","title":"생활 습관과 감염병의 유행","text":"감염병이 많은 사람에게 빠르게 퍼지는 것을 유행이라고 해요. 감염병이 유행하는 데에는 우리의 생활 습관이 큰 영향을 줘요. 손을 씻지 않으면: 손에 묻은 병균이 눈·코·입으로 들어가거나, 함께 만지는 물건을 통해 여러 사람에게 퍼져요. 환기를 하지 않으면: 창문을 닫아 둔 교실에 사람이","keywords":["감염병","유행","침방울","환기"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-e3","unit":"sci-e3-09","grade":"e3"},
{"id":"sci-e3-09#c3","kind":"concept","title":"물감으로 확인하는 손 씻기","text":"손을 씻었는데도 병균이 남아 있을 수 있어요. 물감으로 내가 손을 잘 씻는지 확인해 볼 수 있어요. 물에 잘 씻기는 물감을 손 전체에 고루 바르고 말려요. (물감은 병균 대신이에요.) 평소에 하던 대로 손을 씻어요. 물감이 남아 있는 곳을 찾아봐요. 보통 엄지손가락, 손가락 사이, 손톱","keywords":[],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-e3","unit":"sci-e3-09","grade":"e3"},
{"id":"sci-e3-09#c4","kind":"concept","title":"감염병 예방 수칙","text":"감염병을 막으려면 이런 예방 수칙을 지켜요. 수칙 · 이렇게 해요 올바른 손 씻기 · 밖에 다녀온 뒤, 밥 먹기 전, 화장실에 다녀온 뒤 비누로 30초 이상 씻어요 기침 예절 · 기침이나 재채기를 할 때 휴지나 옷소매로 입과 코를 가려요 예방 접종 · 정해진 때에 예방 주사를 맞아요(예","keywords":["감염병","기침 예절","예방 접종","예방 수칙"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-e3","unit":"sci-e3-09","grade":"e3"},
{"id":"sci-e3-09#t0","kind":"term","title":"감염병","text":"세균이나 바이러스 같은 아주 작은 것이 몸에 들어와 생기는 병 가운데, 다른 사람에게 옮을 수 있는 병이에요. 예: 감기, 독감, 수두","keywords":["감염병"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-09","grade":"e3"},
{"id":"sci-e3-09#t1","kind":"term","title":"유행","text":"감염병이 짧은 시간에 많은 사람에게 퍼지는 것이에요.","keywords":["유행"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-e3","unit":"sci-e3-09","grade":"e3"},
{"id":"sci-e3-09#t2","kind":"term","title":"침방울","text":"기침이나 재채기, 말을 할 때 입에서 튀어나오는 아주 작은 침 덩어리예요.","keywords":["침방울"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-e3","unit":"sci-e3-09","grade":"e3"},
{"id":"sci-e3-09#t3","kind":"term","title":"환기","text":"창문을 열어 방 안의 공기를 바깥의 신선한 공기로 바꾸는 것이에요.","keywords":["환기"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-e3","unit":"sci-e3-09","grade":"e3"},
{"id":"sci-e3-09#t4","kind":"term","title":"기침 예절","text":"기침이나 재채기를 할 때 휴지나 옷소매로 입과 코를 가리는 것이에요.","keywords":["기침 예절"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-e3","unit":"sci-e3-09","grade":"e3"},
{"id":"sci-e3-09#t5","kind":"term","title":"예방 접종","text":"감염병에 잘 걸리지 않도록 미리 예방 주사를 맞는 것이에요. 예: 독감 예방 접종","keywords":["예방 접종"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-e3","unit":"sci-e3-09","grade":"e3"},
{"id":"sci-e3-09#t6","kind":"term","title":"예방 수칙","text":"병에 걸리지 않도록 지켜야 할 약속이에요.","keywords":["예방 수칙"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-e3","unit":"sci-e3-09","grade":"e3"},
{"id":"sci-e3-09#f0","kind":"faq","title":"손은 꼭 30초 이상 씻어야 해요?","text":"네. 물로만 잠깐 헹구면 손에 묻은 병균이 많이 남아요. 비누 거품을 내서 손바닥, 손등, 손가락 사이, 엄지, 손톱 밑까지 구석구석 30초 이상 문질러야 병균을 잘 없앨 수 있어요. 마음속으로 천천히 30까지 세면서 문질러 보세요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-e3","unit":"sci-e3-09","grade":"e3"},
{"id":"sci-e3-09#f1","kind":"faq","title":"기침할 때 왜 손으로 막으면 안 돼요?","text":"손바닥으로 막으면 침방울이 손에 묻어요. 그 손으로 문손잡이나 책상, 친구 손을 만지면 병균이 다른 사람에게 옮아요. 휴지로 가리고 휴지는 쓰레기통에 버린 뒤 손을 씻어요. 휴지가 없으면 옷소매 안쪽으로 가려요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-e3","unit":"sci-e3-09","grade":"e3"},
{"id":"sci-e3-09#f2","kind":"faq","title":"감기는 왜 겨울에 더 많이 걸려요?","text":"추운 날에는 창문을 닫고 사람들이 실내에 모여 있는 시간이 길어져요. 환기가 잘 안 되는 곳에 여러 사람이 가까이 있으면 감염병이 옮기 쉬워요. 그래서 추운 날에도 쉬는 시간마다 잠깐씩 창문을 열어 환기하는 것이 좋아요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-e3","unit":"sci-e3-09","grade":"e3"},
{"id":"sci-e3-09#m0","kind":"mistake","title":"자주 하는 실수","text":"물로만 잠깐 헹구면 손이 깨끗해진다고 생각하는 실수 — 비누로 30초 이상, 엄지와 손톱 밑까지 구석구석 씻어야 해요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e3","unit":"sci-e3-09","grade":"e3"},
{"id":"sci-e3-09#m1","kind":"mistake","title":"자주 하는 실수","text":"기침할 때 손바닥으로 입을 막는 실수 — 휴지나 옷소매 안쪽으로 가려야 손에 병균이 묻지 않아요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e3","unit":"sci-e3-09","grade":"e3"},
{"id":"sci-e3-09#m2","kind":"mistake","title":"자주 하는 실수","text":"예방 접종을 하면 어떤 병에도 걸리지 않는다고 생각하는 실수 — 정해진 감염병의 위험을 줄여 줄 뿐이니 다른 예방 수칙도 함께 지켜요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e3","unit":"sci-e3-09","grade":"e3"},
{"id":"sci-e4-01","kind":"unit","title":"자석의 이용","text":"자석에 붙는 물체와 자석의 극을 알아보고, 나침반의 원리와 자석을 이용한 편리한 장치를 배워요. 자석에 붙는 물체와 붙지 않는 물체를 나눌 수 있어요. 자석의 두 극과 극끼리 밀고 당기는 성질을 설명할 수 있어요. 자석이 남북을 가리키는 성질을 이용해 나침반을 쓸 수 있어요. 생활 속 자석의 쓰임을 찾고, 자석을 이용한 장치를 생각해 낼 수 있어요.","keywords":["자석","자석의 극","N극","S극","나침반","방위","철"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e4","unit":"sci-e4-01","grade":"e4"},
{"id":"sci-e4-01#c0","kind":"concept","title":"자석에 붙는 물체","text":"여러 물체에 자석을 대 보면 붙는 것과 붙지 않는 것이 있어요. 자석에 붙는 물체는 철로 만들어졌다는 공통점이 있어요. 자석에 붙는 물체 · 자석에 붙지 않는 물체 철 클립, 철못, 철사, 옷핀 · 지우개, 나무젓가락, 유리컵, 플라스틱 자 통조림 철 캔 · 알루미늄 캔, 구리선, 종이","keywords":["자석","철"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e4","unit":"sci-e4-01","grade":"e4"},
{"id":"sci-e4-01#c1","kind":"concept","title":"자석의 두 극","text":"막대자석을 클립이 담긴 상자에 넣었다가 꺼내면 클립이 양쪽 끝에 많이 붙고 가운데에는 거의 붙지 않아요. 자석에서 철을 끌어당기는 힘이 가장 센 부분을 자석의 극이라고 해요. 자석의 극은 두 개예요. 하나는 N극, 다른 하나는 S극이라고 해요. 막대자석은 양쪽 끝이 극이에요. 💡 자석","keywords":["자석","자석의 극","N극","S극","철"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-e4","unit":"sci-e4-01","grade":"e4"},
{"id":"sci-e4-01#c2","kind":"concept","title":"떨어져 있어도, 사이에 물건이 있어도","text":"자석은 철로 된 물체에 닿지 않아도 끌어당길 수 있어요. 자석을 클립 가까이 가져가면 클립이 자석 쪽으로 끌려와요. 또 자석과 철 사이에 종이, 얇은 플라스틱 판, 유리 같은 물체가 있어도 자석은 철을 끌어당겨요. 냉장고 문에 종이를 끼우고 자석으로 붙여 둘 수 있는 것도 이 때문이에요","keywords":["자석","철"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-e4","unit":"sci-e4-01","grade":"e4"},
{"id":"sci-e4-01#c3","kind":"concept","title":"같은 극은 밀고, 다른 극은 당겨요","text":"자석 두 개를 가까이 가져가 보면 서로 끌어당기기도 하고 밀어내기도 해요. 같은 극끼리(N극과 N극, S극과 S극)는 서로 밀어내요. 다른 극끼리(N극과 S극)는 서로 끌어당겨요. 그래서 극 표시가 있는 자석을 이용하면, 다른 자석의 극이 무엇인지도 알아낼 수 있어요. N극에 끌려오는 ","keywords":["자석","자석의 극","N극","S극"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-e4","unit":"sci-e4-01","grade":"e4"},
{"id":"sci-e4-01#c4","kind":"concept","title":"남북을 가리키는 자석과 나침반","text":"막대자석을 물에 띄운 그릇에 올려놓거나 실에 매달아 자유롭게 움직이게 하면, 자석은 이리저리 돌다가 늘 같은 방향에서 멈춰요. 이때 N극은 북쪽, S극은 남쪽을 가리켜요. 나침반은 이 성질을 이용한 도구예요. 나침반 바늘은 작은 자석이라서, 바늘의 N극이 북쪽을 가리켜요. 바늘의 N극은","keywords":["자석","N극","S극","나침반","방위","철"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-e4","unit":"sci-e4-01","grade":"e4"},
{"id":"sci-e4-01#c5","kind":"concept","title":"생활 속 자석과 편리한 장치","text":"우리 주변에는 자석을 이용한 물건이 많아요. 냉장고 문: 문 가장자리 고무 속에 자석이 있어 철로 된 냉장고 몸체에 착 붙어 꼭 닫혀요. 자석 필통·가방 덮개: 뚜껑이 저절로 딱 붙어 잘 닫혀요. 자석 칠판·메모꽂이: 철판으로 된 칠판에 종이를 자석으로 붙여요. 자석 드라이버: 끝이 자","keywords":["자석","철"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-e4","unit":"sci-e4-01","grade":"e4"},
{"id":"sci-e4-01#t0","kind":"term","title":"자석","text":"철로 된 물체를 끌어당기는 성질이 있는 물체예요. 막대자석, 원형 자석, 고리 자석처럼 모양이 여러 가지예요.","keywords":["자석"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-e4","unit":"sci-e4-01","grade":"e4"},
{"id":"sci-e4-01#t1","kind":"term","title":"자석의 극","text":"자석에서 철을 끌어당기는 힘이 가장 센 부분이에요. 막대자석은 양쪽 끝이 극이에요.","keywords":["자석의 극"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-e4","unit":"sci-e4-01","grade":"e4"},
{"id":"sci-e4-01#t2","kind":"term","title":"N극","text":"자석의 두 극 가운데 하나로, 자석을 자유롭게 움직이게 하면 북쪽을 가리키는 극이에요.","keywords":["N극"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-e4","unit":"sci-e4-01","grade":"e4"},
{"id":"sci-e4-01#t3","kind":"term","title":"S극","text":"자석의 두 극 가운데 하나로, 자석을 자유롭게 움직이게 하면 남쪽을 가리키는 극이에요.","keywords":["S극"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-e4","unit":"sci-e4-01","grade":"e4"},
{"id":"sci-e4-01#t4","kind":"term","title":"나침반","text":"자석으로 된 바늘이 남북을 가리키는 성질을 이용해 방향을 알려 주는 도구예요.","keywords":["나침반"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-e4","unit":"sci-e4-01","grade":"e4"},
{"id":"sci-e4-01#t5","kind":"term","title":"방위","text":"동쪽·서쪽·남쪽·북쪽처럼 어느 쪽인지를 나타내는 방향이에요.","keywords":["방위"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-e4","unit":"sci-e4-01","grade":"e4"},
{"id":"sci-e4-01#t6","kind":"term","title":"철","text":"자석에 붙는 대표적인 금속이에요. 클립, 못, 철사, 통조림 캔 등을 만들 때 써요.","keywords":["철"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-e4","unit":"sci-e4-01","grade":"e4"},
{"id":"sci-e4-01#f0","kind":"faq","title":"금속은 다 자석에 붙지 않나요?","text":"아니에요. 알루미늄 캔, 구리선처럼 자석에 붙지 않는 금속도 많아요. 우리 주변에서 자석에 붙는 물체는 대부분 철로 만든 물체예요.","keywords":["자석"],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-e4","unit":"sci-e4-01","grade":"e4"},
{"id":"sci-e4-01#f1","kind":"faq","title":"자석은 왜 북쪽을 가리켜요?","text":"지구가 하나의 큰 자석처럼 행동하기 때문이에요. 자유롭게 움직일 수 있는 자석은 지구의 자석 힘을 받아 N극이 북쪽, S극이 남쪽을 향하며 멈춰요.","keywords":["자석"],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-e4","unit":"sci-e4-01","grade":"e4"},
{"id":"sci-e4-01#f2","kind":"faq","title":"자석에 붙어 있는 클립에 다른 클립이 또 붙는 건 왜 그래요?","text":"자석에 붙어 있는 동안 클립도 잠깐 자석처럼 되기 때문이에요. 그래서 다른 클립을 끌어당겨 줄줄이 매달려요. 자석에서 떼어 내면 그 힘은 대부분 금방 약해져요.","keywords":["자석"],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-e4","unit":"sci-e4-01","grade":"e4"},
{"id":"sci-e4-01#f3","kind":"faq","title":"자석을 반으로 자르면 N극과 S극으로 나뉘나요?","text":"아니에요. 자른 조각마다 새로 N극과 S극이 생겨 작은 자석 두 개가 돼요. N극만 있거나 S극만 있는 자석은 만들 수 없어요.","keywords":["자석","N극","S극"],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-e4","unit":"sci-e4-01","grade":"e4"},
{"id":"sci-e4-01#m0","kind":"mistake","title":"자주 하는 실수","text":"\"금속이면 모두 자석에 붙는다\"고 생각하는 실수 — 알루미늄·구리는 금속이지만 붙지 않아요. 자석에 붙는 것은 철로 된 물체예요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e4","unit":"sci-e4-01","grade":"e4"},
{"id":"sci-e4-01#m1","kind":"mistake","title":"자주 하는 실수","text":"막대자석은 가운데가 가장 세다고 생각하는 실수 — 힘이 가장 센 곳은 양쪽 끝(극)이고, 가운데는 가장 약해요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e4","unit":"sci-e4-01","grade":"e4"},
{"id":"sci-e4-01#m2","kind":"mistake","title":"자주 하는 실수","text":"자석이나 철 가까이에서 나침반을 읽는 실수 — 바늘이 그쪽으로 끌려가 방위가 틀려요. 자석·철에서 떨어진 곳에서 써요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e4","unit":"sci-e4-01","grade":"e4"},
{"id":"sci-e4-02","kind":"unit","title":"물의 상태 변화","text":"물이 얼음과 수증기로 변하는 모습을 관찰하고, 얼고 녹고 증발하고 끓고 응결할 때의 변화를 알아봐요. 물의 세 가지 상태를 알고 주변에서 예를 찾을 수 있어요. 물이 얼거나 얼음이 녹을 때 부피와 무게가 어떻게 변하는지 설명할 수 있어요. 증발과 끓음의 같은 점과 다른 점, 응결을 설명할 수 있어요. 물의 상태 변화를 이용해 물을 얻는 장치를 생각해 낼 …","keywords":["수증기","부피","증발","끓음","응결","고체·액체·기체","김"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e4","unit":"sci-e4-02","grade":"e4"},
{"id":"sci-e4-02#c0","kind":"concept","title":"물의 세 가지 상태","text":"물은 세 가지 상태로 있을 수 있어요. 상태 · 모습 · 예 얼음 · 단단하고 모양이 일정해요. · 냉동실 얼음, 고드름 물 · 흐르고, 담는 그릇에 따라 모양이 바뀌어요. · 수돗물, 빗물 수증기 · 눈에 보이지 않고 공기 중에 퍼져 있어요. · 빨래가 마를 때 공기 중으로 날아간 물","keywords":["수증기","김"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e4","unit":"sci-e4-02","grade":"e4"},
{"id":"sci-e4-02#c1","kind":"concept","title":"물이 얼 때와 얼음이 녹을 때","text":"물을 얼리면 부피(차지하는 공간의 크기)는 늘어나고, 무게는 변하지 않아요. 얼음이 녹으면 부피는 줄어들고, 무게는 변하지 않아요. · 부피 · 무게 물이 얼 때 · 늘어나요 · 그대로예요 얼음이 녹을 때 · 줄어들어요 · 그대로예요 물의 양 자체는 늘거나 줄지 않고 모습만 바뀌기 때문","keywords":["부피"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-e4","unit":"sci-e4-02","grade":"e4"},
{"id":"sci-e4-02#c2","kind":"concept","title":"증발","text":"물이 담긴 그릇을 며칠 두면 물의 양이 조금씩 줄어들어요. 물이 표면에서 수증기로 변해 공기 중으로 흩어졌기 때문이에요. 이렇게 물의 표면에서 물이 수증기로 변하는 현상을 증발이라고 해요. 증발은 천천히 일어나서 눈으로 바로 보이지 않아요. 우리 주변의 예를 찾아볼까요? 젖은 빨래가 말","keywords":["수증기","증발"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-e4","unit":"sci-e4-02","grade":"e4"},
{"id":"sci-e4-02#c3","kind":"concept","title":"끓음, 그리고 증발과 비교하기","text":"물을 가열하면 물속에서 커다란 기포(거품)가 생겨 물 표면으로 올라와 터져요. 이렇게 물의 표면과 물속에서 물이 수증기로 변하는 현상을 끓음이라고 해요. 끓을 때 생기는 기포는 공기가 아니라 수증기예요. · 증발 · 끓음 같은 점 · 물이 수증기로 변해요 · 물이 수증기로 변해요 어디에","keywords":["수증기","증발","끓음","김"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-e4","unit":"sci-e4-02","grade":"e4"},
{"id":"sci-e4-02#c4","kind":"concept","title":"응결","text":"얼음물을 담은 컵을 두면 컵 겉면에 물방울이 맺혀요. 공기 중의 수증기가 차가운 컵 표면에 닿아 물방울로 변했기 때문이에요. 이렇게 기체인 수증기가 액체인 물로 변하는 현상을 응결이라고 해요. ⚠️ 컵 겉면의 물방울은 컵 안의 물이 스며 나온 것이 아니에요. 컵 안에 색깔 물을 넣어도 ","keywords":["수증기","응결"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-e4","unit":"sci-e4-02","grade":"e4"},
{"id":"sci-e4-02#c5","kind":"concept","title":"물의 상태 변화를 이용해 물을 얻는 장치","text":"마실 물이 부족한 곳에서는 물의 상태 변화를 이용해 깨끗한 물을 얻는 장치를 생각해 볼 수 있어요. 증발과 응결을 함께 이용해요. 장치의 원리 (예) 넓은 그릇에 흙탕물이나 바닷물을 담고, 가운데에 빈 컵을 놓아요. 그릇 위를 투명한 비닐로 덮고, 비닐 가운데에 작은 돌을 올려 오목하게","keywords":["수증기","증발","응결"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-e4","unit":"sci-e4-02","grade":"e4"},
{"id":"sci-e4-02#t0","kind":"term","title":"수증기","text":"기체 상태의 물이에요. 눈에 보이지 않고 공기 중에 퍼져 있어요.","keywords":["수증기"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-e4","unit":"sci-e4-02","grade":"e4"},
{"id":"sci-e4-02#t1","kind":"term","title":"부피","text":"물체가 차지하는 공간의 크기예요. 물이 얼면 부피가 늘어나요.","keywords":["부피"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-e4","unit":"sci-e4-02","grade":"e4"},
{"id":"sci-e4-02#t2","kind":"term","title":"증발","text":"물의 표면에서 물이 수증기로 변하는 현상이에요. 예: 젖은 빨래가 말라요.","keywords":["증발"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-e4","unit":"sci-e4-02","grade":"e4"},
{"id":"sci-e4-02#t3","kind":"term","title":"끓음","text":"물의 표면과 물속에서 물이 수증기로 변하는 현상이에요. 물속에서 기포가 생기고, 물이 빠르게 줄어요.","keywords":["끓음"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-e4","unit":"sci-e4-02","grade":"e4"},
{"id":"sci-e4-02#t4","kind":"term","title":"응결","text":"기체인 수증기가 차가운 물체 표면 등에서 액체인 물로 변하는 현상이에요. 예: 차가운 컵 겉면의 물방울.","keywords":["응결"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-e4","unit":"sci-e4-02","grade":"e4"},
{"id":"sci-e4-02#t5","kind":"term","title":"고체·액체·기체","text":"물질의 세 가지 상태예요. 얼음은 고체, 물은 액체, 수증기는 기체예요.","keywords":["고체·액체·기체"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-e4","unit":"sci-e4-02","grade":"e4"},
{"id":"sci-e4-02#t6","kind":"term","title":"김","text":"주전자나 냄비에서 나오는 하얀 연기 같은 것으로, 수증기가 식어서 생긴 아주 작은 물방울이에요.","keywords":["김"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-e4","unit":"sci-e4-02","grade":"e4"},
{"id":"sci-e4-02#f0","kind":"faq","title":"주전자에서 나오는 하얀 김은 수증기 아니에요?","text":"아니에요. 수증기는 눈에 보이지 않아요. 주전자 입구 바로 앞을 자세히 보면 아무것도 안 보이는 틈이 있는데, 거기에 수증기가 있어요. 그 수증기가 조금 떨어진 곳에서 식어 아주 작은 물방울이 된 것이 하얀 김이에요.","keywords":["수증기","김"],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-e4","unit":"sci-e4-02","grade":"e4"},
{"id":"sci-e4-02#f1","kind":"faq","title":"차가운 컵 겉면의 물방울은 컵 안의 물이 새어 나온 거예요?","text":"아니에요. 공기 중의 수증기가 차가운 컵에 닿아 응결한 것이에요. 컵 안에 색깔 물을 넣어 보면 겉면의 물방울은 색이 없어서 컵 안의 물이 아니라는 것을 알 수 있어요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-e4","unit":"sci-e4-02","grade":"e4"},
{"id":"sci-e4-02#f2","kind":"faq","title":"물이 얼면 왜 무게는 그대로예요?","text":"물이 얼음이 될 때 물이 새로 생기거나 없어지지 않기 때문이에요. 모습만 바뀌고 양은 그대로라서 무게도 같아요. 다만 얼음이 되면서 더 넓은 자리를 차지해 부피는 늘어나요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-e4","unit":"sci-e4-02","grade":"e4"},
{"id":"sci-e4-02#f3","kind":"faq","title":"물이 끓을 때 나오는 거품은 공기예요?","text":"끓을 때 계속 생겨 올라오는 큰 기포는 물이 변한 수증기예요. 물을 데우기 시작할 때 그릇 벽에 붙는 작은 거품 가운데에는 물에 녹아 있던 공기도 있어요.","keywords":[],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-e4","unit":"sci-e4-02","grade":"e4"},
{"id":"sci-e4-02#m0","kind":"mistake","title":"자주 하는 실수","text":"물이 얼면 무게가 늘어난다고 생각하는 실수 — 늘어나는 것은 부피이고, 무게는 그대로예요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e4","unit":"sci-e4-02","grade":"e4"},
{"id":"sci-e4-02#m1","kind":"mistake","title":"자주 하는 실수","text":"하얀 김을 수증기라고 하는 실수 — 수증기는 보이지 않아요. 김은 수증기가 식어서 생긴 작은 물방울이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e4","unit":"sci-e4-02","grade":"e4"},
{"id":"sci-e4-02#m2","kind":"mistake","title":"자주 하는 실수","text":"차가운 컵 겉면의 물방울이 컵 안에서 새어 나왔다고 생각하는 실수 — 공기 중의 수증기가 응결한 것이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e4","unit":"sci-e4-02","grade":"e4"},
{"id":"sci-e4-03","kind":"unit","title":"땅의 변화","text":"흐르는 물이 땅을 깎고 옮기고 쌓는 작용과 화산·지진이 일어나는 모습, 우리 생활에 주는 영향을 알아봐요. 흐르는 물의 침식·운반·퇴적 작용을 설명하고 강 상류와 하류의 모습을 비교할 수 있어요. 화산의 뜻과 화산 분출물을 알고, 현무암과 화강암을 비교할 수 있어요. 화산 활동과 지진이 우리 생활에 주는 영향을 말할 수 있어요. 지진이 났을 때 안전하게 …","keywords":["침식","운반","퇴적","화산","마그마","용암","화성암","현무암","화강암","지진"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e4","unit":"sci-e4-03","grade":"e4"},
{"id":"sci-e4-03#c0","kind":"concept","title":"흐르는 물이 하는 일: 침식·운반·퇴적","text":"흐르는 물은 땅의 모습을 바꿔요. 흐르는 물이 하는 일은 세 가지예요. 침식: 흐르는 물이 땅을 깎는 작용 운반: 깎인 흙이나 돌을 옮기는 작용 퇴적: 옮겨 온 흙이나 돌을 쌓는 작용 흙 언덕 실험: 흙으로 비스듬한 언덕을 만들고 위쪽에서 물을 천천히 흘려보내면, 언덕 위쪽은 깎이고, ","keywords":["침식","운반","퇴적"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e4","unit":"sci-e4-03","grade":"e4"},
{"id":"sci-e4-03#c1","kind":"concept","title":"강 상류와 하류","text":"강이 시작되는 산 쪽을 상류, 바다와 가까운 쪽을 하류라고 해요. 상류와 하류는 모습이 달라요. · 상류 · 하류 경사 · 급해요 · 완만해요 강폭 · 좁아요 · 넓어요 돌의 크기 · 크고 모난 돌이 많아요 · 작고 둥근 돌, 모래, 진흙이 많아요 활발한 작용 · 침식 · 퇴적 상류에서","keywords":["침식","퇴적"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-e4","unit":"sci-e4-03","grade":"e4"},
{"id":"sci-e4-03#c2","kind":"concept","title":"화산과 화산 분출물","text":"땅속 깊은 곳에서 암석이 녹은 것을 마그마라고 해요. 마그마가 땅 위로 솟아 나와 생긴 지형을 화산이라고 해요. 화산 꼭대기에는 마그마가 나온 곳인 움푹 파인 분화구가 있는 경우가 많아요. 화산과 화산이 아닌 산은 마그마가 분출해 만들어졌는지로 구별해요. 한라산·백두산은 화산이고, 설악","keywords":["화산","마그마","용암"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-e4","unit":"sci-e4-03","grade":"e4"},
{"id":"sci-e4-03#c3","kind":"concept","title":"현무암과 화강암","text":"마그마가 식어서 굳어진 암석을 화성암이라고 해요. 대표적인 화성암이 현무암과 화강암이에요. · 현무암 · 화강암 색 · 어두워요(검은색, 짙은 회색) · 밝아요(흰색·분홍색 바탕에 검은 알갱이) 알갱이 크기 · 매우 작아 맨눈으로 보기 어려워요 · 커서 맨눈으로 보여요 생기는 곳 · 땅","keywords":["마그마","용암","화성암","현무암","화강암"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-e4","unit":"sci-e4-03","grade":"e4"},
{"id":"sci-e4-03#c4","kind":"concept","title":"화산과 지진이 우리 생활에 주는 영향","text":"화산 활동의 피해 용암이 흘러 산불이 나거나 마을과 농작물이 피해를 입어요. 화산재가 하늘을 덮어 비행기가 다니기 어렵고, 사람과 동물이 숨쉬기 힘들어져요. 화산 활동의 이로움 땅속의 열로 데워진 물로 온천을 즐길 수 있어요. 땅속의 열로 전기를 만드는 지열 발전을 할 수 있어요. 화산","keywords":["화산","용암","지진"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-e4","unit":"sci-e4-03","grade":"e4"},
{"id":"sci-e4-03#c5","kind":"concept","title":"지진이 났을 때 이렇게 해요","text":"지진이 나면 당황하지 말고 머리를 보호하는 것이 가장 먼저예요. 흔들리는 동안 (건물 안) 튼튼한 탁자나 책상 아래로 들어가 머리를 보호하고, 탁자 다리를 꼭 잡아요. 창문, 유리, 넘어질 수 있는 가구에서 멀리 떨어져요. 흔들림이 멈추면 문을 열어 나갈 곳을 확보해요. 엘리베이터는 타","keywords":["지진"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-e4","unit":"sci-e4-03","grade":"e4"},
{"id":"sci-e4-03#t0","kind":"term","title":"침식","text":"흐르는 물이 땅의 흙이나 돌을 깎는 작용이에요. 경사가 급한 강 상류에서 활발해요.","keywords":["침식"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-e4","unit":"sci-e4-03","grade":"e4"},
{"id":"sci-e4-03#t1","kind":"term","title":"운반","text":"흐르는 물이 깎인 흙이나 돌을 다른 곳으로 옮기는 작용이에요.","keywords":["운반"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-e4","unit":"sci-e4-03","grade":"e4"},
{"id":"sci-e4-03#t2","kind":"term","title":"퇴적","text":"흐르는 물이 옮겨 온 흙이나 돌을 쌓는 작용이에요. 경사가 완만한 강 하류에서 활발해요.","keywords":["퇴적"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-e4","unit":"sci-e4-03","grade":"e4"},
{"id":"sci-e4-03#t3","kind":"term","title":"화산","text":"땅속의 마그마가 땅 위로 분출해 생긴 지형이에요. 예: 한라산, 백두산","keywords":["화산"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-e4","unit":"sci-e4-03","grade":"e4"},
{"id":"sci-e4-03#t4","kind":"term","title":"마그마","text":"땅속 깊은 곳에서 암석이 녹아 있는 것이에요.","keywords":["마그마"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-e4","unit":"sci-e4-03","grade":"e4"},
{"id":"sci-e4-03#t5","kind":"term","title":"용암","text":"마그마가 땅 위로 흘러나온 것이에요. 화산 분출물 가운데 액체 상태예요.","keywords":["용암"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-e4","unit":"sci-e4-03","grade":"e4"},
{"id":"sci-e4-03#t6","kind":"term","title":"화성암","text":"마그마가 식어서 굳어진 암석이에요. 현무암과 화강암이 대표적이에요.","keywords":["화성암"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-e4","unit":"sci-e4-03","grade":"e4"},
{"id":"sci-e4-03#t7","kind":"term","title":"현무암","text":"색이 어둡고 알갱이가 매우 작은 화성암이에요. 땅 표면 가까이에서 빨리 식어 만들어져요.","keywords":["현무암"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-e4","unit":"sci-e4-03","grade":"e4"},
{"id":"sci-e4-03#t8","kind":"term","title":"화강암","text":"색이 밝고 알갱이가 커서 맨눈으로 보이는 화성암이에요. 땅속 깊은 곳에서 천천히 식어 만들어져요.","keywords":["화강암"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-e4","unit":"sci-e4-03","grade":"e4"},
{"id":"sci-e4-03#t9","kind":"term","title":"지진","text":"땅이 흔들리거나 갈라지는 현상이에요.","keywords":["지진"],"ref":{"tab":"terms","idx":9},"subject":"sci","course":"sci-e4","unit":"sci-e4-03","grade":"e4"},
{"id":"sci-e4-03#f0","kind":"faq","title":"마그마랑 용암은 뭐가 달라요?","text":"둘 다 암석이 녹은 것이에요. 땅속에 있을 때는 마그마, 땅 위로 흘러나오면 용암이라고 불러요.","keywords":["마그마","용암"],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-e4","unit":"sci-e4-03","grade":"e4"},
{"id":"sci-e4-03#f1","kind":"faq","title":"한라산이랑 백두산은 화산이에요?","text":"네, 둘 다 마그마가 분출해서 만들어진 화산이에요. 한라산 꼭대기의 백록담, 백두산 꼭대기의 천지는 화산과 관련된 움푹한 곳에 물이 고인 호수예요.","keywords":["화산"],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-e4","unit":"sci-e4-03","grade":"e4"},
{"id":"sci-e4-03#f2","kind":"faq","title":"지진이 나면 바로 밖으로 뛰어나가야 해요?","text":"아니에요. 흔들리는 동안 뛰어나가면 넘어지거나 떨어지는 물건에 다치기 쉬워요. 흔들리는 동안에는 탁자 아래에서 머리를 보호하고, 흔들림이 멈춘 뒤 계단으로 나가 넓은 곳으로 대피해요.","keywords":["지진"],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-e4","unit":"sci-e4-03","grade":"e4"},
{"id":"sci-e4-03#f3","kind":"faq","title":"강 하류에는 왜 둥근 돌이 많아요?","text":"상류에서 깎여 나온 모난 돌이 물에 실려 내려가는 동안 서로 부딪히고 깎여서 둥글고 작아지기 때문이에요.","keywords":[],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-e4","unit":"sci-e4-03","grade":"e4"},
{"id":"sci-e4-03#m0","kind":"mistake","title":"자주 하는 실수","text":"마그마와 용암을 같은 말로 쓰는 실수 — 땅속에 있으면 마그마, 땅 위로 흘러나오면 용암이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e4","unit":"sci-e4-03","grade":"e4"},
{"id":"sci-e4-03#m1","kind":"mistake","title":"자주 하는 실수","text":"상류와 하류의 모습을 거꾸로 기억하는 실수 — 상류는 경사가 급하고 강폭이 좁으며 큰 돌이 많고, 하류는 경사가 완만하고 강폭이 넓으며 모래가 많아요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e4","unit":"sci-e4-03","grade":"e4"},
{"id":"sci-e4-03#m2","kind":"mistake","title":"자주 하는 실수","text":"지진이 나자마자 밖으로 뛰어나가거나 엘리베이터를 타는 실수 — 흔들리는 동안에는 머리를 보호하고, 멈춘 뒤 계단으로 대피해요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e4","unit":"sci-e4-03","grade":"e4"},
{"id":"sci-e4-04","kind":"unit","title":"다양한 생물과 우리 생활","text":"버섯·곰팡이 같은 균류, 짚신벌레 같은 원생생물, 세균의 특징을 알고 우리 생활에 주는 영향을 알아봐요. 균류(버섯·곰팡이)의 생김새와 사는 곳을 설명할 수 있어요. 원생생물(짚신벌레·해캄)과 세균의 특징과 사는 곳을 설명할 수 있어요. 균류·원생생물·세균이 우리 생활에 주는 이로운 영향과 해로운 영향을 말할 수 있어요. 생명과학을 생활에 이용하는 예를 …","keywords":["균류","균사","포자","원생생물","세균","발효","생물 농약","생명과학","적조"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e4","unit":"sci-e4-04","grade":"e4"},
{"id":"sci-e4-04#c0","kind":"concept","title":"균류: 버섯과 곰팡이","text":"버섯과 곰팡이처럼 몸이 가늘고 긴 실 모양의 균사로 이루어진 생물을 균류라고 해요. 버섯: 위쪽에 우산 같은 갓이 있고, 갓 아래에는 주름이 있으며, 아래에는 갓을 받치는 자루가 있어요. 곰팡이: 가는 실 같은 균사가 거미줄처럼 얽혀 있고, 균사 끝에 작고 둥근 알갱이가 달려 있어요. ","keywords":["균류","균사","포자"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e4","unit":"sci-e4-04","grade":"e4"},
{"id":"sci-e4-04#c1","kind":"concept","title":"원생생물: 짚신벌레와 해캄","text":"동물, 식물, 균류로 나누기 어렵고 생김새가 단순한 생물을 원생생물이라고 해요. 원생생물은 대부분 논, 연못, 도랑처럼 물이 고인 곳이나 물살이 느린 곳에 살아요. 크기가 작아서 대부분 현미경으로 관찰해요. 짚신벌레: 옛날 신발인 짚신처럼 끝이 둥글고 길쭉한 모양이에요. 몸 바깥쪽에 가","keywords":["균류","원생생물"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-e4","unit":"sci-e4-04","grade":"e4"},
{"id":"sci-e4-04#c2","kind":"concept","title":"세균","text":"세균은 균류나 원생생물보다 훨씬 작아서 맨눈으로 볼 수 없고, 배율이 높은 현미경으로 봐야 해요. 모양: 공 모양, 막대 모양, 나선 모양 등 여러 가지예요. 꼬리가 있는 것도 있어요. 하나씩 떨어져 있기도 하고, 여러 개가 줄줄이 이어져 있기도 해요. 사는 곳: 땅, 물, 공기, 음식","keywords":["균류","원생생물","세균"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-e4","unit":"sci-e4-04","grade":"e4"},
{"id":"sci-e4-04#c3","kind":"concept","title":"우리 생활에 주는 영향","text":"균류·원생생물·세균은 우리 생활에 이로운 영향과 해로운 영향을 모두 줘요. 이로운 영향 균류와 세균은 죽은 생물이나 배설물을 분해해 자연을 깨끗하게 하고, 분해된 물질은 흙의 양분이 돼요. 된장, 김치, 요구르트, 빵처럼 맛있는 발효 음식을 만들어요. 해캄 같은 원생생물은 물속 생물의 ","keywords":["균류","원생생물","세균","발효","적조"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-e4","unit":"sci-e4-04","grade":"e4"},
{"id":"sci-e4-04#c4","kind":"concept","title":"생명과학을 생활에 이용하기","text":"사람들은 작은 생물의 특징을 연구해 생활에 이용하고 있어요. 이렇게 생물을 연구해 우리 생활에 도움이 되게 하는 학문을 생명과학이라고 해요. 이용하는 곳 · 어떻게 이용할까요? 발효 식품 · 젖산균(세균)으로 김치·요구르트를, 곰팡이와 세균으로 된장·간장을, 효모(균류)로 빵을 만들어요","keywords":["균류","원생생물","세균","발효","생물 농약","생명과학"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-e4","unit":"sci-e4-04","grade":"e4"},
{"id":"sci-e4-04#t0","kind":"term","title":"균류","text":"버섯, 곰팡이처럼 실 같은 균사로 이루어져 있고 포자로 번식하는 생물이에요. 스스로 양분을 만들지 못해요.","keywords":["균류"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-e4","unit":"sci-e4-04","grade":"e4"},
{"id":"sci-e4-04#t1","kind":"term","title":"균사","text":"균류의 몸을 이루는 가늘고 긴 실 모양의 구조예요.","keywords":["균사"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-e4","unit":"sci-e4-04","grade":"e4"},
{"id":"sci-e4-04#t2","kind":"term","title":"포자","text":"균류가 번식할 때 퍼뜨리는 아주 작은 알갱이예요. 씨와 비슷한 역할을 해요.","keywords":["포자"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-e4","unit":"sci-e4-04","grade":"e4"},
{"id":"sci-e4-04#t3","kind":"term","title":"원생생물","text":"동물, 식물, 균류로 나누기 어렵고 생김새가 단순한 생물이에요. 예: 짚신벌레, 해캄, 아메바","keywords":["원생생물"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-e4","unit":"sci-e4-04","grade":"e4"},
{"id":"sci-e4-04#t4","kind":"term","title":"세균","text":"맨눈으로 볼 수 없을 만큼 아주 작은 생물이에요. 공 모양·막대 모양·나선 모양 등이 있고, 거의 모든 곳에 살아요.","keywords":["세균"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-e4","unit":"sci-e4-04","grade":"e4"},
{"id":"sci-e4-04#t5","kind":"term","title":"발효","text":"세균이나 균류 같은 작은 생물이 음식 재료를 변화시켜 사람에게 이로운 새 맛과 성질을 만드는 것이에요. 예: 김치, 된장, 요구르트","keywords":["발효"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-e4","unit":"sci-e4-04","grade":"e4"},
{"id":"sci-e4-04#t6","kind":"term","title":"생물 농약","text":"해충에게 병을 일으키는 세균이나 균류 같은 생물을 이용해 만든 농약이에요.","keywords":["생물 농약"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-e4","unit":"sci-e4-04","grade":"e4"},
{"id":"sci-e4-04#t7","kind":"term","title":"생명과학","text":"생물을 연구하고, 그 결과를 우리 생활에 이용하는 학문이에요.","keywords":["생명과학"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-e4","unit":"sci-e4-04","grade":"e4"},
{"id":"sci-e4-04#t8","kind":"term","title":"적조","text":"바다나 강에 작은 원생생물이 지나치게 많아져 물 색이 붉게 변하고 물고기가 죽기도 하는 현상이에요.","keywords":["적조"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-e4","unit":"sci-e4-04","grade":"e4"},
{"id":"sci-e4-04#f0","kind":"faq","title":"버섯은 식물 아니에요?","text":"아니에요. 버섯은 균류예요. 식물처럼 스스로 양분을 만들지 못하고, 뿌리·줄기·잎이 없으며, 씨가 아니라 포자로 번식해요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-e4","unit":"sci-e4-04","grade":"e4"},
{"id":"sci-e4-04#f1","kind":"faq","title":"세균은 다 나쁜 거예요?","text":"아니에요. 병을 일으키는 해로운 세균도 있지만, 김치·요구르트를 만드는 젖산균, 죽은 생물을 분해하는 세균처럼 이로운 세균도 아주 많아요. 우리 장 속에도 소화를 돕는 세균이 살고 있어요.","keywords":["세균"],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-e4","unit":"sci-e4-04","grade":"e4"},
{"id":"sci-e4-04#f2","kind":"faq","title":"곰팡이 핀 빵은 곰팡이 부분만 떼어 내고 먹어도 돼요?","text":"먹지 않는 것이 안전해요. 곰팡이의 균사는 눈에 보이지 않게 빵 속까지 퍼져 있을 수 있어요. 곰팡이가 핀 음식은 봉지째 버리고 손을 씻어요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-e4","unit":"sci-e4-04","grade":"e4"},
{"id":"sci-e4-04#f3","kind":"faq","title":"산에서 본 버섯을 먹어도 돼요?","text":"절대 먹으면 안 돼요. 먹을 수 있는 버섯과 독버섯은 생김새가 비슷해 전문가도 구별하기 어려워요. 버섯은 가게에서 파는 것만 먹어요.","keywords":[],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-e4","unit":"sci-e4-04","grade":"e4"},
{"id":"sci-e4-04#m0","kind":"mistake","title":"자주 하는 실수","text":"버섯을 식물이라고 생각하는 실수 — 버섯은 균류예요. 스스로 양분을 만들지 못하고 포자로 번식해요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e4","unit":"sci-e4-04","grade":"e4"},
{"id":"sci-e4-04#m1","kind":"mistake","title":"자주 하는 실수","text":"세균은 모두 해롭다고 생각하는 실수 — 발효 음식을 만들고 죽은 생물을 분해하는 이로운 세균도 많아요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e4","unit":"sci-e4-04","grade":"e4"},
{"id":"sci-e4-04#m2","kind":"mistake","title":"자주 하는 실수","text":"곰팡이를 관찰할 때 봉지를 열어 냄새를 맡는 실수 — 포자를 들이마실 수 있어요. 봉지째 돋보기로 관찰해요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e4","unit":"sci-e4-04","grade":"e4"},
{"id":"sci-e4-05","kind":"unit","title":"밤하늘 관찰","text":"달의 모양과 표면을 관찰하고, 태양계의 태양과 행성, 북극성 주변의 별자리를 찾아봐요. 달 표면의 모습을 설명하고, 여러 날 동안 달 모양이 바뀌는 순서를 말할 수 있어요. 태양계를 이루는 태양·행성·위성을 알고, 행성의 겉모습 특징을 비교할 수 있어요. 별과 행성이 어떻게 다른지 설명할 수 있어요. 북두칠성과 카시오페이아자리를 이용해 북극성을 찾을 수 …","keywords":["충돌 구덩이","달의 바다","천체","태양계","행성","위성","별","별자리","북극성"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e4","unit":"sci-e4-05","grade":"e4"},
{"id":"sci-e4-05#c0","kind":"concept","title":"달 표면의 모습","text":"맨눈이나 망원경으로 달을 보면 밝은 곳과 어두운 곳이 있어요. 밝은 곳: 주변보다 높고 울퉁불퉁한 땅이에요. 어두운 곳: 낮고 평평한 땅이에요. 옛날 사람들이 바다처럼 보인다고 생각해 달의 바다라고 불렀지만, 실제로 물은 없어요. 충돌 구덩이: 우주에서 날아온 돌덩이가 부딪혀 생긴 둥글","keywords":["충돌 구덩이","달의 바다"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e4","unit":"sci-e4-05","grade":"e4"},
{"id":"sci-e4-05#c1","kind":"concept","title":"여러 날 동안 달 모양이 바뀌는 순서","text":"같은 시각에 여러 날 동안 달을 관찰하면 달의 모양이 조금씩 바뀌어요. 바뀌는 순서는 이래요. 초승달 → 상현달 → 보름달 → 하현달 → 그믐달 이름 · 모양 초승달 · 오른쪽이 가늘게 빛나는 눈썹 모양 상현달 · 오른쪽 반이 빛나는 반달 보름달 · 둥근 달 전체가 빛나는 달 하현달 ·","keywords":[],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-e4","unit":"sci-e4-05","grade":"e4"},
{"id":"sci-e4-05#c2","kind":"concept","title":"태양계의 구성원","text":"태양계는 태양과, 태양의 영향을 받으며 그 둘레를 도는 천체들, 그리고 그들이 있는 공간을 모두 합한 것이에요. (천체: 우주에 있는 모든 물체) 태양: 태양계의 한가운데에 있어요. 태양계에서 스스로 빛과 열을 내는 천체는 태양뿐이에요. 행성: 태양 둘레를 도는 큰 천체예요. 태양에서 ","keywords":["천체","태양계","행성","위성"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-e4","unit":"sci-e4-05","grade":"e4"},
{"id":"sci-e4-05#c3","kind":"concept","title":"태양과 행성의 겉모습","text":"사진이나 자료로 태양과 행성을 살펴보면 겉모습이 저마다 달라요. 천체 · 겉모습의 특징 태양 · 스스로 밝은 빛과 열을 내는 뜨거운 공 모양 수성 · 회색빛이고, 달처럼 충돌 구덩이가 많아요 금성 · 두꺼운 구름에 싸여 노르스름하게 보여요 지구 · 파란 바다와 흰 구름이 보이고, 생물이","keywords":["충돌 구덩이","천체","행성"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-e4","unit":"sci-e4-05","grade":"e4"},
{"id":"sci-e4-05#c4","kind":"concept","title":"별은 스스로 빛을 내요","text":"별은 스스로 빛을 내는 천체예요. 태양도 별이에요. 밤하늘의 별들은 태양보다 훨씬 멀리 있어서 작은 점으로 보여요. 행성과 달은 스스로 빛을 내지 못해요. 태양 빛을 받아 되비추기(반사하기) 때문에 밝게 보이는 거예요. · 별 · 행성 스스로 빛을 내나요? · 내요 · 내지 못해요(태양","keywords":["천체","행성","별","별자리"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-e4","unit":"sci-e4-05","grade":"e4"},
{"id":"sci-e4-05#c5","kind":"concept","title":"북극성 찾기","text":"북극성은 북쪽 하늘에 있는 별이에요. 밤새 거의 같은 자리에 있어서, 북극성을 찾으면 북쪽이 어디인지 알 수 있어요. 옛날 사람들은 북극성을 보고 길을 찾았어요. 북극성은 아주 밝은 별이 아니어서, 주변의 눈에 잘 띄는 별자리를 이용해 찾아요. 북두칠성(국자 모양의 일곱 별): 국자 끝","keywords":["별","별자리","북극성"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-e4","unit":"sci-e4-05","grade":"e4"},
{"id":"sci-e4-05#t0","kind":"term","title":"충돌 구덩이","text":"우주에서 날아온 돌덩이가 부딪혀 생긴, 둥글게 움푹 파인 곳이에요. 달 표면에 많아요.","keywords":["충돌 구덩이"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-e4","unit":"sci-e4-05","grade":"e4"},
{"id":"sci-e4-05#t1","kind":"term","title":"달의 바다","text":"달에서 어둡게 보이는 낮고 평평한 곳이에요. 바다라고 부르지만 물은 없어요.","keywords":["달의 바다"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-e4","unit":"sci-e4-05","grade":"e4"},
{"id":"sci-e4-05#t2","kind":"term","title":"천체","text":"태양, 달, 별, 행성처럼 우주에 있는 모든 물체예요.","keywords":["천체"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-e4","unit":"sci-e4-05","grade":"e4"},
{"id":"sci-e4-05#t3","kind":"term","title":"태양계","text":"태양과, 태양 둘레를 도는 행성·위성 같은 천체들과 그 공간을 모두 합한 것이에요.","keywords":["태양계"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-e4","unit":"sci-e4-05","grade":"e4"},
{"id":"sci-e4-05#t4","kind":"term","title":"행성","text":"태양 둘레를 도는 큰 천체예요. 수성, 금성, 지구, 화성, 목성, 토성, 천왕성, 해왕성 8개가 있어요.","keywords":["행성"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-e4","unit":"sci-e4-05","grade":"e4"},
{"id":"sci-e4-05#t5","kind":"term","title":"위성","text":"행성 둘레를 도는 천체예요. 예: 달은 지구의 위성이에요.","keywords":["위성"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-e4","unit":"sci-e4-05","grade":"e4"},
{"id":"sci-e4-05#t6","kind":"term","title":"별","text":"태양처럼 스스로 빛을 내는 천체예요.","keywords":["별"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-e4","unit":"sci-e4-05","grade":"e4"},
{"id":"sci-e4-05#t7","kind":"term","title":"별자리","text":"밤하늘의 별들을 이어 동물·물건·사람 모양을 떠올리고 이름을 붙인 것이에요. 예: 북두칠성, 카시오페이아자리","keywords":["별자리"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-e4","unit":"sci-e4-05","grade":"e4"},
{"id":"sci-e4-05#t8","kind":"term","title":"북극성","text":"북쪽 하늘에 있어 밤새 거의 움직이지 않는 별이에요. 북쪽 방향을 찾을 때 써요.","keywords":["북극성"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-e4","unit":"sci-e4-05","grade":"e4"},
{"id":"sci-e4-05#f0","kind":"faq","title":"금성을 샛별이라고 부르던데, 금성은 별이에요?","text":"아니에요. 금성은 태양 빛을 반사해서 빛나는 행성이에요. 새벽이나 초저녁 하늘에서 아주 밝게 보여서 옛날 사람들이 \"샛별\"이라는 이름을 붙였을 뿐이에요. 과학에서 별은 스스로 빛을 내는 천체를 말해요.","keywords":["별"],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-e4","unit":"sci-e4-05","grade":"e4"},
{"id":"sci-e4-05#f1","kind":"faq","title":"달은 스스로 빛나요?","text":"아니에요. 달은 스스로 빛을 내지 못하고 태양 빛을 반사해서 밝게 보여요. 달은 별이 아니라 지구 둘레를 도는 위성이에요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-e4","unit":"sci-e4-05","grade":"e4"},
{"id":"sci-e4-05#f2","kind":"faq","title":"북극성은 왜 중요한 별이에요? 제일 밝아서 그래요?","text":"북극성은 가장 밝은 별이 아니에요. 북쪽 하늘에서 밤새 거의 움직이지 않기 때문에 북쪽을 알려 주는 별이라 중요해요. 그래서 옛날부터 밤에 길을 찾을 때 썼어요.","keywords":["별","북극성"],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-e4","unit":"sci-e4-05","grade":"e4"},
{"id":"sci-e4-05#f3","kind":"faq","title":"태양도 별이에요?","text":"네, 태양도 스스로 빛과 열을 내는 별이에요. 밤하늘의 다른 별들보다 우리와 아주 가까이 있어서 훨씬 크고 밝게 보여요.","keywords":["별"],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-e4","unit":"sci-e4-05","grade":"e4"},
{"id":"sci-e4-05#m0","kind":"mistake","title":"자주 하는 실수","text":"달의 어두운 곳에 물이 있다고 생각하는 실수 — \"달의 바다\"는 이름일 뿐, 낮고 평평한 땅이고 물은 없어요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e4","unit":"sci-e4-05","grade":"e4"},
{"id":"sci-e4-05#m1","kind":"mistake","title":"자주 하는 실수","text":"상현달과 하현달을 헷갈리는 실수 — 보름달 전에 보이는 오른쪽 반달이 상현달, 보름달 뒤에 보이는 왼쪽 반달이 하현달이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e4","unit":"sci-e4-05","grade":"e4"},
{"id":"sci-e4-05#m2","kind":"mistake","title":"자주 하는 실수","text":"밝게 빛나면 모두 별이라고 생각하는 실수 — 달과 행성은 태양 빛을 반사해서 빛나요. 스스로 빛을 내는 것만 별이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e4","unit":"sci-e4-05","grade":"e4"},
{"id":"sci-e4-06","kind":"unit","title":"생물과 환경","text":"생태계를 이루는 생물 요소와 비생물 요소, 먹고 먹히는 관계, 사람의 활동이 생태계에 주는 영향을 알아봐요. 생태계를 이루는 생물 요소와 비생물 요소를 구분할 수 있어요. 양분을 얻는 방법에 따라 생물을 생산자·소비자·분해자로 나눌 수 있어요. 먹이 사슬과 먹이 그물을 나타내고, 먹이 관계가 복잡할수록 생물이 살아남기에 유리한 까닭을 말할 수 있어요. 환…","keywords":["생태계","생물 요소","비생물 요소","생산자","소비자","분해자","먹이 사슬","먹이 그물","환경 오염"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e4","unit":"sci-e4-06","grade":"e4"},
{"id":"sci-e4-06#c0","kind":"concept","title":"생태계: 생물 요소와 비생물 요소","text":"어떤 곳에서 살아가는 생물과, 그 생물을 둘러싼 환경이 서로 영향을 주고받는 것을 생태계라고 해요. 숲, 강, 바다, 연못, 학교 화단도 저마다 하나의 생태계예요. 생태계를 이루는 것은 두 가지로 나눌 수 있어요. 생물 요소: 살아 있는 것 — 식물, 동물, 곰팡이, 세균 등 비생물 요","keywords":["생태계","생물 요소","비생물 요소"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e4","unit":"sci-e4-06","grade":"e4"},
{"id":"sci-e4-06#c1","kind":"concept","title":"생산자·소비자·분해자","text":"생물은 살아가는 데 필요한 양분을 얻는 방법에 따라 세 무리로 나눌 수 있어요. 무리 · 양분을 얻는 방법 · 예 생산자 · 햇빛을 이용해 스스로 양분을 만들어요 · 벼, 민들레, 소나무, 검정말, 미역 소비자 · 다른 생물을 먹어서 양분을 얻어요 · 메뚜기, 토끼, 개구리, 뱀, 매 ","keywords":["생태계","생산자","소비자","분해자"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-e4","unit":"sci-e4-06","grade":"e4"},
{"id":"sci-e4-06#c2","kind":"concept","title":"먹이 사슬","text":"생물들 사이의 먹고 먹히는 관계가 사슬처럼 한 줄로 이어진 것을 먹이 사슬이라고 해요. 벼 → 메뚜기 → 개구리 → 뱀 → 매 화살표는 먹히는 생물에서 먹는 생물 쪽으로 그려요. \"벼 → 메뚜기\"는 메뚜기가 벼를 먹는다는 뜻이에요. 먹이 사슬의 맨 앞에는 보통 스스로 양분을 만드는 생산","keywords":["생산자","소비자","먹이 사슬"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-e4","unit":"sci-e4-06","grade":"e4"},
{"id":"sci-e4-06#c3","kind":"concept","title":"먹이 그물","text":"실제 생태계에서 한 생물은 여러 가지를 먹고, 여러 생물에게 먹혀요. 그래서 여러 먹이 사슬이 그물처럼 얽혀 있어요. 이것을 먹이 그물이라고 해요. 아래 그림에서 참새는 벼도 먹고 메뚜기도 먹어요. 또 참새는 뱀에게도, 매에게도 먹혀요. 생물 이름을 쓴 카드를 놓고 털실이나 끈으로 먹고","keywords":["생태계","먹이 사슬","먹이 그물"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-e4","unit":"sci-e4-06","grade":"e4"},
{"id":"sci-e4-06#c4","kind":"concept","title":"먹이 관계가 복잡하면 유리한 까닭","text":"먹이 사슬처럼 한 줄로만 이어져 있으면, 한 생물이 사라졌을 때 그것을 먹던 생물은 먹이를 구하지 못해 살기 어려워져요. 먹이 그물처럼 관계가 복잡하면, 한 가지 먹이가 줄어들어도 다른 먹이를 먹을 수 있어서 생물이 살아남기에 유리해요. 예를 들어 위의 먹이 그물에서 메뚜기가 크게 줄어","keywords":["먹이 사슬","먹이 그물"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-e4","unit":"sci-e4-06","grade":"e4"},
{"id":"sci-e4-06#c5","kind":"concept","title":"환경 오염과 생태계 보전","text":"사람의 활동으로 공기·물·흙이 더러워지는 것을 환경 오염이라고 해요. 환경 오염은 생물이 살아가기 어렵게 만들어요. 오염 · 원인의 예 · 생물에 주는 영향 공기 오염 · 자동차 배기가스, 공장 매연 · 동물의 숨 쉬는 기관이 아프고, 식물이 잘 자라지 못해요 물 오염 · 생활 하수, ","keywords":["생태계","환경 오염"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-e4","unit":"sci-e4-06","grade":"e4"},
{"id":"sci-e4-06#t0","kind":"term","title":"생태계","text":"어떤 곳에 사는 생물과 그 생물을 둘러싼 환경이 서로 영향을 주고받는 것이에요. 예: 숲, 강, 바다","keywords":["생태계"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-e4","unit":"sci-e4-06","grade":"e4"},
{"id":"sci-e4-06#t1","kind":"term","title":"생물 요소","text":"생태계에서 살아 있는 것이에요. 예: 식물, 동물, 곰팡이, 세균","keywords":["생물 요소"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-e4","unit":"sci-e4-06","grade":"e4"},
{"id":"sci-e4-06#t2","kind":"term","title":"비생물 요소","text":"생태계에서 살아 있지 않은 것이에요. 예: 햇빛, 물, 공기, 흙, 온도","keywords":["비생물 요소"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-e4","unit":"sci-e4-06","grade":"e4"},
{"id":"sci-e4-06#t3","kind":"term","title":"생산자","text":"햇빛을 이용해 스스로 양분을 만드는 생물이에요. 예: 벼, 민들레, 소나무","keywords":["생산자"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-e4","unit":"sci-e4-06","grade":"e4"},
{"id":"sci-e4-06#t4","kind":"term","title":"소비자","text":"다른 생물을 먹어서 양분을 얻는 생물이에요. 예: 메뚜기, 토끼, 뱀","keywords":["소비자"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-e4","unit":"sci-e4-06","grade":"e4"},
{"id":"sci-e4-06#t5","kind":"term","title":"분해자","text":"죽은 생물이나 배출물을 분해해서 양분을 얻는 생물이에요. 예: 곰팡이, 세균, 버섯","keywords":["분해자"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-e4","unit":"sci-e4-06","grade":"e4"},
{"id":"sci-e4-06#t6","kind":"term","title":"먹이 사슬","text":"생물들의 먹고 먹히는 관계가 사슬처럼 한 줄로 이어진 것이에요. 예: 벼 → 메뚜기 → 개구리","keywords":["먹이 사슬"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-e4","unit":"sci-e4-06","grade":"e4"},
{"id":"sci-e4-06#t7","kind":"term","title":"먹이 그물","text":"여러 먹이 사슬이 그물처럼 얽혀 있는 것이에요.","keywords":["먹이 그물"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-e4","unit":"sci-e4-06","grade":"e4"},
{"id":"sci-e4-06#t8","kind":"term","title":"환경 오염","text":"사람의 활동으로 공기·물·흙이 더러워지는 것이에요.","keywords":["환경 오염"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-e4","unit":"sci-e4-06","grade":"e4"},
{"id":"sci-e4-06#f0","kind":"faq","title":"버섯은 식물 아니에요?","text":"버섯은 식물처럼 한자리에서 자라지만 식물이 아니에요. 식물은 햇빛으로 스스로 양분을 만들지만, 버섯은 죽은 나무나 낙엽을 분해해서 양분을 얻어요. 그래서 버섯은 분해자예요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-e4","unit":"sci-e4-06","grade":"e4"},
{"id":"sci-e4-06#f1","kind":"faq","title":"먹이 사슬 화살표는 왜 먹히는 쪽에서 먹는 쪽으로 그려요?","text":"화살표는 양분이 옮겨 가는 방향을 나타내요. 메뚜기가 벼를 먹으면 벼의 양분이 메뚜기에게 가지요. 그래서 \"벼 → 메뚜기\"로 그려요.","keywords":["먹이 사슬"],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-e4","unit":"sci-e4-06","grade":"e4"},
{"id":"sci-e4-06#f2","kind":"faq","title":"사람은 생산자, 소비자, 분해자 중에 뭐예요?","text":"사람은 스스로 양분을 만들지 못하고 식물과 동물을 먹어서 양분을 얻으니까 소비자예요.","keywords":["생산자","소비자","분해자"],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-e4","unit":"sci-e4-06","grade":"e4"},
{"id":"sci-e4-06#f3","kind":"faq","title":"햇빛이나 물 같은 비생물 요소도 생태계에서 중요해요?","text":"아주 중요해요. 식물은 햇빛과 물이 있어야 양분을 만들고, 그 식물을 동물이 먹어요. 비생물 요소가 달라지면 생물 요소도 함께 영향을 받아요.","keywords":["생태계","생물 요소","비생물 요소"],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-e4","unit":"sci-e4-06","grade":"e4"},
{"id":"sci-e4-06#m0","kind":"mistake","title":"자주 하는 실수","text":"먹이 사슬의 화살표를 거꾸로 그리는 실수 — 화살표는 먹히는 생물에서 먹는 생물 쪽으로 그려요. \"벼 → 메뚜기\"는 메뚜기가 벼를 먹는다는 뜻이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e4","unit":"sci-e4-06","grade":"e4"},
{"id":"sci-e4-06#m1","kind":"mistake","title":"자주 하는 실수","text":"버섯을 생산자(식물)로 생각하는 실수 — 버섯은 스스로 양분을 만들지 못하는 분해자예요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e4","unit":"sci-e4-06","grade":"e4"},
{"id":"sci-e4-06#m2","kind":"mistake","title":"자주 하는 실수","text":"온도나 햇빛처럼 눈에 잘 띄지 않는 것을 생태계에서 빠뜨리는 실수 — 햇빛, 물, 공기, 흙, 온도 모두 비생물 요소예요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e4","unit":"sci-e4-06","grade":"e4"},
{"id":"sci-e4-07","kind":"unit","title":"여러 가지 기체","text":"공기 같은 기체에도 무게가 있고, 온도와 압력에 따라 부피가 달라진다는 것을 실험으로 알아봐요. 공기를 넣기 전과 넣은 뒤의 무게를 비교해 기체에 무게가 있음을 설명할 수 있어요. 온도와 압력에 따라 기체의 부피가 어떻게 달라지는지 말할 수 있어요. 산소·이산화 탄소·질소·헬륨·네온의 성질과 쓰임을 연결할 수 있어요. 기체의 성질을 이용해 움직이는 장치를…","keywords":["기체","부피","압력","산소","이산화 탄소","질소","헬륨","네온"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e4","unit":"sci-e4-07","grade":"e4"},
{"id":"sci-e4-07#c0","kind":"concept","title":"기체에도 무게가 있어요","text":"공기처럼 눈에 보이지 않는 기체도 공간을 차지하고, 무게가 있어요. 바람이 빠진 공의 무게를 전자저울로 잰 뒤, 공기 주입기로 공기를 넣고 다시 재 보면 무게가 늘어나요. 늘어난 무게가 바로 넣은 공기의 무게예요. · 무게 공기를 넣기 전 · 420 g 공기를 넣은 뒤 · 426 g 넣","keywords":["기체"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e4","unit":"sci-e4-07","grade":"e4"},
{"id":"sci-e4-07#c1","kind":"concept","title":"온도에 따라 달라지는 기체의 부피","text":"부피는 물체가 차지하는 공간의 크기예요. 기체의 부피는 온도에 따라 달라져요. 온도가 높아지면 기체의 부피가 커져요. 온도가 낮아지면 기체의 부피가 작아져요. 찌그러진 탁구공을 따뜻한 물에 넣으면, 공 안의 공기가 데워져 부피가 커지면서 찌그러진 곳이 펴져요. 빈 페트병 입구에 풍선을 ","keywords":["기체","부피"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-e4","unit":"sci-e4-07","grade":"e4"},
{"id":"sci-e4-07#c2","kind":"concept","title":"압력에 따라 달라지는 기체의 부피","text":"압력은 누르는 힘의 세기예요. 기체의 부피는 압력에 따라서도 달라져요. 기체에 가하는 압력이 커지면 부피가 작아져요. 압력이 작아지면 부피가 커져요. 입구를 손가락으로 막은 주사기에 공기를 넣고 피스톤을 누르면, 피스톤이 들어가면서 공기의 부피가 작아져요. 세게 누를수록 더 많이 들어가","keywords":["기체","부피","압력"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-e4","unit":"sci-e4-07","grade":"e4"},
{"id":"sci-e4-07#c3","kind":"concept","title":"생활에서 이용되는 여러 가지 기체","text":"우리가 숨 쉬는 공기는 여러 가지 기체가 섞여 있어요. 공기의 대부분은 질소이고, 그다음으로 많은 것이 산소예요. 기체 · 성질 · 생활 속 쓰임 산소 · 생물의 숨쉬기에 필요해요. 다른 물질이 타는 것을 도와요 · 응급 환자의 산소 호흡 장치, 금속을 자르는 기구 이산화 탄소 · 물질","keywords":["기체","산소","이산화 탄소","질소","헬륨","네온"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-e4","unit":"sci-e4-07","grade":"e4"},
{"id":"sci-e4-07#c4","kind":"concept","title":"기체의 성질을 이용한 장치","text":"기체의 성질을 이용하면 물체를 움직이는 장치를 만들 수 있어요. 공기 로켓: 빈 페트병에 빨대 로켓을 꽂고 페트병을 세게 누르면, 압력을 받은 공기가 빠르게 밀려 나가면서 로켓이 날아가요. 풍선 자동차: 부푼 풍선을 장난감 자동차에 달고 입구를 놓으면, 풍선 속 공기가 뒤로 빠져나가면서","keywords":["기체","압력"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-e4","unit":"sci-e4-07","grade":"e4"},
{"id":"sci-e4-07#t0","kind":"term","title":"기체","text":"공기처럼 담는 그릇을 가득 채우고, 모양과 부피가 쉽게 변하는 물질의 상태예요. 대부분 눈에 보이지 않아요.","keywords":["기체"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-e4","unit":"sci-e4-07","grade":"e4"},
{"id":"sci-e4-07#t1","kind":"term","title":"부피","text":"물체가 차지하는 공간의 크기예요.","keywords":["부피"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-e4","unit":"sci-e4-07","grade":"e4"},
{"id":"sci-e4-07#t2","kind":"term","title":"압력","text":"누르는 힘의 세기예요. 압력이 커지면 기체의 부피는 작아져요.","keywords":["압력"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-e4","unit":"sci-e4-07","grade":"e4"},
{"id":"sci-e4-07#t3","kind":"term","title":"산소","text":"생물이 숨 쉬는 데 필요하고, 다른 물질이 타는 것을 돕는 기체예요.","keywords":["산소"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-e4","unit":"sci-e4-07","grade":"e4"},
{"id":"sci-e4-07#t4","kind":"term","title":"이산화 탄소","text":"물질이 타는 것을 막는 기체예요. 소화기, 탄산음료, 드라이아이스에 이용해요.","keywords":["이산화 탄소"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-e4","unit":"sci-e4-07","grade":"e4"},
{"id":"sci-e4-07#t5","kind":"term","title":"질소","text":"공기에서 가장 많은 기체예요. 다른 물질과 잘 반응하지 않아 과자 봉지에 넣어요.","keywords":["질소"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-e4","unit":"sci-e4-07","grade":"e4"},
{"id":"sci-e4-07#t6","kind":"term","title":"헬륨","text":"공기보다 가볍고 불에 타지 않는 기체예요. 하늘로 뜨는 풍선에 넣어요.","keywords":["헬륨"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-e4","unit":"sci-e4-07","grade":"e4"},
{"id":"sci-e4-07#t7","kind":"term","title":"네온","text":"전기를 흘려 주면 붉은빛을 내는 기체예요. 네온사인에 이용해요.","keywords":["네온"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-e4","unit":"sci-e4-07","grade":"e4"},
{"id":"sci-e4-07#f0","kind":"faq","title":"공기는 안 보이는데 정말 무게가 있어요?","text":"네, 있어요. 공기는 눈에 보이지 않을 뿐 아주 작은 알갱이들이 모여 있어요. 공기를 넣기 전과 넣은 뒤의 공 무게를 전자저울로 재 보면 넣은 공기만큼 무게가 늘어난 것을 확인할 수 있어요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-e4","unit":"sci-e4-07","grade":"e4"},
{"id":"sci-e4-07#f1","kind":"faq","title":"헬륨 풍선은 왜 하늘로 날아가요?","text":"헬륨이 공기보다 가볍기 때문이에요. 물에 뜨는 나무 조각처럼, 공기보다 가벼운 헬륨을 넣은 풍선은 공기 중에서 위로 떠올라요.","keywords":["헬륨"],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-e4","unit":"sci-e4-07","grade":"e4"},
{"id":"sci-e4-07#f2","kind":"faq","title":"주사기에 물을 넣고 누르면 왜 안 들어가요?","text":"물 같은 액체는 압력을 받아도 부피가 거의 줄어들지 않기 때문이에요. 기체는 알갱이 사이의 빈 공간이 넓어서 누르면 부피가 쉽게 작아져요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-e4","unit":"sci-e4-07","grade":"e4"},
{"id":"sci-e4-07#f3","kind":"faq","title":"찌그러진 탁구공은 왜 뜨거운 물에 넣으면 펴져요?","text":"탁구공 안의 공기가 데워져 부피가 커지면서 찌그러진 곳을 안에서 밀어 주기 때문이에요. 물이 뜨거우면 데일 수 있으니 따뜻한 물로, 어른과 함께 해 보세요.","keywords":[],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-e4","unit":"sci-e4-07","grade":"e4"},
{"id":"sci-e4-07#m0","kind":"mistake","title":"자주 하는 실수","text":"공기는 보이지 않으니 무게도 없다고 생각하는 실수 — 공기에도 무게가 있어요. 공기를 넣으면 공이 무거워져요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e4","unit":"sci-e4-07","grade":"e4"},
{"id":"sci-e4-07#m1","kind":"mistake","title":"자주 하는 실수","text":"온도와 부피, 압력과 부피의 관계를 헷갈리는 실수 — 온도가 높아지면 부피가 커지고, 압력이 커지면 부피가 작아져요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e4","unit":"sci-e4-07","grade":"e4"},
{"id":"sci-e4-07#m2","kind":"mistake","title":"자주 하는 실수","text":"산소가 스스로 탄다고 생각하는 실수 — 산소는 다른 물질이 타는 것을 돕는 기체예요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e4","unit":"sci-e4-07","grade":"e4"},
{"id":"sci-e4-08","kind":"unit","title":"기후변화와 우리 생활","text":"기후변화가 어떤 현상이며 사람의 활동과 어떤 관계가 있는지 알고, 생활 속 대응 방법을 실천해요. 날씨와 기후를 구별하고, 기후변화와 관련된 현상의 예를 들 수 있어요. 기후변화가 사람의 활동과 관련되어 있음을 설명할 수 있어요. 기후변화가 우리 생활과 환경에 주는 영향을 말할 수 있어요. 기후변화에 대응하는 방법을 알고 실천 계획을 세울 수 있어요.","keywords":["날씨","기후","평년","기후변화","폭염","한파","가뭄","홍수","해수면 상승"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e4","unit":"sci-e4-08","grade":"e4"},
{"id":"sci-e4-08#c0","kind":"concept","title":"날씨, 기후, 그리고 기후변화","text":"날씨는 그날그날의 맑음, 비, 기온 같은 하늘과 공기의 상태예요. 하루에도 여러 번 바뀔 수 있어요. 기후는 한 지역에서 오랜 기간(보통 30년) 동안 나타난 날씨를 평균한 것이에요. 이 30년 동안의 평균을 평년이라고 해요. \"우리나라는 여름에 덥고 비가 많이 와요\"처럼 말하는 것이 ","keywords":["날씨","기후","평년","기후변화","폭염","한파","가뭄","홍수"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e4","unit":"sci-e4-08","grade":"e4"},
{"id":"sci-e4-08#c1","kind":"concept","title":"기후변화와 사람의 활동","text":"과학자들은 요즘 일어나는 기후변화가 사람의 활동과 관련되어 있다고 말해요. 연료를 많이 태우는 생활: 자동차를 타고, 공장을 돌리고, 전기를 만들고, 집을 따뜻하게 할 때 석탄·석유·가스 같은 연료를 많이 태워요. 숲이 줄어드는 일: 나무를 베어 내고 그 자리에 길·건물·밭을 만들면 숲","keywords":["기후","기후변화"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-e4","unit":"sci-e4-08","grade":"e4"},
{"id":"sci-e4-08#c2","kind":"concept","title":"기후변화가 우리 생활과 환경에 주는 영향","text":"기후변화는 우리 생활과 자연 곳곳에 영향을 줘요. 농작물: 기온이 오르면서 같은 곳에서 기르던 농작물이 잘 자라지 않기도 해요. 우리나라에서는 사과를 기르기 알맞은 곳이 점점 북쪽으로 옮겨 가고 있어요. 생물이 사는 곳: 북극의 얼음이 줄어 북극곰이 사냥하기 어려워졌어요. 바닷물이 따뜻","keywords":["기후","기후변화","폭염","가뭄","홍수"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-e4","unit":"sci-e4-08","grade":"e4"},
{"id":"sci-e4-08#c3","kind":"concept","title":"해수면 상승과 모형 실험","text":"해수면은 바닷물의 높이예요. 기온이 오르면 육지를 덮고 있던 빙하와 얼음이 녹아 바다로 흘러들어 해수면이 높아져요. 이것을 해수면 상승이라고 해요. 해수면이 높아지면 바닷가의 낮은 땅이 물에 잠기고, 바닷가 마을과 논밭이 피해를 입어요. 해수면 상승 피해 모형 실험 넓은 통의 한쪽에 모","keywords":["해수면 상승"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-e4","unit":"sci-e4-08","grade":"e4"},
{"id":"sci-e4-08#c4","kind":"concept","title":"기후변화에 대응하는 방법과 실천 계획","text":"기후변화를 늦추기 위해 우리가 생활 속에서 할 수 있는 일이 많아요. 방법 · 실천의 예 에너지 절약 · 쓰지 않는 전등 끄기, 안 쓰는 전기 기구의 플러그 뽑기, 냉난방 온도를 알맞게 맞추기 대중교통 이용 · 가까운 곳은 걷거나 자전거 타기, 먼 곳은 버스·지하철 이용하기 재활용 · ","keywords":["기후","기후변화"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-e4","unit":"sci-e4-08","grade":"e4"},
{"id":"sci-e4-08#t0","kind":"term","title":"날씨","text":"그날그날의 맑음, 비, 기온 같은 하늘과 공기의 상태예요.","keywords":["날씨"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-e4","unit":"sci-e4-08","grade":"e4"},
{"id":"sci-e4-08#t1","kind":"term","title":"기후","text":"한 지역에서 오랜 기간(보통 30년) 동안 나타난 날씨를 평균한 것이에요.","keywords":["기후"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-e4","unit":"sci-e4-08","grade":"e4"},
{"id":"sci-e4-08#t2","kind":"term","title":"평년","text":"날씨를 비교할 때 기준으로 삼는, 지난 30년 동안의 평균이에요. 예: \"평년보다 기온이 높아요.\"","keywords":["평년"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-e4","unit":"sci-e4-08","grade":"e4"},
{"id":"sci-e4-08#t3","kind":"term","title":"기후변화","text":"한 지역의 기후가 오랜 시간에 걸쳐 달라지는 것이에요.","keywords":["기후변화"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-e4","unit":"sci-e4-08","grade":"e4"},
{"id":"sci-e4-08#t4","kind":"term","title":"폭염","text":"아주 심한 더위가 여러 날 이어지는 것이에요.","keywords":["폭염"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-e4","unit":"sci-e4-08","grade":"e4"},
{"id":"sci-e4-08#t5","kind":"term","title":"한파","text":"갑자기 기온이 크게 떨어지는 심한 추위예요.","keywords":["한파"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-e4","unit":"sci-e4-08","grade":"e4"},
{"id":"sci-e4-08#t6","kind":"term","title":"가뭄","text":"오랫동안 비가 내리지 않아 땅과 강이 메마르는 것이에요.","keywords":["가뭄"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-e4","unit":"sci-e4-08","grade":"e4"},
{"id":"sci-e4-08#t7","kind":"term","title":"홍수","text":"비가 너무 많이 와서 강물이 넘치고 땅이 잠기는 것이에요.","keywords":["홍수"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-e4","unit":"sci-e4-08","grade":"e4"},
{"id":"sci-e4-08#t8","kind":"term","title":"해수면 상승","text":"빙하와 얼음이 녹아 바다로 흘러드는 등의 까닭으로 바닷물의 높이가 높아지는 것이에요.","keywords":["해수면 상승"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-e4","unit":"sci-e4-08","grade":"e4"},
{"id":"sci-e4-08#f0","kind":"faq","title":"날씨랑 기후는 뭐가 달라요?","text":"날씨는 오늘, 이번 주처럼 짧은 동안의 하늘과 공기의 상태예요. 기후는 오랜 기간(보통 30년) 동안 나타난 날씨를 평균한 모습이에요. \"오늘 비가 와요\"는 날씨, \"우리나라는 여름에 비가 많이 와요\"는 기후예요.","keywords":["날씨","기후"],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-e4","unit":"sci-e4-08","grade":"e4"},
{"id":"sci-e4-08#f1","kind":"faq","title":"기후변화 때문에 더워진다면서 왜 한파도 와요?","text":"기후변화는 단순히 매일 더워지기만 하는 것이 아니에요. 기후가 달라지면 평년보다 크게 덥거나, 크게 춥거나, 비나 눈이 아주 많거나 적은 일이 더 자주 나타날 수 있어요. 그래서 폭염과 한파, 가뭄과 홍수가 모두 기후변화와 관련된 현상으로 이야기돼요.","keywords":["기후","기후변화","한파"],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-e4","unit":"sci-e4-08","grade":"e4"},
{"id":"sci-e4-08#f2","kind":"faq","title":"나 혼자 전등을 끈다고 기후변화가 달라져요?","text":"한 사람의 실천은 작아 보이지만, 많은 사람이 함께하면 큰 차이가 돼요. 또 내가 실천하는 모습을 보고 가족과 친구도 함께하게 돼요. 작은 실천을 꾸준히 이어 가는 것이 중요해요.","keywords":["기후","기후변화"],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-e4","unit":"sci-e4-08","grade":"e4"},
{"id":"sci-e4-08#m0","kind":"mistake","title":"자주 하는 실수","text":"하루나 며칠의 날씨를 보고 기후가 바뀌었다고 말하는 실수 — 기후는 오랜 기간(보통 30년)의 평균이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e4","unit":"sci-e4-08","grade":"e4"},
{"id":"sci-e4-08#m1","kind":"mistake","title":"자주 하는 실수","text":"기후변화가 \"더워지는 것\"뿐이라고 생각하는 실수 — 한파, 폭설, 가뭄, 홍수처럼 평년과 크게 다른 날씨가 자주 나타나는 것도 기후변화와 관련된 현상이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e4","unit":"sci-e4-08","grade":"e4"},
{"id":"sci-e4-08#m2","kind":"mistake","title":"자주 하는 실수","text":"바다에 떠 있는 얼음이 녹는 것이 해수면을 높이는 까닭이라고 생각하는 실수 — 해수면을 크게 높이는 것은 육지 위의 빙하와 얼음이 녹아 바다로 흘러드는 물이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e4","unit":"sci-e4-08","grade":"e4"},
{"id":"sci-e5-01","kind":"unit","title":"실험으로 탐구하기","text":"궁금한 문제를 정하고 결과를 예상한 뒤, 조건을 맞춘 실험으로 결론을 이끌어 내는 탐구 방법을 배워요. 실험으로 확인할 수 있는 탐구 문제를 정하고 결과를 예상할 수 있어요. 다르게 할 조건과 같게 할 조건을 정해 실험을 계획할 수 있어요. 실험 결과를 표와 그래프로 나타내고 해석해 결론을 내릴 수 있어요. 탐구 결과를 발표하고 새로운 탐구 문제를 찾을 …","keywords":["탐구 문제","가설","다르게 할 조건","같게 할 조건","탐구 계획","결과 해석","결론"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-01","grade":"e5"},
{"id":"sci-e5-01#c0","kind":"concept","title":"실험으로 확인할 수 있는 탐구 문제","text":"탐구 문제는 실험이나 관찰로 답을 찾으려는 궁금한 점이에요. 좋은 탐구 문제는 다음 조건을 갖춰요. 실험으로 확인할 수 있어요. 재거나 세거나 관찰해서 답을 얻을 수 있어요. 무엇을 바꾸고 무엇을 잴지 분명해요. 우리가 가진 준비물과 시간으로 직접 해 볼 수 있어요. 예를 들어 \"경사면","keywords":["탐구 문제"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-01","grade":"e5"},
{"id":"sci-e5-01#c1","kind":"concept","title":"결과 예상하기와 탐구 계획 세우기","text":"탐구 문제를 정했으면 실험하기 전에 결과를 미리 예상해요. 예상은 그냥 짐작이 아니라 내가 알고 있는 것과 겪은 일을 바탕으로 세워요. 이렇게 실험으로 확인해 볼 수 있게 미리 세운 예상을 가설이라고도 해요. 예: \"경사면이 높을수록 장난감 자동차가 더 멀리 굴러갈 것이다. 미끄럼틀이 ","keywords":["탐구 문제","가설","다르게 할 조건","같게 할 조건","탐구 계획"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-e5","unit":"sci-e5-01","grade":"e5"},
{"id":"sci-e5-01#c2","kind":"concept","title":"다르게 할 조건과 같게 할 조건","text":"실험을 설계할 때는 다르게 할 조건을 딱 하나만 정하고, 나머지 조건은 모두 같게 해요. 다르게 할 조건: 결과에 영향을 주는지 알아보려고 일부러 바꾸는 조건 (예: 경사면의 높이) 같게 할 조건: 결과에 영향을 줄 수 있어서 모두 똑같이 맞추는 조건 (예: 자동차의 종류, 출발 위치,","keywords":["다르게 할 조건","같게 할 조건"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-e5","unit":"sci-e5-01","grade":"e5"},
{"id":"sci-e5-01#c3","kind":"concept","title":"결과를 표와 그래프로 나타내기","text":"실험에서 얻은 결과는 표로 정리하고, 한눈에 비교하기 쉽게 그래프로 나타내요. 경사면의 높이(cm) · 10 · 20 · 30 굴러간 거리(cm) · 45 · 80 · 115 표: 다르게 한 조건과 잰 값을 칸에 맞춰 적어요. 단위를 꼭 써요. 막대그래프: 여러 가지를 서로 비교할 때 ","keywords":[],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-e5","unit":"sci-e5-01","grade":"e5"},
{"id":"sci-e5-01#c4","kind":"concept","title":"결과 해석하기와 결론 내리기","text":"결과 해석은 표와 그래프를 보고 \"다르게 한 조건이 달라질 때 결과가 어떻게 달라졌는지\" 규칙을 찾는 거예요. 예: 높이가 10 cm → 20 cm → 30 cm로 높아질수록 굴러간 거리가 45 cm → 80 cm → 115 cm로 늘어났어요. 이 규칙을 바탕으로 탐구 문제의 답을 한 ","keywords":["탐구 문제","같게 할 조건","결과 해석","결론"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-e5","unit":"sci-e5-01","grade":"e5"},
{"id":"sci-e5-01#c5","kind":"concept","title":"발표하고 새로운 탐구 문제 찾기","text":"탐구가 끝나면 다른 사람에게 발표해요. 발표할 때는 다음 순서로 정리하면 듣는 사람이 이해하기 쉬워요. 탐구 문제 예상 실험 방법(다르게 한 조건, 같게 한 조건) 결과(표·그래프) 결론 발표를 듣는 사람은 궁금한 점을 질문하고, 발표하는 사람은 친구들의 생각을 들으며 탐구를 돌아봐요.","keywords":["탐구 문제","결론"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-e5","unit":"sci-e5-01","grade":"e5"},
{"id":"sci-e5-01#t0","kind":"term","title":"탐구 문제","text":"실험이나 관찰로 답을 찾으려는 궁금한 점이에요. 예: \"물의 온도에 따라 각설탕이 녹는 시간이 달라질까?\"","keywords":["탐구 문제"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-01","grade":"e5"},
{"id":"sci-e5-01#t1","kind":"term","title":"가설","text":"탐구 문제에 대해 실험으로 확인할 수 있게 미리 세운 예상이에요. 예: \"경사면이 높을수록 자동차가 멀리 굴러갈 것이다.\"","keywords":["가설"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-e5","unit":"sci-e5-01","grade":"e5"},
{"id":"sci-e5-01#t2","kind":"term","title":"다르게 할 조건","text":"결과에 영향을 주는지 알아보려고 실험에서 일부러 바꾸는 조건이에요. 한 실험에서 하나만 정해요.","keywords":["다르게 할 조건"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-e5","unit":"sci-e5-01","grade":"e5"},
{"id":"sci-e5-01#t3","kind":"term","title":"같게 할 조건","text":"결과에 영향을 줄 수 있어서 실험하는 동안 모두 똑같이 맞추는 조건이에요.","keywords":["같게 할 조건"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-e5","unit":"sci-e5-01","grade":"e5"},
{"id":"sci-e5-01#t4","kind":"term","title":"탐구 계획","text":"준비물, 다르게 할 조건과 같게 할 조건, 잴 것, 실험 방법과 횟수, 안전 수칙을 미리 정해 두는 것이에요.","keywords":["탐구 계획"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-e5","unit":"sci-e5-01","grade":"e5"},
{"id":"sci-e5-01#t5","kind":"term","title":"결과 해석","text":"표나 그래프를 보고 조건이 달라질 때 결과가 어떻게 달라지는지 규칙을 찾는 것이에요.","keywords":["결과 해석"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-e5","unit":"sci-e5-01","grade":"e5"},
{"id":"sci-e5-01#t6","kind":"term","title":"결론","text":"실험 결과를 바탕으로 탐구 문제에 대한 답을 정리한 것이에요.","keywords":["결론"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-e5","unit":"sci-e5-01","grade":"e5"},
{"id":"sci-e5-01#f0","kind":"faq","title":"다르게 할 조건이랑 같게 할 조건은 어떻게 찾아요?","text":"먼저 탐구 문제에서 \"~에 따라\"의 앞부분을 찾으면 그것이 다르게 할 조건이에요. \"경사면의 높이에 따라 거리가 달라질까?\"라면 높이지요. 그다음 결과에 영향을 줄 수 있는 다른 것들을 모두 떠올려 보세요. 자동차, 출발 위치, 바닥처럼 결과를 바꿀 수 있는 것은 모두 같게 할 조건이에요.","keywords":["다르게 할 조건","같게 할 조건"],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-01","grade":"e5"},
{"id":"sci-e5-01#f1","kind":"faq","title":"예상이 틀리면 실험을 잘못한 건가요?","text":"아니에요. 예상은 실험 전에 세운 생각일 뿐이라 틀릴 수 있어요. 예상과 결과가 다르면 같게 할 조건을 잘 지켰는지 확인하고 다시 실험해 보세요. 그래도 같다면 예상을 고치면 돼요. 예상이 틀린 덕분에 새로 알게 되는 것도 많아요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-e5","unit":"sci-e5-01","grade":"e5"},
{"id":"sci-e5-01#f2","kind":"faq","title":"왜 같은 실험을 여러 번 해요?","text":"한 번만 하면 실수가 섞여도 알아차리기 어려워요. 여러 번 해서 결과가 비슷하게 나오면 그 결과를 믿을 수 있고, 하나만 크게 다르면 실수가 있었는지 확인할 수 있어요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-e5","unit":"sci-e5-01","grade":"e5"},
{"id":"sci-e5-01#f3","kind":"faq","title":"결과랑 결론은 뭐가 달라요?","text":"결과는 실험에서 관찰하고 잰 것 그 자체예요(예: 높이 10 cm에서 45 cm 굴러감). 결론은 결과를 해석해서 탐구 문제에 답한 문장이에요(예: 경사면이 높을수록 멀리 굴러간다).","keywords":["결론"],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-e5","unit":"sci-e5-01","grade":"e5"},
{"id":"sci-e5-01#m0","kind":"mistake","title":"자주 하는 실수","text":"다르게 할 조건을 두 가지 이상 바꾸는 실수 — 무엇 때문에 결과가 달라졌는지 알 수 없어요. 한 가지만 바꿔요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e5","unit":"sci-e5-01","grade":"e5"},
{"id":"sci-e5-01#m1","kind":"mistake","title":"자주 하는 실수","text":"실험에서 재는 결과(굴러간 거리, 걸린 시간)를 \"조건\"으로 헷갈리는 실수 — 조건은 실험하는 사람이 정하는 것, 결과는 실험해서 얻는 것이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e5","unit":"sci-e5-01","grade":"e5"},
{"id":"sci-e5-01#m2","kind":"mistake","title":"자주 하는 실수","text":"예상과 다른 결과를 지우거나 고쳐 쓰는 실수 — 결과는 있는 그대로 적고, 다르면 방법을 점검해 다시 실험해요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e5","unit":"sci-e5-01","grade":"e5"},
{"id":"sci-e5-02","kind":"unit","title":"지층과 화석","text":"층층이 쌓인 지층이 만들어지는 과정과 퇴적암, 화석으로 옛날 생물과 환경을 알아내는 방법을 배워요. 지층의 특징을 관찰하고, 지층이 만들어지는 과정을 설명할 수 있어요. 알갱이의 크기에 따라 퇴적암을 이암·사암·역암으로 나눌 수 있어요. 화석이 만들어지는 과정을 설명하고, 화석으로 옛날의 생물과 환경을 추리할 수 있어요.","keywords":["지층","퇴적물","퇴적","퇴적암","이암","사암","역암","화석","화석 연료"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-02","grade":"e5"},
{"id":"sci-e5-02#c0","kind":"concept","title":"지층의 특징","text":"산을 깎아 만든 길옆이나 바닷가 절벽을 보면 여러 겹의 줄무늬가 있는 곳이 있어요. 이렇게 자갈, 모래, 진흙 같은 알갱이가 층층이 쌓여 있는 것을 지층이라고 해요. 지층을 관찰하면 이런 특징이 있어요. 줄무늬가 보여요. 층과 층 사이에 경계가 있어요. 층마다 두께가 달라요. 두꺼운 층","keywords":["지층"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-02","grade":"e5"},
{"id":"sci-e5-02#c1","kind":"concept","title":"지층이 만들어지는 과정","text":"지층은 아주 오랜 시간에 걸쳐 이렇게 만들어져요. 운반: 흐르는 물이 자갈, 모래, 진흙을 강이나 바다로 옮겨요. 퇴적: 옮겨진 알갱이들이 바다나 호수의 바닥에 차례로 쌓여요. 다져지고 굳음: 그 위에 또 쌓이고 쌓이면, 위에서 누르는 무게 때문에 아래의 알갱이들이 단단히 다져지고 서로","keywords":["지층","퇴적"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-e5","unit":"sci-e5-02","grade":"e5"},
{"id":"sci-e5-02#c2","kind":"concept","title":"퇴적암: 이암, 사암, 역암","text":"물에 실려 와 쌓인 자갈, 모래, 진흙 같은 것을 퇴적물이라고 해요. 퇴적물이 다져지고 굳어져 만들어진 암석을 퇴적암이라고 해요. 퇴적암은 알갱이의 크기에 따라 나눠요. 퇴적암 · 주로 이루는 알갱이 · 알갱이 크기 · 만져 보면 이암 · 진흙 · 아주 작아요 · 부드러워요 사암 · 모","keywords":["퇴적물","퇴적","퇴적암","이암","사암","역암"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-e5","unit":"sci-e5-02","grade":"e5"},
{"id":"sci-e5-02#c3","kind":"concept","title":"화석과 화석이 만들어지는 과정","text":"화석은 아주 오랜 옛날에 살았던 생물의 몸체나 흔적이 암석이나 지층 속에 남아 있는 것이에요. 뼈나 껍데기, 잎 같은 몸체뿐 아니라 발자국, 기어간 자국 같은 흔적도 화석이에요. 화석은 이렇게 만들어져요. 생물이 죽어 호수나 바다의 바닥에 가라앉아요. 그 위로 진흙이나 모래가 빠르게 쌓","keywords":["지층","퇴적물","퇴적","퇴적암","화석"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-e5","unit":"sci-e5-02","grade":"e5"},
{"id":"sci-e5-02#c4","kind":"concept","title":"화석으로 알 수 있는 것과 화석의 가치","text":"화석을 보면 오래전에 어떤 생물이 살았는지, 그 생물이 어떻게 생겼고 어떻게 살았는지 알 수 있어요. 오늘날 비슷한 생물이 사는 곳과 비교하면 그곳이 옛날에 어떤 환경이었는지도 추리할 수 있어요. 발견된 화석 · 추리할 수 있는 옛날 환경 산호 화석 · 따뜻하고 얕은 바다 조개·물고기 ","keywords":["지층","화석","화석 연료"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-e5","unit":"sci-e5-02","grade":"e5"},
{"id":"sci-e5-02#t0","kind":"term","title":"지층","text":"자갈, 모래, 진흙 같은 알갱이가 층층이 쌓여 줄무늬가 보이는 것이에요.","keywords":["지층"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-02","grade":"e5"},
{"id":"sci-e5-02#t1","kind":"term","title":"퇴적물","text":"물이나 바람에 실려 와서 쌓인 자갈, 모래, 진흙 같은 것이에요.","keywords":["퇴적물"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-e5","unit":"sci-e5-02","grade":"e5"},
{"id":"sci-e5-02#t2","kind":"term","title":"퇴적","text":"물에 실려 온 자갈, 모래, 진흙 같은 것이 바다나 호수의 바닥에 쌓이는 것이에요.","keywords":["퇴적"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-e5","unit":"sci-e5-02","grade":"e5"},
{"id":"sci-e5-02#t3","kind":"term","title":"퇴적암","text":"퇴적물이 다져지고 굳어져 만들어진 암석이에요. 이암, 사암, 역암이 있어요.","keywords":["퇴적암"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-e5","unit":"sci-e5-02","grade":"e5"},
{"id":"sci-e5-02#t4","kind":"term","title":"이암","text":"주로 아주 작은 진흙 알갱이로 이루어진 퇴적암이에요. 만지면 부드러워요.","keywords":["이암"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-e5","unit":"sci-e5-02","grade":"e5"},
{"id":"sci-e5-02#t5","kind":"term","title":"사암","text":"주로 모래로 이루어진 퇴적암이에요. 만지면 조금 거칠어요.","keywords":["사암"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-e5","unit":"sci-e5-02","grade":"e5"},
{"id":"sci-e5-02#t6","kind":"term","title":"역암","text":"자갈이 섞여 있는 퇴적암이에요. 알갱이가 커서 울퉁불퉁해요.","keywords":["역암"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-e5","unit":"sci-e5-02","grade":"e5"},
{"id":"sci-e5-02#t7","kind":"term","title":"화석","text":"아주 오래전에 살았던 생물의 몸체나 발자국 같은 흔적이 암석이나 지층 속에 남아 있는 것이에요.","keywords":["화석"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-e5","unit":"sci-e5-02","grade":"e5"},
{"id":"sci-e5-02#t8","kind":"term","title":"화석 연료","text":"아주 옛날 생물이 땅속에 묻혀 만들어진 석탄, 석유 같은 연료예요.","keywords":["화석 연료"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-e5","unit":"sci-e5-02","grade":"e5"},
{"id":"sci-e5-02#f0","kind":"faq","title":"화석은 생물이 그대로 돌로 변한 거예요?","text":"꼭 그렇지는 않아요. 뼈나 껍데기 같은 단단한 부분이 오랜 시간 동안 남은 것도 있고, 생물의 몸 모양대로 자국만 남은 것도 있어요. 발자국이나 기어간 자국처럼 생물의 몸이 아닌 흔적도 화석이에요.","keywords":["화석"],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-02","grade":"e5"},
{"id":"sci-e5-02#f1","kind":"faq","title":"바닷속에서 만들어진 지층이 왜 산에서 보여요?","text":"아주 오랜 시간에 걸쳐 땅이 조금씩 솟아오를 수 있어요. 바다나 호수 바닥에 쌓인 지층이 솟아올라 육지가 되고, 겉이 깎이면 그 속의 지층과 화석이 드러나요. 그래서 높은 산에서 조개 화석이 발견되기도 해요.","keywords":["지층"],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-e5","unit":"sci-e5-02","grade":"e5"},
{"id":"sci-e5-02#f2","kind":"faq","title":"지층은 얼마나 오래 걸려서 만들어져요?","text":"한 층의 두께와 쌓이는 빠르기에 따라 다르지만, 우리가 보는 지층은 대부분 아주 오랜 시간, 수천 년에서 수백만 년 넘게 걸려 만들어져요. 컵에 흙을 넣는 모형은 몇 분 만에 끝나지만, 실제 지층은 그보다 훨씬 천천히 쌓이고 굳어요.","keywords":["지층"],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-e5","unit":"sci-e5-02","grade":"e5"},
{"id":"sci-e5-02#f3","kind":"faq","title":"공룡이랑 사람이 같은 시대에 살았어요?","text":"아니에요. 공룡은 사람이 나타나기 아주 오래전에 사라졌어요. 화석과 지층을 연구하면 공룡 화석은 사람의 흔적이 나오는 지층보다 훨씬 아래, 곧 훨씬 먼저 쌓인 지층에서 나와요.","keywords":[],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-e5","unit":"sci-e5-02","grade":"e5"},
{"id":"sci-e5-02#m0","kind":"mistake","title":"자주 하는 실수","text":"지층에서 위에 있는 층이 먼저 쌓였다고 생각하는 실수 — 뒤집히지 않았다면 아래층이 먼저 쌓인 층이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e5","unit":"sci-e5-02","grade":"e5"},
{"id":"sci-e5-02#m1","kind":"mistake","title":"자주 하는 실수","text":"사암과 역암을 헷갈리는 실수 — 모래가 굳으면 사암, 자갈이 섞여 굳으면 역암이에요. 이암은 진흙이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e5","unit":"sci-e5-02","grade":"e5"},
{"id":"sci-e5-02#m2","kind":"mistake","title":"자주 하는 실수","text":"뼈나 껍데기만 화석이라고 생각하는 실수 — 발자국이나 기어간 자국 같은 흔적도 화석이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e5","unit":"sci-e5-02","grade":"e5"},
{"id":"sci-e5-03","kind":"unit","title":"빛의 성질","text":"물체를 보려면 빛이 필요한 까닭과 빛이 곧게 나아가고 반사되고 꺾이는 성질, 거울과 렌즈의 쓰임을 배워요. 물체를 보려면 빛이 필요한 까닭을 설명할 수 있어요. 빛의 직진으로 그림자가 생기는 까닭과 거울에서 빛이 반사되는 모습을 설명할 수 있어요. 물과 공기의 경계에서 빛이 꺾이는 현상과 볼록 렌즈의 성질을 설명할 수 있어요. 거울과 렌즈가 생활에서 쓰이…","keywords":["빛의 직진","그림자","빛의 반사","빛의 굴절","볼록 렌즈","잠망경"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-03","grade":"e5"},
{"id":"sci-e5-03#c0","kind":"concept","title":"물체를 보려면 빛이 필요해요","text":"불을 모두 끈 깜깜한 방에서는 바로 앞의 물건도 보이지 않아요. 물체를 보려면 빛이 있어야 하기 때문이에요. 스스로 빛을 내는 물체: 태양, 켜진 전등, 반딧불이처럼 스스로 빛을 내요. 이런 물체에서 나온 빛이 우리 눈에 바로 들어오면 그 물체가 보여요. 스스로 빛을 내지 못하는 물체:","keywords":[],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-03","grade":"e5"},
{"id":"sci-e5-03#c1","kind":"concept","title":"빛의 직진과 그림자","text":"빛은 공기 속에서 휘지 않고 곧게 나아가요. 이것을 빛의 직진이라고 해요. 곧게 나아가던 빛이 물체에 막히면 물체 뒤쪽으로는 빛이 닿지 못해요. 그래서 물체 뒤에 어두운 부분, 곧 그림자가 생겨요. 빛이 휘어서 물체 뒤로 돌아 들어가지 못하니, 그림자의 모양은 빛을 막은 물체의 모양과 ","keywords":["빛의 직진","그림자"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-e5","unit":"sci-e5-03","grade":"e5"},
{"id":"sci-e5-03#c2","kind":"concept","title":"거울에서 빛의 반사","text":"빛이 나아가다가 거울에 부딪히면 방향을 바꾸어 되돌아 나와요. 이것을 빛의 반사라고 해요. 손전등 빛을 거울에 비추면, 빛이 거울에서 방향을 바꾸어 다른 쪽 벽을 비추는 것을 볼 수 있어요. 거울을 이용하면 빛이 나아가는 방향을 바꿀 수 있어요. 거울을 여러 개 놓으면 빛을 원하는 곳까","keywords":["빛의 반사"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-e5","unit":"sci-e5-03","grade":"e5"},
{"id":"sci-e5-03#c3","kind":"concept","title":"물과 공기의 경계에서 빛의 굴절","text":"빛이 공기에서 물로, 또는 물에서 공기로 비스듬히 나아갈 때는 두 물질의 경계에서 꺾여 나아가요. 이것을 빛의 굴절이라고 해요. 빛이 경계에 수직으로(똑바로 내리꽂히듯) 들어가면 꺾이지 않고 그대로 나아가요. 빛이 경계에 비스듬히 들어가면 경계에서 꺾여요. 그래서 이런 일이 생겨요. 물","keywords":["빛의 굴절"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-e5","unit":"sci-e5-03","grade":"e5"},
{"id":"sci-e5-03#c4","kind":"concept","title":"볼록 렌즈","text":"볼록 렌즈는 가운데가 가장자리보다 두꺼운 렌즈예요. 볼록 렌즈를 지나는 빛은 꺾여서(굴절해서) 한 곳으로 모여요. 햇빛 모으기: 볼록 렌즈로 햇빛을 모으면, 빛이 모인 곳은 주변보다 밝고 온도가 높아요. 햇빛이 모인 곳을 작게 할수록 더 밝고 뜨거워져요. 볼록 렌즈로 본 물체의 모습: ","keywords":["볼록 렌즈"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-e5","unit":"sci-e5-03","grade":"e5"},
{"id":"sci-e5-03#c5","kind":"concept","title":"거울과 렌즈의 쓰임","text":"빛이 반사하고 굴절하는 성질을 이용한 도구가 우리 주변에 많아요. 도구 · 쓰는 것 · 하는 일 잠망경 · 거울 2개 · 빛을 두 번 반사시켜 담 너머나 물 위를 봐요 자동차 뒷거울 · 거울 · 뒤에서 오는 차를 봐요 돋보기 · 볼록 렌즈 · 작은 물체를 크게 봐요 안경 · 렌즈 · 잘","keywords":["볼록 렌즈","잠망경"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-e5","unit":"sci-e5-03","grade":"e5"},
{"id":"sci-e5-03#t0","kind":"term","title":"빛의 직진","text":"빛이 휘지 않고 곧게 나아가는 성질이에요. 그래서 그림자가 생겨요.","keywords":["빛의 직진"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-03","grade":"e5"},
{"id":"sci-e5-03#t1","kind":"term","title":"그림자","text":"곧게 나아가던 빛이 물체에 막혀 물체 뒤쪽에 생긴 어두운 부분이에요.","keywords":["그림자"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-e5","unit":"sci-e5-03","grade":"e5"},
{"id":"sci-e5-03#t2","kind":"term","title":"빛의 반사","text":"나아가던 빛이 거울 같은 물체에 부딪혀 방향을 바꾸어 되돌아 나오는 것이에요.","keywords":["빛의 반사"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-e5","unit":"sci-e5-03","grade":"e5"},
{"id":"sci-e5-03#t3","kind":"term","title":"빛의 굴절","text":"빛이 공기와 물처럼 서로 다른 물질의 경계를 비스듬히 지날 때 꺾여 나아가는 것이에요.","keywords":["빛의 굴절"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-e5","unit":"sci-e5-03","grade":"e5"},
{"id":"sci-e5-03#t4","kind":"term","title":"볼록 렌즈","text":"가운데가 가장자리보다 두꺼운 렌즈예요. 빛을 꺾어 한 곳으로 모아요. 예: 돋보기","keywords":["볼록 렌즈"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-e5","unit":"sci-e5-03","grade":"e5"},
{"id":"sci-e5-03#t5","kind":"term","title":"잠망경","text":"거울 두 개로 빛을 반사시켜 담 너머나 물 위처럼 직접 볼 수 없는 곳을 보는 도구예요.","keywords":["잠망경"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-e5","unit":"sci-e5-03","grade":"e5"},
{"id":"sci-e5-03#f0","kind":"faq","title":"달은 왜 밝게 빛나요? 스스로 빛을 내는 거 아니에요?","text":"달은 스스로 빛을 내지 않아요. 태양에서 온 빛이 달 표면에 부딪혀 반사되고, 그 빛이 우리 눈에 들어와서 밝게 보이는 거예요. 책이 전등 빛을 반사해서 보이는 것과 같은 원리예요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-03","grade":"e5"},
{"id":"sci-e5-03#f1","kind":"faq","title":"거울은 왜 좌우만 바뀌고 위아래는 안 바뀌어요?","text":"거울은 앞에 있는 것을 바로 앞뒤로만 뒤집어 비춰 줘요. 그래서 위쪽에 있는 머리는 거울 속에서도 위쪽, 아래쪽 발은 아래쪽에 그대로 있어요. 그런데 거울 속 사람이 나를 마주 보고 있다고 생각하면 내 오른손이 그 사람의 왼손 자리에 있게 되어 좌우가 바뀐 것처럼 느껴져요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-e5","unit":"sci-e5-03","grade":"e5"},
{"id":"sci-e5-03#f2","kind":"faq","title":"물속 젓가락은 진짜로 휘어진 거예요?","text":"아니에요. 꺼내 보면 젓가락은 곧아요. 물속의 젓가락에서 나온 빛이 물과 공기의 경계에서 꺾여 눈에 들어오기 때문에 꺾여 보이는 거예요. 이것을 빛의 굴절이라고 해요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-e5","unit":"sci-e5-03","grade":"e5"},
{"id":"sci-e5-03#f3","kind":"faq","title":"볼록 렌즈로 태양을 보면 안 되는 이유가 뭐예요?","text":"볼록 렌즈는 빛을 한 곳에 모아요. 렌즈로 태양을 보면 아주 강한 햇빛이 눈 속에 모여서 눈을 크게 다칠 수 있어요. 렌즈 없이도 태양을 직접 보는 것은 위험해요. 햇빛을 모으는 실험은 어른과 함께, 종이에만 비추어 해요.","keywords":["볼록 렌즈"],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-e5","unit":"sci-e5-03","grade":"e5"},
{"id":"sci-e5-03#m0","kind":"mistake","title":"자주 하는 실수","text":"달이나 거울이 스스로 빛을 낸다고 생각하는 실수 — 둘 다 다른 곳에서 온 빛을 반사해서 보여요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e5","unit":"sci-e5-03","grade":"e5"},
{"id":"sci-e5-03#m1","kind":"mistake","title":"자주 하는 실수","text":"빛의 반사와 굴절을 헷갈리는 실수 — 거울에서 튕겨 나오면 반사, 물과 공기의 경계를 지나며 꺾이면 굴절이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e5","unit":"sci-e5-03","grade":"e5"},
{"id":"sci-e5-03#m2","kind":"mistake","title":"자주 하는 실수","text":"거울에 비친 모습은 위아래도 바뀐다고 생각하는 실수 — 위아래는 그대로이고 좌우가 바뀌어 보여요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e5","unit":"sci-e5-03","grade":"e5"},
{"id":"sci-e5-04","kind":"unit","title":"용해와 용액","text":"물에 녹는 현상과 용질·용매·용액의 뜻, 용질의 종류와 물의 온도에 따른 녹는 양, 용액의 진하기를 배워요. 용해, 용질, 용매, 용액의 뜻을 말할 수 있어요. 용질이 물에 녹아도 없어지지 않는다는 것을 무게로 설명할 수 있어요. 용질의 종류와 물의 온도에 따라 녹는 양이 다르다는 것을 실험으로 알 수 있어요. 여러 가지 방법으로 용액의 진하기를 비교할 …","keywords":["용해","용질","용매","용액","진하기"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-04","grade":"e5"},
{"id":"sci-e5-04#c0","kind":"concept","title":"용해, 용질, 용매, 용액","text":"물에 설탕을 넣고 저으면 설탕이 점점 작아지다가 보이지 않게 돼요. 이처럼 어떤 물질이 다른 물질에 녹아 고르게 섞이는 현상을 용해라고 해요. 낱말 · 뜻 · 설탕물에서 용질 · 녹는 물질 · 설탕 용매 · 녹이는 물질 · 물 용액 · 용질이 용매에 녹아 고르게 섞여 있는 물질 · 설탕","keywords":["용해","용질","용매","용액"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-04","grade":"e5"},
{"id":"sci-e5-04#c1","kind":"concept","title":"녹아도 없어지지 않아요","text":"설탕이 물에 녹아 보이지 않으면 설탕이 없어진 걸까요? 무게를 재 보면 알 수 있어요. 잰 것 · 무게 물 · 100 g 각설탕 · 10 g 각설탕이 다 녹은 설탕물 · 110 g 녹이기 전의 물과 용질의 무게를 더한 값과 녹인 뒤 용액의 무게가 같아요. 설탕은 없어진 것이 아니라 눈에","keywords":["용질","용액"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-e5","unit":"sci-e5-04","grade":"e5"},
{"id":"sci-e5-04#c2","kind":"concept","title":"용질의 종류에 따라 녹는 양이 달라요","text":"온도와 양이 같은 물에 여러 가지 용질을 한 숟가락씩 넣으며 저어 보면, 용질마다 녹는 양이 달라요. 예를 들어 온도가 같은 물 50 mL씩에 소금, 설탕, 베이킹 소다를 한 숟가락씩 넣으며 저어 보면 설탕이 가장 많이 녹고, 그다음이 소금, 베이킹 소다가 가장 적게 녹아요. 용질 · ","keywords":["용질"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-e5","unit":"sci-e5-04","grade":"e5"},
{"id":"sci-e5-04#c3","kind":"concept","title":"물의 온도가 높을수록 많이 녹아요","text":"같은 양의 물에 같은 용질을 넣어도 물의 온도가 높을수록 더 많이 녹아요. 예를 들어 차가운 물과 따뜻한 물 50 mL씩에 백반(흰 알갱이 모양의 물질)을 똑같이 넣고 저으면, 차가운 물에서는 다 녹지 않고 바닥에 남지만 따뜻한 물에서는 더 많이 녹아요. 바닥에 녹지 않고 남은 용질이 ","keywords":["용질","용액"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-e5","unit":"sci-e5-04","grade":"e5"},
{"id":"sci-e5-04#c4","kind":"concept","title":"용액의 진하기 비교하기","text":"같은 양의 용매에 용질이 많이 녹아 있을수록 진한 용액이에요. 진하기는 이렇게 비교할 수 있어요. 색깔: 황설탕물처럼 색깔이 있는 용액은 진할수록 색깔이 진해요. 물체가 뜨는 정도: 같은 물체(방울토마토, 메추리알 등)를 넣으면 진한 용액일수록 물체가 높이 떠올라요. 무게: 같은 양(부","keywords":["용질","용매","용액","진하기"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-e5","unit":"sci-e5-04","grade":"e5"},
{"id":"sci-e5-04#c5","kind":"concept","title":"생활 속의 용액","text":"우리 생활에는 용액이 아주 많아요. 용액 · 용질의 예 · 쓰임 바닷물 · 소금 등 · 바닷물을 말려 소금을 얻어요 식초 · 아세트산 · 음식의 신맛을 내요 꿀물·설탕물 · 꿀·설탕 · 단맛이 나는 음료 탄산음료 · 이산화 탄소(기체) · 톡 쏘는 맛을 내요 병원의 수액 · 포도당·소금","keywords":["용질","용액","진하기"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-e5","unit":"sci-e5-04","grade":"e5"},
{"id":"sci-e5-04#t0","kind":"term","title":"용해","text":"어떤 물질이 다른 물질에 녹아 고르게 섞이는 현상이에요. 예: 설탕이 물에 녹는 것","keywords":["용해"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-04","grade":"e5"},
{"id":"sci-e5-04#t1","kind":"term","title":"용질","text":"녹는 물질이에요. 설탕물에서는 설탕, 소금물에서는 소금이에요.","keywords":["용질"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-e5","unit":"sci-e5-04","grade":"e5"},
{"id":"sci-e5-04#t2","kind":"term","title":"용매","text":"용질을 녹이는 물질이에요. 설탕물, 소금물에서는 물이에요.","keywords":["용매"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-e5","unit":"sci-e5-04","grade":"e5"},
{"id":"sci-e5-04#t3","kind":"term","title":"용액","text":"용질이 용매에 녹아 고르게 섞여 있는 물질이에요. 오래 두어도 가라앉거나 뜨는 것이 없어요. 예: 설탕물, 소금물","keywords":["용액"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-e5","unit":"sci-e5-04","grade":"e5"},
{"id":"sci-e5-04#t4","kind":"term","title":"진하기","text":"같은 양의 용매에 용질이 얼마나 많이 녹아 있는지를 나타내요. 많이 녹아 있을수록 진한 용액이에요.","keywords":["진하기"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-e5","unit":"sci-e5-04","grade":"e5"},
{"id":"sci-e5-04#f0","kind":"faq","title":"설탕이 물에 녹으면 어디로 가요?","text":"설탕은 눈에 보이지 않을 만큼 아주 작게 나뉘어 물 사이사이에 고르게 섞여 있어요. 없어진 것이 아니라서, 녹이기 전 물과 설탕의 무게를 더하면 설탕물의 무게와 같아요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-04","grade":"e5"},
{"id":"sci-e5-04#f1","kind":"faq","title":"용매는 항상 물이에요?","text":"아니에요. 물이 가장 흔한 용매라서 많이 쓰일 뿐이에요. 예를 들어 손톱에 칠한 매니큐어는 물에는 잘 녹지 않지만 다른 액체에는 녹아요. 이때는 그 액체가 용매예요.","keywords":["용매"],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-e5","unit":"sci-e5-04","grade":"e5"},
{"id":"sci-e5-04#f2","kind":"faq","title":"저어도 녹지 않는 가루는 왜 생겨요?","text":"일정한 온도의 물이 녹일 수 있는 용질의 양에는 한계가 있어요. 그 한계보다 많이 넣으면 아무리 저어도 남는 가루가 바닥에 생겨요. 물의 온도를 높이거나 물을 더 부으면 더 녹일 수 있어요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-e5","unit":"sci-e5-04","grade":"e5"},
{"id":"sci-e5-04#f3","kind":"faq","title":"용해랑 녹는 것(얼음이 녹는 것)은 같은 거예요?","text":"달라요. 얼음이 녹아 물이 되는 것은 고체가 열을 받아 액체로 변하는 상태 변화예요(4학년에서 배운 물의 상태 변화). 용해는 설탕처럼 어떤 물질이 다른 물질(물) 속에 녹아 고르게 섞이는 현상이에요. 우리말로는 둘 다 \"녹는다\"고 해서 헷갈리기 쉬워요.","keywords":["용해"],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-e5","unit":"sci-e5-04","grade":"e5"},
{"id":"sci-e5-04#m0","kind":"mistake","title":"자주 하는 실수","text":"용질이 녹으면 없어져서 무게가 줄어든다고 생각하는 실수 — 용액의 무게 = 용매의 무게 + 용질의 무게예요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e5","unit":"sci-e5-04","grade":"e5"},
{"id":"sci-e5-04#m1","kind":"mistake","title":"자주 하는 실수","text":"용질·용매·용액을 헷갈리는 실수 — 녹는 것이 용질(설탕), 녹이는 것이 용매(물), 녹아서 만들어진 것이 용액(설탕물)이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e5","unit":"sci-e5-04","grade":"e5"},
{"id":"sci-e5-04#m2","kind":"mistake","title":"자주 하는 실수","text":"실험에서 만든 용액을 맛보아 진하기를 비교하는 실수 — 실험 용액은 맛보지 않고, 색깔이나 물체가 뜨는 정도로 비교해요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e5","unit":"sci-e5-04","grade":"e5"},
{"id":"sci-e5-05","kind":"unit","title":"우리 몸의 구조와 기능","text":"뼈와 근육이 몸을 움직이는 원리와 소화·순환·호흡·배설 기관이 하는 일, 건강을 지키는 생활을 알아봐요. 뼈와 근육이 함께 몸을 움직이는 원리를 설명할 수 있어요. 소화·순환·호흡·배설 기관의 생김새와 하는 일을 말할 수 있어요. 운동할 때 여러 기관이 함께 일하는 모습을 설명하고, 건강한 생활 습관을 실천할 수 있어요.","keywords":["운동 기관","근육","소화","순환","맥박","호흡","기관지","배설","콩팥","방광"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-05","grade":"e5"},
{"id":"sci-e5-05#c0","kind":"concept","title":"뼈와 근육이 몸을 움직여요","text":"우리 몸에는 크기와 모양이 다른 뼈가 많이 있어요. 뼈는 몸의 형태를 만들고 몸을 지탱하며, 머리뼈가 뇌를, 갈비뼈가 심장과 폐를 감싸듯 몸속 기관을 보호해요. 뼈와 근육처럼 몸을 움직이는 데 관여하는 기관을 운동 기관이라고 해요. 뼈는 혼자서 움직이지 못해요. 뼈에 붙어 있는 근육이 ","keywords":["운동 기관","근육"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-05","grade":"e5"},
{"id":"sci-e5-05#c1","kind":"concept","title":"소화 기관","text":"먹은 음식물을 몸에 흡수될 수 있게 잘게 쪼개는 과정을 소화라고 하고, 소화에 관여하는 기관을 소화 기관이라고 해요. 음식물은 이 순서로 지나가요. 입 → 식도 → 위 → 작은창자 → 큰창자 → 항문 기관 · 하는 일 입 · 이로 음식물을 잘게 부수고 침과 섞어요 식도 · 삼킨 음식물을","keywords":["소화"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-e5","unit":"sci-e5-05","grade":"e5"},
{"id":"sci-e5-05#c2","kind":"concept","title":"순환 기관과 맥박","text":"혈액은 몸속을 돌며 영양소와 산소를 온몸에 전해 주고, 몸에서 생긴 이산화 탄소와 노폐물을 받아 와요. 혈액이 온몸을 도는 것을 순환이라고 하고, 순환에 관여하는 심장과 혈관을 순환 기관이라고 해요. 심장: 주먹만 한 크기로 가슴 가운데에서 조금 왼쪽에 있어요. 펌프 작용으로 혈액을 온","keywords":["순환","맥박"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-e5","unit":"sci-e5-05","grade":"e5"},
{"id":"sci-e5-05#c3","kind":"concept","title":"호흡 기관","text":"숨을 들이쉬고 내쉬는 것을 호흡이라고 하고, 호흡에 관여하는 기관을 호흡 기관이라고 해요. 코: 공기가 드나드는 곳이에요. 기관: 목 안에서 공기가 지나가는 굵은 관이에요. 기관지: 기관에서 나뉘어 폐와 이어진 관이에요. 나뭇가지처럼 갈라져 있어요. 폐: 가슴 양쪽에 하나씩 있어요. 공","keywords":["순환","호흡","기관지"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-e5","unit":"sci-e5-05","grade":"e5"},
{"id":"sci-e5-05#c4","kind":"concept","title":"배설 기관","text":"우리 몸이 영양소를 쓰고 나면 몸에 필요 없는 노폐물이 생겨요. 노폐물은 혈액에 실려 다니는데, 이것을 걸러 몸 밖으로 내보내는 것을 배설이라고 해요. 배설에 관여하는 기관이 배설 기관이에요. 콩팥: 강낭콩 모양으로, 허리의 등 쪽 양옆에 하나씩 두 개가 있어요. 혈액 속의 노폐물을 걸","keywords":["배설","콩팥","방광"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-e5","unit":"sci-e5-05","grade":"e5"},
{"id":"sci-e5-05#c5","kind":"concept","title":"운동할 때 기관들이 함께 일해요","text":"달리기를 하면 숨이 가빠지고 심장이 빨리 뛰고 땀이 나요. 왜 그럴까요? 운동을 하면 근육이 많이 움직여서 산소와 영양소가 더 많이 필요해요. 호흡 기관: 숨을 더 빠르게 쉬어 산소를 더 많이 받아들여요. 순환 기관: 심장이 더 빨리 뛰어(맥박이 빨라져) 산소와 영양소를 실은 혈액을 근","keywords":["근육","소화","순환","맥박","호흡","배설"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-e5","unit":"sci-e5-05","grade":"e5"},
{"id":"sci-e5-05#t0","kind":"term","title":"운동 기관","text":"뼈와 근육처럼 몸을 움직이는 데 관여하는 기관이에요.","keywords":["운동 기관"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-05","grade":"e5"},
{"id":"sci-e5-05#t1","kind":"term","title":"근육","text":"뼈에 붙어 있으면서 길이가 줄어들거나 늘어나 뼈를 움직이게 하는 부분이에요.","keywords":["근육"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-e5","unit":"sci-e5-05","grade":"e5"},
{"id":"sci-e5-05#t2","kind":"term","title":"소화","text":"음식물을 몸에 흡수될 수 있게 잘게 쪼개는 과정이에요.","keywords":["소화"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-e5","unit":"sci-e5-05","grade":"e5"},
{"id":"sci-e5-05#t3","kind":"term","title":"순환","text":"혈액이 심장에서 나와 혈관을 따라 온몸을 돌고 다시 심장으로 돌아오는 것이에요.","keywords":["순환"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-e5","unit":"sci-e5-05","grade":"e5"},
{"id":"sci-e5-05#t4","kind":"term","title":"맥박","text":"심장이 뛰는 것이 혈관에 전해져 손목이나 목에서 느껴지는 움직임이에요.","keywords":["맥박"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-e5","unit":"sci-e5-05","grade":"e5"},
{"id":"sci-e5-05#t5","kind":"term","title":"호흡","text":"숨을 들이쉬고 내쉬는 것이에요. 산소를 받아들이고 이산화 탄소를 내보내요.","keywords":["호흡"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-e5","unit":"sci-e5-05","grade":"e5"},
{"id":"sci-e5-05#t6","kind":"term","title":"기관지","text":"기관에서 나뉘어 폐와 이어진 공기의 통로예요. 나뭇가지처럼 갈라져 있어요.","keywords":["기관지"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-e5","unit":"sci-e5-05","grade":"e5"},
{"id":"sci-e5-05#t7","kind":"term","title":"배설","text":"혈액 속의 노폐물을 걸러 몸 밖으로 내보내는 것이에요.","keywords":["배설"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-e5","unit":"sci-e5-05","grade":"e5"},
{"id":"sci-e5-05#t8","kind":"term","title":"콩팥","text":"강낭콩 모양의 배설 기관으로, 혈액 속 노폐물을 걸러 오줌을 만들어요. 허리의 등 쪽 양옆에 두 개가 있어요.","keywords":["콩팥"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-e5","unit":"sci-e5-05","grade":"e5"},
{"id":"sci-e5-05#t9","kind":"term","title":"방광","text":"콩팥에서 만든 오줌을 모아 두었다가 몸 밖으로 내보내는 주머니 모양의 기관이에요.","keywords":["방광"],"ref":{"tab":"terms","idx":9},"subject":"sci","course":"sci-e5","unit":"sci-e5-05","grade":"e5"},
{"id":"sci-e5-05#f0","kind":"faq","title":"맥박은 왜 손목에서 느껴져요?","text":"심장이 혈액을 내보낼 때마다 혈관이 툭툭 움직이는데, 손목 안쪽이나 목처럼 혈관이 피부 가까이 지나가는 곳에서는 그 움직임을 손가락으로 느낄 수 있어요. 그래서 맥박 수는 심장이 뛰는 횟수와 같아요.","keywords":["맥박"],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-05","grade":"e5"},
{"id":"sci-e5-05#f1","kind":"faq","title":"음식물은 간이나 쓸개를 지나가요?","text":"아니에요. 음식물은 입 → 식도 → 위 → 작은창자 → 큰창자 → 항문으로만 지나가요. 간, 쓸개, 이자는 음식물이 지나가지는 않지만, 소화를 돕는 액체를 만들거나 저장해서 작은창자로 보내 소화를 도와요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-e5","unit":"sci-e5-05","grade":"e5"},
{"id":"sci-e5-05#f2","kind":"faq","title":"운동을 하면 왜 숨이 차요?","text":"운동할 때 근육은 산소를 많이 써요. 그래서 산소를 더 많이 받아들이려고 숨을 빠르고 깊게 쉬게 돼요. 운동을 멈추고 쉬면 점점 원래대로 돌아와요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-e5","unit":"sci-e5-05","grade":"e5"},
{"id":"sci-e5-05#f3","kind":"faq","title":"숨을 쉴 때 산소만 들어가고 이산화 탄소만 나와요?","text":"그렇지는 않아요. 들이쉬는 공기와 내쉬는 공기 모두 여러 기체가 섞여 있어요. 다만 내쉬는 공기는 들이쉬는 공기보다 산소가 적고 이산화 탄소가 많아요. 폐에서 산소를 받아들이고 이산화 탄소를 내보냈기 때문이에요.","keywords":[],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-e5","unit":"sci-e5-05","grade":"e5"},
{"id":"sci-e5-05#m0","kind":"mistake","title":"자주 하는 실수","text":"기관과 기관지의 순서를 헷갈리는 실수 — 굵은 기관에서 기관지가 나뉘어 나와요. 들이쉴 때는 코 → 기관 → 기관지 → 폐예요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e5","unit":"sci-e5-05","grade":"e5"},
{"id":"sci-e5-05#m1","kind":"mistake","title":"자주 하는 실수","text":"방광이 오줌을 만든다고 생각하는 실수 — 오줌은 콩팥에서 만들고, 방광은 모아 두기만 해요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e5","unit":"sci-e5-05","grade":"e5"},
{"id":"sci-e5-05#m2","kind":"mistake","title":"자주 하는 실수","text":"15초 동안 센 맥박 수를 그대로 1분 동안의 맥박 수로 쓰는 실수 — 1분은 15초의 4배이니 4를 곱해요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e5","unit":"sci-e5-05","grade":"e5"},
{"id":"sci-e5-06","kind":"unit","title":"혼합물의 분리","text":"여러 물질이 섞인 혼합물을 알갱이 크기와 물에 녹는 성질 등을 이용해 분리하는 방법을 배워요. 혼합물의 뜻을 알고 생활 속 혼합물을 찾을 수 있어요. 알갱이 크기, 섞이는 정도, 물에 녹는 성질을 이용해 혼합물을 분리할 수 있어요. 거름과 증발을 이용해 소금과 모래의 혼합물을 분리할 수 있어요. 혼합물의 분리를 이용한 생활 속 기술을 설명할 수 있어요.","keywords":["혼합물","혼합물의 분리","체","거름","거름 장치","증발","스포이트","염전","정수 장치"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-06","grade":"e5"},
{"id":"sci-e5-06#c0","kind":"concept","title":"혼합물이란?","text":"혼합물은 두 가지 이상의 물질이 섞여 있는 것이에요. 혼합물 속의 물질은 섞여 있어도 저마다의 성질이 변하지 않아요. 잡곡밥: 쌀, 콩, 보리가 섞여 있어요. 콩을 씹으면 여전히 콩 맛이 나요. 바닷물: 물에 소금 같은 여러 물질이 녹아 섞여 있어요. 그래서 짠맛이 나요. 김밥: 밥, ","keywords":["혼합물","혼합물의 분리"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-06","grade":"e5"},
{"id":"sci-e5-06#c1","kind":"concept","title":"알갱이 크기로 나누기 — 체","text":"콩과 좁쌀처럼 알갱이 크기가 다른 고체 혼합물은 체로 분리해요. 체에는 일정한 크기의 구멍이 있어요. 혼합물을 체에 넣고 흔들면 구멍보다 작은 알갱이(좁쌀)는 구멍으로 빠져나가고, 구멍보다 큰 알갱이(콩)는 체 위에 남아요. 공사장에서 모래와 자갈을 나눌 때도 큰 체를 써요. 자갈은 체","keywords":["혼합물","체"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-e5","unit":"sci-e5-06","grade":"e5"},
{"id":"sci-e5-06#c2","kind":"concept","title":"섞이지 않는 액체 나누기 — 물과 식용유","text":"물과 식용유를 컵에 넣고 저은 뒤 가만히 두면, 시간이 지나면서 두 층으로 나뉘어요. 식용유는 위층, 물은 아래층이에요. 물과 식용유는 서로 골고루 섞이지 않기 때문이에요. 이렇게 층이 나뉘면 스포이트로 위에 뜬 식용유를 조심스럽게 빨아들여 다른 그릇에 덜어 내요. 그러면 물과 식용유를","keywords":["체","스포이트"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-e5","unit":"sci-e5-06","grade":"e5"},
{"id":"sci-e5-06#c3","kind":"concept","title":"물에 녹는 성질로 나누기 — 거름","text":"소금과 모래가 섞여 있으면 알갱이 크기가 비슷해서 체로 나누기 어려워요. 이때는 소금은 물에 녹고, 모래는 물에 녹지 않는 성질을 이용해요. 혼합물에 물을 붓고 저어요. 소금은 물에 녹고 모래는 그대로 있어요. 거름 장치로 걸러요. 거름종이를 접어 깔때기에 넣고, 물을 묻혀 깔때기에 붙","keywords":["혼합물","체","거름","거름 장치"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-e5","unit":"sci-e5-06","grade":"e5"},
{"id":"sci-e5-06#c4","kind":"concept","title":"증발로 녹아 있는 고체 얻기","text":"거름종이를 빠져나온 소금물에서 소금을 다시 얻으려면 물을 증발시키면 돼요. 증발은 액체인 물이 표면에서 기체인 수증기로 변해 공기 중으로 날아가는 것이에요(4학년에서 배웠어요). 소금물을 넓은 그릇에 담아 햇볕이 잘 드는 곳에 며칠 두면 물이 증발하고 흰 소금 알갱이가 남아요. 실험실에","keywords":["체","거름","증발","염전"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-e5","unit":"sci-e5-06","grade":"e5"},
{"id":"sci-e5-06#c5","kind":"concept","title":"혼합물의 분리를 이용한 기술","text":"혼합물의 분리는 우리 생활과 환경을 지키는 기술에 쓰여요. 기술 · 이용한 분리 정수 장치 · 여러 겹의 거름 장치와 숯 등으로 물속의 찌꺼기를 걸러 깨끗한 물을 만들어요 바닷물을 마실 물로 만드는 장치 · 바닷물을 증발시킨 뒤 수증기를 차갑게 해 물로 모으거나(응결), 아주 촘촘한 막","keywords":["혼합물","혼합물의 분리","거름","거름 장치","증발","정수 장치"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-e5","unit":"sci-e5-06","grade":"e5"},
{"id":"sci-e5-06#t0","kind":"term","title":"혼합물","text":"두 가지 이상의 물질이 성질이 변하지 않은 채 섞여 있는 것이에요. 예: 잡곡, 바닷물, 김밥","keywords":["혼합물"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-06","grade":"e5"},
{"id":"sci-e5-06#t1","kind":"term","title":"혼합물의 분리","text":"섞여 있는 물질의 성질 차이를 이용해 혼합물을 각각의 물질로 나누는 것이에요.","keywords":["혼합물의 분리"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-e5","unit":"sci-e5-06","grade":"e5"},
{"id":"sci-e5-06#t2","kind":"term","title":"체","text":"일정한 크기의 구멍이 있어서 알갱이 크기가 다른 고체를 나눌 수 있는 도구예요.","keywords":["체"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-e5","unit":"sci-e5-06","grade":"e5"},
{"id":"sci-e5-06#t3","kind":"term","title":"거름","text":"거름종이 같은 거름 장치로 액체에 섞인 녹지 않는 고체를 걸러 내는 것이에요. 예: 소금물에 섞인 모래 거르기","keywords":["거름"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-e5","unit":"sci-e5-06","grade":"e5"},
{"id":"sci-e5-06#t4","kind":"term","title":"거름 장치","text":"거름종이, 깔때기, 깔때기대, 비커, 유리 막대로 꾸민 장치예요. 녹지 않은 고체는 거름종이 위에 남아요.","keywords":["거름 장치"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-e5","unit":"sci-e5-06","grade":"e5"},
{"id":"sci-e5-06#t5","kind":"term","title":"증발","text":"액체 표면에서 액체가 기체로 변해 날아가는 현상이에요. 소금물의 물을 증발시키면 소금이 남아요.","keywords":["증발"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-e5","unit":"sci-e5-06","grade":"e5"},
{"id":"sci-e5-06#t6","kind":"term","title":"스포이트","text":"고무 부분을 눌렀다 놓아 적은 양의 액체를 빨아들여 옮기는 도구예요. 물 위에 뜬 식용유를 덜어 낼 때 써요.","keywords":["스포이트"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-e5","unit":"sci-e5-06","grade":"e5"},
{"id":"sci-e5-06#t7","kind":"term","title":"염전","text":"바닷물을 가두어 햇볕과 바람으로 물을 증발시켜 소금을 얻는 곳이에요.","keywords":["염전"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-e5","unit":"sci-e5-06","grade":"e5"},
{"id":"sci-e5-06#t8","kind":"term","title":"정수 장치","text":"거름 등 혼합물을 분리하는 방법을 이용해 더러운 물을 깨끗하게 만드는 장치예요.","keywords":["정수 장치"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-e5","unit":"sci-e5-06","grade":"e5"},
{"id":"sci-e5-06#f0","kind":"faq","title":"혼합물은 왜 분리해요?","text":"필요한 물질만 얻거나 필요 없는 물질을 없애기 위해서예요. 바닷물에서 소금을 얻고, 더러운 물에서 찌꺼기를 걸러 깨끗한 물을 얻고, 쓰레기 속 철 캔을 골라 다시 쓰는 것이 모두 혼합물의 분리예요.","keywords":["혼합물"],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-06","grade":"e5"},
{"id":"sci-e5-06#f1","kind":"faq","title":"소금은 왜 거름종이에 걸러지지 않아요?","text":"소금이 물에 녹으면 눈에 보이지 않을 만큼 아주 작게 나뉘어 물속에 고루 퍼져요. 그래서 거름종이의 작은 구멍도 물과 함께 쉽게 빠져나가요. 녹지 않은 모래 알갱이는 구멍보다 커서 걸러져요.","keywords":["거름"],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-e5","unit":"sci-e5-06","grade":"e5"},
{"id":"sci-e5-06#f2","kind":"faq","title":"식용유는 왜 물 위에 떠요?","text":"물과 식용유는 서로 섞이지 않고, 같은 부피일 때 식용유가 물보다 가벼워요. 그래서 식용유가 위층, 물이 아래층이 돼요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-e5","unit":"sci-e5-06","grade":"e5"},
{"id":"sci-e5-06#m0","kind":"mistake","title":"자주 하는 실수","text":"소금물을 거름종이로 거르면 소금이 걸러진다고 생각하는 실수 — 물에 녹은 소금은 거름종이를 빠져나가요. 소금은 물을 증발시켜 얻어요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e5","unit":"sci-e5-06","grade":"e5"},
{"id":"sci-e5-06#m1","kind":"mistake","title":"자주 하는 실수","text":"거른 액체가 맑고 투명하면 아무것도 녹아 있지 않다고 생각하는 실수 — 소금물이나 설탕물도 투명해요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e5","unit":"sci-e5-06","grade":"e5"},
{"id":"sci-e5-06#m2","kind":"mistake","title":"자주 하는 실수","text":"알갱이 크기가 비슷한 소금과 모래를 체로 나누려는 실수 — 소금은 물에 녹고 모래는 녹지 않는 성질을 이용해요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e5","unit":"sci-e5-06","grade":"e5"},
{"id":"sci-e5-07","kind":"unit","title":"날씨와 우리 생활","text":"기온·습도·바람 같은 기상 요소를 알고, 이슬·안개·구름의 차이와 고기압·저기압에 따른 날씨를 알아봐요. 기상 요소를 알고 날씨가 생활에 주는 영향을 말할 수 있어요. 건습구 습도계와 습도표로 습도를 구할 수 있어요. 이슬·안개·구름의 공통점과 차이점을 설명할 수 있어요. 고기압과 저기압 사이에서 바람이 부는 방향과 그때의 날씨를 설명할 수 있어요.","keywords":["기상 요소","기온","습도","건습구 습도계","응결","이슬","안개","구름","기압","바람"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-07","grade":"e5"},
{"id":"sci-e5-07#c0","kind":"concept","title":"기상 요소와 우리 생활","text":"날씨는 그날그날의 비, 구름, 바람, 기온 같은 대기의 상태예요. 날씨를 나타내는 요소를 기상 요소라고 해요. 기상 요소 · 뜻 기온 · 공기의 온도 습도 · 공기 중에 수증기가 포함된 정도 바람 · 공기가 이동하는 것 (부는 방향과 빠르기) 구름의 양 · 하늘을 구름이 덮고 있는 정도","keywords":["기상 요소","기온","습도","구름","바람"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-07","grade":"e5"},
{"id":"sci-e5-07#c1","kind":"concept","title":"습도와 건습구 습도계","text":"습도는 공기 중에 수증기가 포함된 정도예요. 퍼센트(%)로 나타내요. 건습구 습도계는 온도계 두 개로 습도를 재요. 건구 온도계: 그냥 둔 온도계. 지금 공기의 기온을 나타내요. 습구 온도계: 끝(액체샘)을 물에 젖은 헝겊으로 감싼 온도계. 헝겊의 물이 증발하면서 열을 빼앗아 가서 보통","keywords":["기온","습도","건습구 습도계"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-e5","unit":"sci-e5-07","grade":"e5"},
{"id":"sci-e5-07#c2","kind":"concept","title":"이슬·안개·구름","text":"이슬, 안개, 구름은 모두 공기 중의 수증기가 응결해서 생겨요. 응결은 기체인 수증기가 차가워져 액체인 물방울로 변하는 것이에요(4학년에서 배웠어요). 다른 점은 생기는 곳이에요. · 생기는 곳과 모습 이슬 · 밤에 차가워진 풀잎·나뭇잎 같은 물체의 표면에 물방울로 맺혀요 안개 · 밤에","keywords":["응결","이슬","안개","구름"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-e5","unit":"sci-e5-07","grade":"e5"},
{"id":"sci-e5-07#c3","kind":"concept","title":"기압 — 고기압과 저기압","text":"공기는 눈에 보이지 않지만 무게가 있어요. 공기의 무게 때문에 생기는 누르는 힘을 기압이라고 해요. 같은 부피의 공기라도 온도에 따라 무게가 달라요. 차가운 공기는 같은 부피 안에 공기 알갱이가 더 많아서 더 무거워요 → 기압이 높아요. 따뜻한 공기는 같은 부피 안에 공기 알갱이가 더 ","keywords":["기압"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-e5","unit":"sci-e5-07","grade":"e5"},
{"id":"sci-e5-07#c4","kind":"concept","title":"바람은 고기압에서 저기압으로","text":"두 곳의 기압이 다르면 공기가 고기압에서 저기압으로 이동해요. 이렇게 공기가 이동하는 것이 바람이에요. 기압 차이가 클수록 바람이 세게 불어요. 바닷가의 바람 낮: 햇볕을 받으면 육지가 바다보다 빨리 데워져요. 육지 위 공기는 따뜻해져 저기압, 바다 위 공기는 상대적으로 차가워 고기압이","keywords":["기압","바람"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-e5","unit":"sci-e5-07","grade":"e5"},
{"id":"sci-e5-07#c5","kind":"concept","title":"고기압과 저기압의 날씨","text":"고기압과 저기압일 때는 날씨가 달라요. · 공기의 움직임 · 날씨 고기압 · 공기가 위에서 아래로 내려와요 · 구름이 잘 생기지 않아 대체로 맑아요 저기압 · 공기가 아래에서 위로 올라가요 · 올라간 공기가 차가워져 구름이 생겨 흐리거나 비·눈이 와요 저기압에서 공기가 위로 올라가면 온","keywords":["응결","구름","기압"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-e5","unit":"sci-e5-07","grade":"e5"},
{"id":"sci-e5-07#t0","kind":"term","title":"기상 요소","text":"날씨를 나타내는 요소예요. 기온, 습도, 바람, 구름의 양, 강수량 등이 있어요.","keywords":["기상 요소"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-07","grade":"e5"},
{"id":"sci-e5-07#t1","kind":"term","title":"기온","text":"공기의 온도예요.","keywords":["기온"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-e5","unit":"sci-e5-07","grade":"e5"},
{"id":"sci-e5-07#t2","kind":"term","title":"습도","text":"공기 중에 수증기가 포함된 정도예요. %로 나타내요.","keywords":["습도"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-e5","unit":"sci-e5-07","grade":"e5"},
{"id":"sci-e5-07#t3","kind":"term","title":"건습구 습도계","text":"건구 온도계와, 끝을 젖은 헝겊으로 감싼 습구 온도계로 습도를 재는 기구예요.","keywords":["건습구 습도계"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-e5","unit":"sci-e5-07","grade":"e5"},
{"id":"sci-e5-07#t4","kind":"term","title":"응결","text":"기체인 수증기가 차가워져 액체인 물로 변하는 현상이에요. 이슬·안개·구름이 생기는 까닭이에요.","keywords":["응결"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-e5","unit":"sci-e5-07","grade":"e5"},
{"id":"sci-e5-07#t5","kind":"term","title":"이슬","text":"공기 중의 수증기가 차가워진 물체 표면에 응결해 물방울로 맺힌 것이에요.","keywords":["이슬"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-e5","unit":"sci-e5-07","grade":"e5"},
{"id":"sci-e5-07#t6","kind":"term","title":"안개","text":"땅 가까이의 공기가 차가워져 수증기가 응결해, 땅 가까이 공중에 작은 물방울로 떠 있는 것이에요.","keywords":["안개"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-e5","unit":"sci-e5-07","grade":"e5"},
{"id":"sci-e5-07#t7","kind":"term","title":"구름","text":"공기가 하늘 높이 올라가며 차가워져 수증기가 응결하거나 얼음 알갱이로 변해 떠 있는 것이에요.","keywords":["구름"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-e5","unit":"sci-e5-07","grade":"e5"},
{"id":"sci-e5-07#t8","kind":"term","title":"기압","text":"공기의 무게 때문에 생기는 누르는 힘이에요. 주위보다 높은 곳은 고기압, 낮은 곳은 저기압이에요.","keywords":["기압"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-e5","unit":"sci-e5-07","grade":"e5"},
{"id":"sci-e5-07#t9","kind":"term","title":"바람","text":"기압 차이 때문에 공기가 고기압에서 저기압으로 이동하는 것이에요.","keywords":["바람"],"ref":{"tab":"terms","idx":9},"subject":"sci","course":"sci-e5","unit":"sci-e5-07","grade":"e5"},
{"id":"sci-e5-07#f0","kind":"faq","title":"습구 온도계는 왜 건구 온도계보다 온도가 낮아요?","text":"습구 온도계를 감싼 젖은 헝겊에서 물이 증발하면서 주변의 열을 가져가기 때문이에요. 공기가 메마를수록 물이 더 잘 증발해서 습구 온도가 더 많이 내려가요. 그래서 두 온도의 차로 습도를 알 수 있어요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-07","grade":"e5"},
{"id":"sci-e5-07#f1","kind":"faq","title":"공기에도 정말 무게가 있어요?","text":"네, 있어요. 공기를 넣은 공과 공기를 뺀 공의 무게를 정밀한 저울로 재면 공기를 넣은 공이 조금 더 무거워요. 우리 머리 위에는 아주 높은 곳까지 공기가 쌓여 있어서 그 무게로 누르는 힘, 곧 기압이 생겨요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-e5","unit":"sci-e5-07","grade":"e5"},
{"id":"sci-e5-07#f2","kind":"faq","title":"안개랑 구름은 같은 거예요?","text":"만들어지는 원리는 같아요. 둘 다 수증기가 응결한 작은 물방울이에요. 다만 안개는 땅 가까이에 떠 있고, 구름은 하늘 높이 떠 있다는 점이 달라요. 그래서 높은 산에 오르면 아래에서 구름으로 보이던 것이 안개처럼 느껴지기도 해요.","keywords":["안개","구름"],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-e5","unit":"sci-e5-07","grade":"e5"},
{"id":"sci-e5-07#m0","kind":"mistake","title":"자주 하는 실수","text":"바람이 저기압에서 고기압으로 분다고 생각하는 실수 — 바람은 기압이 높은 곳에서 낮은 곳으로 불어요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e5","unit":"sci-e5-07","grade":"e5"},
{"id":"sci-e5-07#m1","kind":"mistake","title":"자주 하는 실수","text":"습도표에서 습구 온도를 세로줄로 찾는 실수 — 세로줄은 건구 온도, 가로줄은 두 온도의 차예요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e5","unit":"sci-e5-07","grade":"e5"},
{"id":"sci-e5-07#m2","kind":"mistake","title":"자주 하는 실수","text":"이슬이 하늘에서 내려온다고 생각하는 실수 — 이슬은 공기 중의 수증기가 차가워진 물체 표면에 응결해 생겨요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e5","unit":"sci-e5-07","grade":"e5"},
{"id":"sci-e5-08","kind":"unit","title":"열과 우리 생활","text":"온도를 정확히 재는 방법과 전도·대류·복사로 열이 이동하는 모습, 단열을 이용한 생활을 배워요. 온도의 뜻을 알고 여러 가지 온도계로 온도를 바르게 잴 수 있어요. 온도가 다른 두 물체가 닿을 때 열이 어떻게 이동하는지 설명할 수 있어요. 전도·대류·복사로 열이 이동하는 모습을 구별할 수 있어요. 단열의 뜻을 알고 생활 속 단열의 예를 찾을 수 있어요.","keywords":["온도","열","적외선 온도계","전도","대류","복사","단열","열 변색 붙임딱지"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-08","grade":"e5"},
{"id":"sci-e5-08#c0","kind":"concept","title":"온도와 온도계","text":"온도는 물체가 차갑거나 따뜻한 정도를 숫자로 나타낸 것이에요. 단위는 °C이고 \"섭씨 도\"라고 읽어요. 25 °C는 \"섭씨 이십오 도\"예요. 공기의 온도는 기온, 물의 온도는 수온, 몸의 온도는 체온이라고 해요. 손으로 만져 보는 느낌은 사람마다, 그때그때 달라서 정확하지 않아요. 그래","keywords":["온도","적외선 온도계"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-08","grade":"e5"},
{"id":"sci-e5-08#c1","kind":"concept","title":"온도가 다른 두 물체가 닿으면","text":"온도가 다른 두 물체가 닿아 있으면 열이 온도가 높은 물체에서 온도가 낮은 물체로 이동해요. 따뜻한 물이 담긴 비커를 차가운 물이 담긴 수조에 넣으면 비커 속 따뜻한 물은 열을 잃어 온도가 내려가고, 수조 속 차가운 물은 열을 얻어 온도가 올라가요. 시간이 지나면 두 물의 온도가 같아지","keywords":["온도","열"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-e5","unit":"sci-e5-08","grade":"e5"},
{"id":"sci-e5-08#c2","kind":"concept","title":"고체에서 열의 이동 — 전도","text":"고체에서 열은 온도가 높은 곳에서 낮은 곳으로 고체 물질을 따라 이동해요. 이것을 전도라고 해요. 구리판에 열 변색 붙임딱지(온도에 따라 색이 변하는 딱지)를 붙이고 한쪽을 가열하면, 가열한 곳에서 가까운 곳부터 먼 곳으로 차례로 색이 변해요. 판의 중간이 잘려 있으면 열은 잘린 틈을 ","keywords":["온도","열","전도","열 변색 붙임딱지"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-e5","unit":"sci-e5-08","grade":"e5"},
{"id":"sci-e5-08#c3","kind":"concept","title":"액체와 기체에서 열의 이동 — 대류","text":"액체나 기체를 데우면, 온도가 높아진 물질이 위로 올라가고 위에 있던 물질이 아래로 밀려 내려오면서 열이 이동해요. 이것을 대류라고 해요. 물: 냄비 바닥을 데우면 바닥의 따뜻해진 물이 위로 올라가고, 위의 차가운 물이 아래로 내려와 다시 데워져요. 이렇게 돌면서 물 전체가 데워져요. ","keywords":["온도","열","대류"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-e5","unit":"sci-e5-08","grade":"e5"},
{"id":"sci-e5-08#c4","kind":"concept","title":"빛으로 바로 전해지는 열 — 복사","text":"햇볕을 쬐면 몸이 따뜻해지지요? 태양과 우리 사이에는 열을 전해 줄 물질이 거의 없는데도 열이 전해져요. 이처럼 열이 다른 물질을 거치지 않고 직접 전해지는 것을 복사라고 해요. 햇볕 아래와 그늘: 햇볕이 직접 닿는 곳은 따뜻하고, 햇볕이 가려진 그늘은 시원해요. 난로나 모닥불 앞: 불","keywords":["열","복사"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-e5","unit":"sci-e5-08","grade":"e5"},
{"id":"sci-e5-08#c5","kind":"concept","title":"단열 — 열의 이동을 막기","text":"단열은 두 물질 사이에서 열이 이동하지 못하게 막는 것이에요. 열이 잘 이동하지 않는 물질(공기, 솜, 스타이로폼, 털 등)을 사이에 두어 단열해요. 보온병: 벽이 두 겹이고, 그 사이의 공기를 거의 빼 두어 열이 잘 빠져나가거나 들어오지 못해요. 그래서 뜨거운 물은 뜨겁게, 차가운 물","keywords":["온도","열","단열"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-e5","unit":"sci-e5-08","grade":"e5"},
{"id":"sci-e5-08#t0","kind":"term","title":"온도","text":"물체가 차갑거나 따뜻한 정도를 숫자로 나타낸 것이에요. 단위는 °C(섭씨 도)예요.","keywords":["온도"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-08","grade":"e5"},
{"id":"sci-e5-08#t1","kind":"term","title":"열","text":"온도가 높은 물체에서 낮은 물체로 이동하며 물체의 온도를 바꾸는 것이에요.","keywords":["열"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-e5","unit":"sci-e5-08","grade":"e5"},
{"id":"sci-e5-08#t2","kind":"term","title":"적외선 온도계","text":"물체 표면을 겨누고 버튼을 눌러, 닿지 않고 표면의 온도를 재는 온도계예요.","keywords":["적외선 온도계"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-e5","unit":"sci-e5-08","grade":"e5"},
{"id":"sci-e5-08#t3","kind":"term","title":"전도","text":"고체에서 열이 온도가 높은 곳에서 낮은 곳으로 물질을 따라 이동하는 것이에요. 예: 숟가락 손잡이가 뜨거워져요.","keywords":["전도"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-e5","unit":"sci-e5-08","grade":"e5"},
{"id":"sci-e5-08#t4","kind":"term","title":"대류","text":"액체나 기체에서 데워진 물질이 위로 올라가고 차가운 물질이 아래로 내려오며 열이 이동하는 것이에요.","keywords":["대류"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-e5","unit":"sci-e5-08","grade":"e5"},
{"id":"sci-e5-08#t5","kind":"term","title":"복사","text":"열이 다른 물질을 거치지 않고 직접 전해지는 것이에요. 예: 햇볕을 쬐면 따뜻해요.","keywords":["복사"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-e5","unit":"sci-e5-08","grade":"e5"},
{"id":"sci-e5-08#t6","kind":"term","title":"단열","text":"두 물질 사이에서 열이 이동하지 못하게 막는 것이에요. 예: 보온병, 이중창","keywords":["단열"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-e5","unit":"sci-e5-08","grade":"e5"},
{"id":"sci-e5-08#t7","kind":"term","title":"열 변색 붙임딱지","text":"온도에 따라 색이 변하는 딱지예요. 열이 이동하는 모습을 눈으로 볼 수 있게 해 줘요.","keywords":["열 변색 붙임딱지"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-e5","unit":"sci-e5-08","grade":"e5"},
{"id":"sci-e5-08#f0","kind":"faq","title":"차가움도 이동하는 거 아니에요?","text":"아니에요. 이동하는 것은 언제나 열이고, 열은 온도가 높은 곳에서 낮은 곳으로 가요. 얼음을 손에 쥐면 차가운 것은 손의 열이 얼음으로 빠져나가기 때문이에요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-08","grade":"e5"},
{"id":"sci-e5-08#f1","kind":"faq","title":"같은 방에 있는데 쇠 문고리가 나무 문보다 더 차가워요. 왜 그래요?","text":"온도는 같아요. 쇠는 열이 빨리 이동해서 손의 열을 빨리 가져가고, 나무는 천천히 가져가요. 그래서 쇠가 더 차갑게 느껴져요. 적외선 온도계로 재 보면 두 곳의 온도가 거의 같게 나와요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-e5","unit":"sci-e5-08","grade":"e5"},
{"id":"sci-e5-08#f2","kind":"faq","title":"전도, 대류, 복사는 어떻게 구별해요?","text":"무엇을 통해 열이 이동하는지 보면 돼요. 고체를 따라 이동하면 전도, 액체나 기체가 직접 움직이며 옮기면 대류, 물질을 거치지 않고 바로 전해지면 복사예요.","keywords":["전도","대류","복사"],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-e5","unit":"sci-e5-08","grade":"e5"},
{"id":"sci-e5-08#m0","kind":"mistake","title":"자주 하는 실수","text":"\"차가움\"이 이동한다고 생각하는 실수 — 이동하는 것은 열이고, 언제나 온도가 높은 곳에서 낮은 곳으로 가요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e5","unit":"sci-e5-08","grade":"e5"},
{"id":"sci-e5-08#m1","kind":"mistake","title":"자주 하는 실수","text":"만졌을 때 더 차갑게 느껴지는 금속이 실제로 온도가 더 낮다고 생각하는 실수 — 같은 곳에 오래 있던 물체는 온도가 같아요. 금속이 손의 열을 빨리 가져갈 뿐이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e5","unit":"sci-e5-08","grade":"e5"},
{"id":"sci-e5-08#m2","kind":"mistake","title":"자주 하는 실수","text":"데워진 공기가 아래로 내려간다고 생각하는 실수 — 데워진 공기는 위로 올라가요. 그래서 난로는 낮은 곳, 에어컨은 높은 곳에 둬요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e5","unit":"sci-e5-08","grade":"e5"},
{"id":"sci-e5-09","kind":"unit","title":"자원과 에너지","text":"생활에 쓰이는 자원이 한정되어 있음을 알고, 재생에너지와 자원·에너지를 아껴 쓰는 방법을 알아봐요. 생활에서 쓰는 여러 가지 자원을 알고, 자원이 한정되어 있음을 설명할 수 있어요. 재생에너지의 종류와 특징을 말할 수 있어요. 자원과 에너지를 효율적으로 쓰는 방법을 찾아 생활에서 실천할 수 있어요.","keywords":["자원","화석 연료","광물","재생에너지","바이오 에너지","지열 에너지","에너지 소비 효율 등급","대기 전력","재활용","새활용"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-09","grade":"e5"},
{"id":"sci-e5-09#c0","kind":"concept","title":"생활 속 여러 가지 자원","text":"자원은 사람이 생활하는 데 쓰려고 자연에서 얻는 것이에요. 자원 · 쓰임의 예 물 · 마시고 씻고, 농사짓고, 공장에서 물건을 만들 때 써요 산림(숲) · 나무로 집·가구·종이를 만들어요. 숲은 맑은 공기를 만들고 빗물을 머금어요 광물 · 철, 구리, 알루미늄 같은 금속을 얻어 자동차·","keywords":["자원","화석 연료","광물"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-09","grade":"e5"},
{"id":"sci-e5-09#c1","kind":"concept","title":"자원은 한정되어 있어요","text":"화석 연료와 광물은 만들어지는 데 아주 오랜 시간(수백만 년 이상)이 걸려요. 그래서 한번 쓰면 사람이 사는 동안에는 다시 만들어지지 않아요. 땅속에 묻혀 있는 양도 정해져 있어서, 계속 쓰기만 하면 언젠가 바닥나요. 재활용을 하면 자원을 아낄 수 있어요. 하지만 재활용을 해도 자원이 ","keywords":["자원","화석 연료","광물","재활용"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-e5","unit":"sci-e5-09","grade":"e5"},
{"id":"sci-e5-09#c2","kind":"concept","title":"재생에너지의 종류","text":"재생에너지는 햇빛, 바람, 물, 땅속의 열처럼 자연에서 계속 다시 얻을 수 있는 에너지예요. 재생에너지 · 얻는 방법 태양 에너지 · 태양 전지판으로 햇빛을 받아 전기를 만들거나(태양광), 햇볕의 열로 물을 데워요(태양열) 풍력 에너지 · 바람으로 커다란 날개를 돌려 전기를 만들어요 수","keywords":["재생에너지","바이오 에너지","지열 에너지"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-e5","unit":"sci-e5-09","grade":"e5"},
{"id":"sci-e5-09#c3","kind":"concept","title":"재생에너지의 특징과 지속가능한 에너지 이용","text":"재생에너지의 좋은 점 자연에서 계속 다시 얻을 수 있어서 바닥날 걱정이 적어요. 화석 연료보다 온실 기체와 공기를 더럽히는 물질을 훨씬 적게 내보내요. 아쉬운 점 날씨, 계절, 장소에 따라 얻는 양이 달라요. 태양광은 밤이나 흐린 날, 풍력은 바람이 약한 날에 전기를 적게 만들어요. 시","keywords":["화석 연료","재생에너지"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-e5","unit":"sci-e5-09","grade":"e5"},
{"id":"sci-e5-09#c4","kind":"concept","title":"에너지를 효율적으로 쓰기","text":"에너지 소비 효율 등급은 전기 제품이 에너지를 얼마나 알뜰하게 쓰는지 1등급부터 5등급까지 나타낸 표시예요. 같은 일을 할 때 1등급이 에너지를 가장 적게 써요. 대기 전력은 전원을 꺼 두어도 플러그가 꽂혀 있으면 조금씩 쓰이는 전기예요. 쓰지 않는 플러그를 뽑거나 스위치가 달린 멀티탭","keywords":["에너지 소비 효율 등급","대기 전력"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-e5","unit":"sci-e5-09","grade":"e5"},
{"id":"sci-e5-09#c5","kind":"concept","title":"재활용·새활용과 생활 속 실천","text":"재활용은 다 쓴 물건을 원료로 되돌려 다시 쓰는 것이에요. 예: 페트병을 녹여 옷감의 실을 만들어요. 알루미늄 캔을 녹여 다시 캔을 만들어요. 새활용은 버려지는 물건에 아이디어와 디자인을 더해 더 쓸모 있는 새 물건으로 만드는 것이에요. 예: 버려진 현수막으로 가방을 만들어요. 낡은 청","keywords":["재활용","새활용"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-e5","unit":"sci-e5-09","grade":"e5"},
{"id":"sci-e5-09#t0","kind":"term","title":"자원","text":"사람이 생활하는 데 쓰려고 자연에서 얻는 것이에요. 예: 물, 산림, 광물, 화석 연료","keywords":["자원"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-09","grade":"e5"},
{"id":"sci-e5-09#t1","kind":"term","title":"화석 연료","text":"아주 오랜 옛날 생물이 땅속에 묻혀 긴 시간 동안 변해서 만들어진 연료예요. 예: 석탄, 석유, 천연가스","keywords":["화석 연료"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-e5","unit":"sci-e5-09","grade":"e5"},
{"id":"sci-e5-09#t2","kind":"term","title":"광물","text":"땅속에서 얻는 자원으로, 철·구리·알루미늄 같은 금속의 원료가 돼요.","keywords":["광물"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-e5","unit":"sci-e5-09","grade":"e5"},
{"id":"sci-e5-09#t3","kind":"term","title":"재생에너지","text":"햇빛, 바람, 물, 땅속의 열, 생물처럼 자연에서 계속 다시 얻을 수 있는 에너지예요.","keywords":["재생에너지"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-e5","unit":"sci-e5-09","grade":"e5"},
{"id":"sci-e5-09#t4","kind":"term","title":"바이오 에너지","text":"나무, 볏짚, 음식물 쓰레기, 가축 분뇨 같은 생물에서 나온 것으로 만든 에너지예요.","keywords":["바이오 에너지"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-e5","unit":"sci-e5-09","grade":"e5"},
{"id":"sci-e5-09#t5","kind":"term","title":"지열 에너지","text":"땅속의 열을 이용하는 에너지예요. 난방을 하거나 전기를 만들어요.","keywords":["지열 에너지"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-e5","unit":"sci-e5-09","grade":"e5"},
{"id":"sci-e5-09#t6","kind":"term","title":"에너지 소비 효율 등급","text":"전기 제품이 에너지를 얼마나 알뜰하게 쓰는지 1~5등급으로 나타낸 것이에요. 1등급이 에너지를 가장 적게 써요.","keywords":["에너지 소비 효율 등급"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-e5","unit":"sci-e5-09","grade":"e5"},
{"id":"sci-e5-09#t7","kind":"term","title":"대기 전력","text":"전원을 꺼도 플러그가 꽂혀 있으면 조금씩 쓰이는 전기예요.","keywords":["대기 전력"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-e5","unit":"sci-e5-09","grade":"e5"},
{"id":"sci-e5-09#t8","kind":"term","title":"재활용","text":"다 쓴 물건을 원료로 되돌려 다시 쓰는 것이에요. 예: 알루미늄 캔을 녹여 새 캔 만들기","keywords":["재활용"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-e5","unit":"sci-e5-09","grade":"e5"},
{"id":"sci-e5-09#t9","kind":"term","title":"새활용","text":"버려지는 물건에 아이디어와 디자인을 더해 더 쓸모 있는 새 물건으로 만드는 것이에요. 업사이클링이라고도 해요.","keywords":["새활용"],"ref":{"tab":"terms","idx":9},"subject":"sci","course":"sci-e5","unit":"sci-e5-09","grade":"e5"},
{"id":"sci-e5-09#f0","kind":"faq","title":"재생에너지만 쓰면 안 돼요?","text":"점점 늘려 가고 있지만 아직은 어려운 점이 있어요. 날씨에 따라 얻는 양이 들쭉날쭉하고, 남는 전기를 저장하는 기술과 시설을 더 갖춰야 하거든요. 그래서 재생에너지를 늘리면서 동시에 에너지를 아껴 쓰는 것이 중요해요.","keywords":["재생에너지"],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-e5","unit":"sci-e5-09","grade":"e5"},
{"id":"sci-e5-09#f1","kind":"faq","title":"재활용이랑 새활용은 뭐가 달라요?","text":"재활용은 다 쓴 물건을 녹이거나 부수어 원료로 되돌린 뒤 다시 만드는 것이에요(알루미늄 캔 → 새 캔). 새활용은 버려지는 물건에 아이디어를 더해 더 쓸모 있는 새 물건으로 바꾸는 것이에요(현수막 → 가방).","keywords":["재활용","새활용"],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-e5","unit":"sci-e5-09","grade":"e5"},
{"id":"sci-e5-09#f2","kind":"faq","title":"전원을 껐는데 왜 플러그까지 뽑아야 해요?","text":"전원을 꺼도 플러그가 꽂혀 있으면 리모컨 신호를 기다리거나 시계를 켜 두느라 전기가 조금씩 쓰여요. 이것을 대기 전력이라고 해요. 하나하나는 적어도 집 안 모든 제품을 합치면 꽤 많아요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-e5","unit":"sci-e5-09","grade":"e5"},
{"id":"sci-e5-09#m0","kind":"mistake","title":"자주 하는 실수","text":"재활용을 하면 자원을 끝없이 쓸 수 있다고 생각하는 실수 — 재활용 과정에서도 자원이 일부 사라지고 에너지가 들어요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e5","unit":"sci-e5-09","grade":"e5"},
{"id":"sci-e5-09#m1","kind":"mistake","title":"자주 하는 실수","text":"에너지 소비 효율 등급의 숫자가 클수록 좋은 제품이라고 생각하는 실수 — 1등급이 에너지를 가장 적게 써요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e5","unit":"sci-e5-09","grade":"e5"},
{"id":"sci-e5-09#m2","kind":"mistake","title":"자주 하는 실수","text":"재생에너지는 단점이 없다고 생각하는 실수 — 날씨·장소에 따라 얻는 양이 달라지고 시설 비용이 들어요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e5","unit":"sci-e5-09","grade":"e5"},
{"id":"sci-e6-01","kind":"unit","title":"산과 염기","text":"지시약으로 용액을 산성과 염기성으로 나누고, 두 용액의 성질과 섞을 때의 변화, 생활 속 쓰임을 알아봐요. 리트머스 종이와 페놀프탈레인 용액의 색 변화로 용액을 산성과 염기성으로 나눌 수 있어요. 산성 용액과 염기성 용액이 여러 물질을 어떻게 녹이는지 말할 수 있어요. 산성 용액에 염기성 용액을 넣을 때 지시약의 색이 어떻게 변하는지 설명할 수 있어요. …","keywords":["지시약","산성 용액","염기성 용액","리트머스 종이","페놀프탈레인 용액","붉은 양배추 지시약","산성비","제산제"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e6","unit":"sci-e6-01","grade":"e6"},
{"id":"sci-e6-01#c0","kind":"concept","title":"지시약으로 용액 나누기","text":"식초, 레몬즙, 비눗물, 유리 세정제처럼 겉보기에 비슷한 용액도 성질이 서로 달라요. 이때 쓰는 것이 지시약이에요. 지시약: 어떤 용액에 넣었을 때, 그 용액의 성질에 따라 색깔이 달라지는 물질이에요. 지시약 · 산성 용액에서 · 염기성 용액에서 푸른색 리트머스 종이 · 붉은색으로 변해","keywords":["지시약","산성 용액","염기성 용액","리트머스 종이","페놀프탈레인 용액"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e6","unit":"sci-e6-01","grade":"e6"},
{"id":"sci-e6-01#c1","kind":"concept","title":"붉은 양배추 지시약 만들기","text":"지시약은 집에 있는 먹을 수 있는 재료로도 만들 수 있어요. 붉은 양배추에는 용액의 성질에 따라 색이 바뀌는 색소가 들어 있어요. 붉은 양배추를 잘게 잘라 그릇에 담아요. 따뜻한 물을 붓고 잠시 두면 물이 보라색으로 우러나요. (뜨거운 물과 칼은 어른과 함께 써요.) 건더기를 걸러 낸 ","keywords":["지시약","붉은 양배추 지시약"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-e6","unit":"sci-e6-01","grade":"e6"},
{"id":"sci-e6-01#c2","kind":"concept","title":"산성 용액과 염기성 용액의 성질","text":"산성 용액과 염기성 용액은 녹이는 물질이 서로 달라요. 넣은 물질 · 산성 용액(묽은 염산) · 염기성 용액(묽은 수산화 나트륨 용액) 달걀 껍데기 · 기포가 생기며 녹아요 · 변화가 거의 없어요 대리석 조각 · 기포가 생기며 녹아요 · 변화가 거의 없어요 삶은 달걀흰자 · 변화가 거의","keywords":["산성 용액","염기성 용액"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-e6","unit":"sci-e6-01","grade":"e6"},
{"id":"sci-e6-01#c3","kind":"concept","title":"산성 용액에 염기성 용액을 넣으면","text":"붉은 양배추 지시약을 넣은 묽은 염산(산성)은 붉은색이에요. 여기에 묽은 수산화 나트륨 용액(염기성)을 조금씩 넣어 보면 색이 차례로 변해요. 붉은색 → 보라색에 가까운 색 → 푸른색·초록색 계열 염기성 용액을 넣을수록 산성이 점점 약해지다가, 계속 넣으면 염기성 용액으로 바뀌어요. 반","keywords":["지시약","산성 용액","염기성 용액","페놀프탈레인 용액","붉은 양배추 지시약"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-e6","unit":"sci-e6-01","grade":"e6"},
{"id":"sci-e6-01#c4","kind":"concept","title":"생활 속 산성·염기성 용액","text":"우리는 산성과 염기성이 서로의 성질을 약하게 하는 것을 생활에서 이용해요. 식초로 생선 비린내 줄이기: 생선 비린내를 내는 물질은 염기성이에요. 산성인 식초나 레몬즙을 뿌리면 비린내가 줄어요. 제산제: 위에서 나오는 위액은 산성이에요. 속이 쓰릴 때 먹는 제산제는 염기성 성질이 있어 위","keywords":["염기성 용액","제산제"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-e6","unit":"sci-e6-01","grade":"e6"},
{"id":"sci-e6-01#c5","kind":"concept","title":"산성화로 생기는 환경 피해","text":"자동차와 공장에서 나오는 오염 물질이 공기 중의 물에 녹으면 빗물이 보통보다 산성이 강한 산성비가 내려요. 산성비는 대리석으로 만든 건물·조각상을 녹여 망가뜨리고, 숲의 나무를 약하게 만들어요. 호수와 강, 흙이 산성으로 변하면 그곳에 사는 생물이 살기 어려워져요. 산성화된 흙에는 염기","keywords":["산성비"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-e6","unit":"sci-e6-01","grade":"e6"},
{"id":"sci-e6-01#t0","kind":"term","title":"지시약","text":"어떤 용액에 넣었을 때 그 용액의 성질에 따라 색깔이 변하는 물질이에요. 예: 리트머스 종이, 페놀프탈레인 용액, 붉은 양배추 지시약","keywords":["지시약"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-e6","unit":"sci-e6-01","grade":"e6"},
{"id":"sci-e6-01#t1","kind":"term","title":"산성 용액","text":"푸른색 리트머스 종이를 붉은색으로 변하게 하는 용액이에요. 예: 식초, 레몬즙, 탄산수, 묽은 염산","keywords":["산성 용액"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-e6","unit":"sci-e6-01","grade":"e6"},
{"id":"sci-e6-01#t2","kind":"term","title":"염기성 용액","text":"붉은색 리트머스 종이를 푸른색으로, 페놀프탈레인 용액을 붉은색으로 변하게 하는 용액이에요. 예: 비눗물, 유리 세정제, 석회수, 묽은 수산화 나트륨 용액","keywords":["염기성 용액"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-e6","unit":"sci-e6-01","grade":"e6"},
{"id":"sci-e6-01#t3","kind":"term","title":"리트머스 종이","text":"용액을 묻혀 색 변화로 산성과 염기성을 알아보는 종이 지시약이에요. 푸른색과 붉은색 두 가지가 있어요.","keywords":["리트머스 종이"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-e6","unit":"sci-e6-01","grade":"e6"},
{"id":"sci-e6-01#t4","kind":"term","title":"페놀프탈레인 용액","text":"색이 없는 지시약이에요. 산성 용액에서는 변하지 않고, 염기성 용액에서 붉은색으로 변해요.","keywords":["페놀프탈레인 용액"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-e6","unit":"sci-e6-01","grade":"e6"},
{"id":"sci-e6-01#t5","kind":"term","title":"붉은 양배추 지시약","text":"붉은 양배추를 우려 만든 보라색 지시약이에요. 산성에서 붉은색 계열, 염기성에서 푸른색·초록색 계열로 변해요.","keywords":["붉은 양배추 지시약"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-e6","unit":"sci-e6-01","grade":"e6"},
{"id":"sci-e6-01#t6","kind":"term","title":"산성비","text":"자동차·공장에서 나온 오염 물질이 녹아 보통 빗물보다 산성이 강해진 비예요. 건물과 숲, 호수의 생물에 피해를 줘요.","keywords":["산성비"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-e6","unit":"sci-e6-01","grade":"e6"},
{"id":"sci-e6-01#t7","kind":"term","title":"제산제","text":"위산이 너무 많아 속이 쓰릴 때 먹는 약이에요. 염기성 성질이 있어 산성인 위액을 약하게 해요.","keywords":["제산제"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-e6","unit":"sci-e6-01","grade":"e6"},
{"id":"sci-e6-01#f0","kind":"faq","title":"물은 산성이에요, 염기성이에요?","text":"깨끗한 물은 산성도 염기성도 아니에요. 그래서 리트머스 종이 두 가지 모두 색이 변하지 않아요. 설탕물, 소금물도 마찬가지예요. 다만 우리가 마시는 물에는 여러 물질이 조금씩 녹아 있어서, 아주 약한 산성이나 염기성을 띠기도 해요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-e6","unit":"sci-e6-01","grade":"e6"},
{"id":"sci-e6-01#f1","kind":"faq","title":"리트머스 종이가 붉게 변하면 무조건 산성이에요?","text":"푸른색 리트머스 종이가 붉게 변했다면 산성이에요. 그런데 붉은색 리트머스 종이는 원래 붉으니, 붉은 종이가 그대로 붉은 것만으로는 산성인지 아닌지 알 수 없어요. 어떤 색의 종이가 어떻게 변했는지 함께 봐야 해요.","keywords":["리트머스 종이"],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-e6","unit":"sci-e6-01","grade":"e6"},
{"id":"sci-e6-01#f2","kind":"faq","title":"식초나 레몬즙을 손에 묻혀도 괜찮아요?","text":"먹을 수 있는 식초와 레몬즙은 산성이 약해서 잠깐 닿는 것은 괜찮지만, 상처나 눈에 들어가면 따가워요. 실험이 끝나면 손을 씻어요. 묽은 염산이나 수산화 나트륨 용액, 청소용 세제는 피부와 눈을 다치게 할 수 있으니 집에서 실험하지 않아요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-e6","unit":"sci-e6-01","grade":"e6"},
{"id":"sci-e6-01#f3","kind":"faq","title":"산성비를 맞으면 머리카락이 빠져요?","text":"산성비는 보통 빗물보다 산성이 조금 강한 정도라서, 한 번 맞는다고 몸이 크게 다치지는 않아요. 산성비가 걱정되는 까닭은 오랫동안 내리면서 숲, 호수의 생물, 건물과 문화재에 피해가 쌓이기 때문이에요. 그래도 비를 맞은 뒤에는 씻는 것이 좋아요.","keywords":["산성비"],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-e6","unit":"sci-e6-01","grade":"e6"},
{"id":"sci-e6-01#m0","kind":"mistake","title":"자주 하는 실수","text":"\"붉은색으로 변하면 산성\"이라고만 외우는 실수 — 페놀프탈레인 용액은 염기성에서 붉은색이 돼요. 지시약 이름과 색을 함께 기억해요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e6","unit":"sci-e6-01","grade":"e6"},
{"id":"sci-e6-01#m1","kind":"mistake","title":"자주 하는 실수","text":"달걀 껍데기와 달걀흰자를 헷갈리는 실수 — 단단한 껍데기(대리석과 같은 무리)는 산성에, 말랑한 삶은 흰자(두부와 같은 무리)는 염기성에 녹아요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e6","unit":"sci-e6-01","grade":"e6"},
{"id":"sci-e6-01#m2","kind":"mistake","title":"자주 하는 실수","text":"생활 속 쓰임에서 짝을 거꾸로 생각하는 실수 — 비린내 물질과 위액 중 염기성인 것은 비린내 물질, 산성인 것은 위액이에요. 반대 성질의 물질로 약하게 해요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e6","unit":"sci-e6-01","grade":"e6"},
{"id":"sci-e6-02","kind":"unit","title":"물체의 운동","text":"운동하는 물체의 위치 변화를 나타내고, 이동 거리와 걸린 시간으로 속력을 구해 빠르기를 비교해요. 운동하는 물체의 위치 변화를 모눈(간단한 좌표 평면)에 나타낼 수 있어요. 빠르기가 변하는 운동과 빠르기가 일정한 운동을 구별할 수 있어요. 이동 거리와 걸린 시간으로 물체의 빠르기를 비교하고 속력을 구할 수 있어요. 속력과 관련된 교통안전 수칙과 안전장치를…","keywords":["운동","기준점","이동 거리","걸린 시간","속력","m/s","km/h","어린이 보호 구역"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e6","unit":"sci-e6-02","grade":"e6"},
{"id":"sci-e6-02#c0","kind":"concept","title":"물체의 운동과 위치 변화","text":"시간이 지나면서 물체의 위치가 바뀌는 것을 운동이라고 해요. 위치가 바뀌지 않으면 운동하지 않는 것이에요. 위치를 정확하게 나타내려면 먼저 기준점을 정해요. 그리고 모눈(간단한 좌표 평면) 위에서 기준점으로부터 가로로 몇 칸, 세로로 몇 칸 떨어져 있는지로 위치를 나타내요. 그림은 굴러","keywords":["운동","기준점","이동 거리","걸린 시간"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e6","unit":"sci-e6-02","grade":"e6"},
{"id":"sci-e6-02#c1","kind":"concept","title":"빠르기가 변하는 운동과 일정한 운동","text":"물체의 운동은 빠르기에 따라 두 가지로 나눌 수 있어요. 운동 · 뜻 · 예 빠르기가 변하는 운동 · 움직이는 동안 빨라지거나 느려져요 · 출발하는 자동차, 롤러코스터, 이륙하는 비행기, 떨어지는 공, 그네 빠르기가 일정한 운동 · 움직이는 동안 빠르기가 변하지 않아요 · 자동계단(에스","keywords":["운동"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-e6","unit":"sci-e6-02","grade":"e6"},
{"id":"sci-e6-02#c2","kind":"concept","title":"같은 거리를 이동할 때 빠르기 비교","text":"달리기 경주처럼 같은 거리를 이동한 물체는 걸린 시간으로 빠르기를 비교해요. 걸린 시간이 짧을수록 더 빨라요. 이름 · 50 m 달리기 기록 민수 · 9초 지아 · 8초 서준 · 10초 세 사람 모두 50 m를 달렸으니 시간만 비교하면 돼요. 걸린 시간이 가장 짧은 지아가 가장 빠르고,","keywords":["걸린 시간"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-e6","unit":"sci-e6-02","grade":"e6"},
{"id":"sci-e6-02#c3","kind":"concept","title":"같은 시간 동안 이동할 때 빠르기 비교","text":"이번에는 같은 시간 동안 이동한 물체를 비교해요. 이때는 이동 거리로 빠르기를 비교해요. 같은 시간 동안 이동 거리가 길수록 더 빨라요. 예를 들어 종이 자동차 세 대를 동시에 출발시키고 5초 뒤에 멈추게 했더니 이동 거리가 다음과 같았어요. 자동차 · 5초 동안 이동 거리 빨간 자동차","keywords":["이동 거리"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-e6","unit":"sci-e6-02","grade":"e6"},
{"id":"sci-e6-02#c4","kind":"concept","title":"속력 구하기","text":"이동 거리도 걸린 시간도 서로 다르면 어떻게 비교할까요? 이때는 속력을 구해요. 속력: 물체가 단위 시간(1초, 1시간 같은 일정한 시간) 동안 이동한 거리예요. (속력) = (이동 거리)÷(걸린 시간) 예: 자전거가 10초 동안 50 m를 이동했다면 속력은 50÷10 = 5, 곧 5 ","keywords":["이동 거리","걸린 시간","속력","m/s","km/h"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-e6","unit":"sci-e6-02","grade":"e6"},
{"id":"sci-e6-02#c5","kind":"concept","title":"속력과 교통안전","text":"속력이 큰 자동차는 갑자기 멈추기 어렵고, 부딪히면 피해가 훨씬 커요. 그래서 도로에는 속력을 줄이고 사람을 지키는 장치가 있어요. 안전장치 · 하는 일 안전띠 · 자동차가 갑자기 멈출 때 몸이 앞으로 튀어 나가지 않게 잡아 줘요 에어백 · 부딪힐 때 순간적으로 부풀어 몸에 오는 충격을","keywords":["속력","km/h","어린이 보호 구역"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-e6","unit":"sci-e6-02","grade":"e6"},
{"id":"sci-e6-02#t0","kind":"term","title":"운동","text":"시간이 지나면서 물체의 위치가 바뀌는 것이에요.","keywords":["운동"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-e6","unit":"sci-e6-02","grade":"e6"},
{"id":"sci-e6-02#t1","kind":"term","title":"기준점","text":"물체의 위치를 나타낼 때 기준으로 삼는 점이에요. 기준점에서 어느 방향으로 얼마나 떨어져 있는지로 위치를 나타내요.","keywords":["기준점"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-e6","unit":"sci-e6-02","grade":"e6"},
{"id":"sci-e6-02#t2","kind":"term","title":"이동 거리","text":"물체가 움직인 거리예요. 단위는 m, km 등을 써요.","keywords":["이동 거리"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-e6","unit":"sci-e6-02","grade":"e6"},
{"id":"sci-e6-02#t3","kind":"term","title":"걸린 시간","text":"물체가 움직이는 데 걸린 시간이에요. 단위는 초, 분, 시간 등을 써요.","keywords":["걸린 시간"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-e6","unit":"sci-e6-02","grade":"e6"},
{"id":"sci-e6-02#t4","kind":"term","title":"속력","text":"물체가 단위 시간(1초, 1시간 등) 동안 이동한 거리예요. 이동 거리를 걸린 시간으로 나누어 구해요. 예: 10초 동안 50 m를 가면 5 m/s","keywords":["속력"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-e6","unit":"sci-e6-02","grade":"e6"},
{"id":"sci-e6-02#t5","kind":"term","title":"m/s","text":"1초 동안 몇 m를 이동하는지 나타내는 속력의 단위예요. \"미터 매 초\" 또는 \"초속 ○ 미터\"라고 읽어요.","keywords":["m/s"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-e6","unit":"sci-e6-02","grade":"e6"},
{"id":"sci-e6-02#t6","kind":"term","title":"km/h","text":"1시간 동안 몇 km를 이동하는지 나타내는 속력의 단위예요. \"킬로미터 매 시\" 또는 \"시속 ○ 킬로미터\"라고 읽어요.","keywords":["km/h"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-e6","unit":"sci-e6-02","grade":"e6"},
{"id":"sci-e6-02#t7","kind":"term","title":"어린이 보호 구역","text":"학교나 유치원 둘레의 도로에서 어린이를 지키려고 자동차의 속력을 제한하는 곳이에요.","keywords":["어린이 보호 구역"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-e6","unit":"sci-e6-02","grade":"e6"},
{"id":"sci-e6-02#f0","kind":"faq","title":"달리기 기록은 숫자가 크면 빠른 거예요?","text":"아니에요. 달리기 기록은 걸린 시간이라서 숫자가 작을수록 빨라요. 반대로 속력(m/s, km/h)은 숫자가 클수록 빨라요. 숫자가 시간인지 속력인지 먼저 확인해요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-e6","unit":"sci-e6-02","grade":"e6"},
{"id":"sci-e6-02#f1","kind":"faq","title":"속력은 왜 나눗셈으로 구해요?","text":"속력은 \"1초(또는 1시간) 동안 간 거리\"예요. 10초 동안 50 m를 갔다면, 50 m를 10초에 똑같이 나누어 주면 1초 동안 간 거리가 나와요. 그래서 이동 거리를 걸린 시간으로 나눠요.","keywords":["속력"],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-e6","unit":"sci-e6-02","grade":"e6"},
{"id":"sci-e6-02#f2","kind":"faq","title":"m/s랑 km/h는 어떻게 읽어요?","text":"5 m/s는 \"5 미터 매 초\" 또는 \"초속 5 미터\", 60 km/h는 \"60 킬로미터 매 시\" 또는 \"시속 60 킬로미터\"라고 읽어요. 빗금(/) 앞은 거리, 뒤는 시간의 단위예요.","keywords":["m/s","km/h"],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-e6","unit":"sci-e6-02","grade":"e6"},
{"id":"sci-e6-02#f3","kind":"faq","title":"자동차에 에어백이 있으면 안전띠를 안 매도 돼요?","text":"아니에요. 에어백은 안전띠를 맨 사람을 함께 지키도록 만들어졌어요. 안전띠가 몸을 자리에 잡아 주어야 에어백이 제대로 충격을 줄여 줄 수 있어요. 차를 타면 뒷자리에서도 꼭 안전띠를 매요.","keywords":[],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-e6","unit":"sci-e6-02","grade":"e6"},
{"id":"sci-e6-02#m0","kind":"mistake","title":"자주 하는 실수","text":"같은 거리를 달린 기록을 비교할 때 숫자가 큰 사람이 빠르다고 생각하는 실수 — 기록(걸린 시간)은 짧을수록 빨라요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e6","unit":"sci-e6-02","grade":"e6"},
{"id":"sci-e6-02#m1","kind":"mistake","title":"자주 하는 실수","text":"속력을 구할 때 거리와 시간을 곱하거나, 시간을 거리로 나누는 실수 — 속력은 이동 거리 ÷ 걸린 시간이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e6","unit":"sci-e6-02","grade":"e6"},
{"id":"sci-e6-02#m2","kind":"mistake","title":"자주 하는 실수","text":"거리와 시간이 모두 다를 때 가장 멀리 간 물체가 가장 빠르다고 생각하는 실수 — 속력을 구해서 비교해요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e6","unit":"sci-e6-02","grade":"e6"},
{"id":"sci-e6-03","kind":"unit","title":"식물의 구조와 기능","text":"생물의 기본 단위인 세포를 현미경으로 관찰하고, 뿌리·줄기·잎·꽃이 하는 일을 실험으로 알아봐요. 세포의 뜻을 알고, 식물 세포의 핵·세포막·세포벽을 말할 수 있어요. 뿌리와 줄기의 생김새와 하는 일을 설명할 수 있어요. 잎에서 일어나는 광합성과 증산 작용을 실험 결과로 설명할 수 있어요. 꽃의 구조를 알고, 꽃가루받이로 씨가 만들어지는 과정을 말할 수 …","keywords":["세포","세포벽","핵","뿌리털","광합성","증산 작용","기공","꽃가루받이"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e6","unit":"sci-e6-03","grade":"e6"},
{"id":"sci-e6-03#c0","kind":"concept","title":"생물의 기본 단위, 세포","text":"모든 생물은 세포로 이루어져 있어요. 세포는 생물을 이루는 가장 기본이 되는 단위예요. 대부분의 세포는 아주 작아서 맨눈으로는 보이지 않고 현미경으로 관찰해요. 양파 껍질 안쪽의 얇은 막을 떼어 염색 약품을 떨어뜨리고 현미경으로 보면, 벽돌을 쌓은 듯한 작은 방들이 보여요. 하나하나가 ","keywords":["세포","세포벽","핵"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e6","unit":"sci-e6-03","grade":"e6"},
{"id":"sci-e6-03#c1","kind":"concept","title":"뿌리의 생김새와 하는 일","text":"뿌리는 생김새에 따라 두 가지로 나눌 수 있어요. 고추·민들레처럼 굵고 곧은 뿌리에 가는 뿌리가 붙어 있는 것 파·강아지풀처럼 굵기가 비슷한 뿌리 여러 개가 수염처럼 난 것 뿌리 끝부분에는 솜털처럼 가는 뿌리털이 많이 나 있어요. 뿌리털은 흙과 닿는 넓이를 넓혀 물을 더 잘 흡수하게 해","keywords":["뿌리털"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-e6","unit":"sci-e6-03","grade":"e6"},
{"id":"sci-e6-03#c2","kind":"concept","title":"줄기의 생김새와 하는 일","text":"줄기는 뿌리와 잎을 이어 주는 부분이에요. 줄기가 하는 일 물이 이동하는 통로: 뿌리에서 흡수한 물이 줄기를 거쳐 잎까지 올라가요. 지지 기능: 식물이 서 있도록 받쳐 줘요. 저장 기능: 감자처럼 줄기에 양분을 저장하기도 해요. 색소 물 실험: 백합이나 봉선화 줄기를 붉은 색소 물에 꽂","keywords":[],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-e6","unit":"sci-e6-03","grade":"e6"},
{"id":"sci-e6-03#c3","kind":"concept","title":"잎에서 양분을 만드는 광합성","text":"식물은 먹이를 먹지 않고 스스로 양분을 만들어요. 광합성: 식물이 빛을 받아, 뿌리에서 흡수한 물과 공기 중의 이산화 탄소를 이용해 스스로 양분(녹말)을 만드는 일이에요. 광합성은 주로 잎에서 일어나요. 확인 실험 같은 식물의 잎 하나는 알루미늄 포일로 싸서 빛을 막고, 다른 잎은 그대","keywords":["광합성"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-e6","unit":"sci-e6-03","grade":"e6"},
{"id":"sci-e6-03#c4","kind":"concept","title":"잎에서 물이 빠져나가는 증산 작용","text":"뿌리에서 흡수해 잎까지 올라온 물은 어떻게 될까요? 증산 작용: 잎에 도달한 물이 수증기가 되어 잎 밖으로 빠져나가는 것이에요. 물은 주로 잎에 있는 아주 작은 구멍인 기공을 통해 빠져나가요. 기공은 잎의 뒷면에 더 많아요. 확인 실험: 잎이 있는 줄기와 잎을 모두 딴 줄기를 같은 양의","keywords":["증산 작용","기공"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-e6","unit":"sci-e6-03","grade":"e6"},
{"id":"sci-e6-03#c5","kind":"concept","title":"꽃의 구조와 꽃가루받이","text":"꽃은 씨를 만들어 식물이 자손을 퍼뜨리게 하는 곳이에요. 꽃은 대부분 네 부분으로 되어 있어요. 구조 · 하는 일 암술 · 꽃가루를 받아 씨를 만들어요 수술 · 꽃가루를 만들어요 꽃잎 · 암술과 수술을 보호하고, 곤충을 끌어들여요 꽃받침 · 꽃잎을 받치고 보호해요 꽃가루받이: 수술에서 ","keywords":["꽃가루받이"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-e6","unit":"sci-e6-03","grade":"e6"},
{"id":"sci-e6-03#t0","kind":"term","title":"세포","text":"생물을 이루는 가장 기본이 되는 단위예요. 대부분 아주 작아서 현미경으로 관찰해요.","keywords":["세포"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-e6","unit":"sci-e6-03","grade":"e6"},
{"id":"sci-e6-03#t1","kind":"term","title":"세포벽","text":"식물 세포의 세포막 바깥을 둘러싼 두껍고 단단한 벽이에요. 동물 세포에는 없어요.","keywords":["세포벽"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-e6","unit":"sci-e6-03","grade":"e6"},
{"id":"sci-e6-03#t2","kind":"term","title":"핵","text":"세포 안의 둥근 부분으로, 세포가 살아가는 데 필요한 여러 일을 조절해요.","keywords":["핵"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-e6","unit":"sci-e6-03","grade":"e6"},
{"id":"sci-e6-03#t3","kind":"term","title":"뿌리털","text":"뿌리 끝부분에 솜털처럼 난 가는 털이에요. 물을 잘 흡수하게 해 줘요.","keywords":["뿌리털"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-e6","unit":"sci-e6-03","grade":"e6"},
{"id":"sci-e6-03#t4","kind":"term","title":"광합성","text":"식물이 빛을 받아 물과 이산화 탄소로 양분(녹말)을 만드는 일이에요. 주로 잎에서 일어나요.","keywords":["광합성"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-e6","unit":"sci-e6-03","grade":"e6"},
{"id":"sci-e6-03#t5","kind":"term","title":"증산 작용","text":"잎에 도달한 물이 수증기가 되어 기공을 통해 잎 밖으로 빠져나가는 것이에요.","keywords":["증산 작용"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-e6","unit":"sci-e6-03","grade":"e6"},
{"id":"sci-e6-03#t6","kind":"term","title":"기공","text":"잎에 있는 아주 작은 구멍이에요. 물이 수증기가 되어 이곳으로 빠져나가요. 잎의 뒷면에 더 많아요.","keywords":["기공"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-e6","unit":"sci-e6-03","grade":"e6"},
{"id":"sci-e6-03#t7","kind":"term","title":"꽃가루받이","text":"수술에서 만든 꽃가루가 암술로 옮겨지는 것이에요. 곤충, 새, 바람, 물이 옮겨 줘요.","keywords":["꽃가루받이"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-e6","unit":"sci-e6-03","grade":"e6"},
{"id":"sci-e6-03#f0","kind":"faq","title":"감자는 땅속에 있는데 왜 뿌리가 아니에요?","text":"감자에는 싹이 나는 눈이 있고, 땅속으로 뻗은 줄기 끝이 양분을 저장해 커진 것이라 줄기예요. 고구마는 뿌리가 양분을 저장해 커진 것이라 뿌리예요. 땅속에 있다고 모두 뿌리는 아니에요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-e6","unit":"sci-e6-03","grade":"e6"},
{"id":"sci-e6-03#f1","kind":"faq","title":"식물은 밤에도 광합성을 해요?","text":"광합성에는 빛이 꼭 필요해요. 그래서 빛이 없는 밤에는 광합성을 하지 못해요. 낮에 만든 양분은 저장해 두었다가 밤에도 쓰여요.","keywords":["광합성"],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-e6","unit":"sci-e6-03","grade":"e6"},
{"id":"sci-e6-03#f2","kind":"faq","title":"꽃이 없는 식물도 있어요?","text":"네, 있어요. 고사리와 이끼는 꽃이 피지 않고, 씨 대신 포자로 퍼져요. 이번 단원에서 배운 꽃가루받이와 씨 만들기는 꽃이 피는 식물의 이야기예요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-e6","unit":"sci-e6-03","grade":"e6"},
{"id":"sci-e6-03#f3","kind":"faq","title":"화분에 물을 너무 많이 주면 왜 안 좋아요?","text":"뿌리도 숨을 쉬어야 하는데, 흙이 늘 물에 잠겨 있으면 뿌리가 숨을 쉬기 어려워 상할 수 있어요. 흙의 겉이 마르면 물을 주는 것처럼, 식물마다 알맞은 양을 주는 것이 좋아요.","keywords":[],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-e6","unit":"sci-e6-03","grade":"e6"},
{"id":"sci-e6-03#m0","kind":"mistake","title":"자주 하는 실수","text":"땅속에 있으면 모두 뿌리라고 생각하는 실수 — 고구마는 뿌리, 감자는 줄기예요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e6","unit":"sci-e6-03","grade":"e6"},
{"id":"sci-e6-03#m1","kind":"mistake","title":"자주 하는 실수","text":"광합성과 증산 작용을 헷갈리는 실수 — 광합성은 양분(녹말)을 만드는 일, 증산 작용은 물이 수증기로 빠져나가는 일이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e6","unit":"sci-e6-03","grade":"e6"},
{"id":"sci-e6-03#m2","kind":"mistake","title":"자주 하는 실수","text":"꽃가루를 만드는 곳을 암술이라고 하는 실수 — 꽃가루는 수술에서 만들고, 암술은 꽃가루를 받아 씨를 만들어요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e6","unit":"sci-e6-03","grade":"e6"},
{"id":"sci-e6-04","kind":"unit","title":"지구의 운동","text":"하루 동안 태양과 별이 움직이는 까닭을 지구의 자전으로, 계절마다 별자리가 바뀌는 까닭을 공전으로 알아봐요. 하루 동안 태양과 별의 위치가 어떻게 변하는지 말할 수 있어요. 지구의 자전을 알고, 자전으로 태양과 별의 움직임과 낮과 밤을 설명할 수 있어요. 지구의 공전을 알고, 계절에 따라 보이는 별자리가 달라지는 까닭을 설명할 수 있어요.","keywords":["자전축","지구의 자전","지구의 공전","낮","밤","별자리"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e6","unit":"sci-e6-04","grade":"e6"},
{"id":"sci-e6-04#c0","kind":"concept","title":"하루 동안 태양과 별의 위치 변화","text":"남쪽 하늘을 바라보고 서면 왼쪽이 동쪽, 오른쪽이 서쪽이에요. 하루 동안 태양을 관찰하면, 아침에 동쪽 하늘에서 떠올라 낮 12시 30분 무렵 남쪽 하늘에서 가장 높이 뜨고, 저녁에 서쪽 하늘로 져요. 남쪽 하늘을 바라볼 때 태양은 왼쪽에서 오른쪽으로 움직이는 것처럼 보여요. 밤하늘의 ","keywords":["낮","밤"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e6","unit":"sci-e6-04","grade":"e6"},
{"id":"sci-e6-04#c1","kind":"concept","title":"지구의 자전","text":"자전축: 지구의 북극과 남극을 이은 가상의 직선이에요. 지구의 자전축은 기울어져 있어요. 지구의 자전: 지구가 자전축을 중심으로 서쪽에서 동쪽으로, 하루에 한 바퀴씩 도는 것이에요. 북극 위에서 내려다보면 시계 반대 방향으로 돌아요. 그런데 우리는 지구와 함께 돌고 있어서 지구가 도는 ","keywords":["자전축","지구의 자전"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-e6","unit":"sci-e6-04","grade":"e6"},
{"id":"sci-e6-04#c2","kind":"concept","title":"지구의 자전으로 생기는 낮과 밤","text":"지구는 스스로 빛을 내지 못하고 태양 빛을 받아요. 그래서 태양 빛을 받는 쪽은 낮, 받지 못하는 반대쪽은 밤이 돼요. 지구가 자전하기 때문에 어느 한 곳은 태양 빛을 받는 쪽으로 왔다가, 다시 빛을 받지 못하는 쪽으로 가요. 그래서 낮과 밤이 번갈아 나타나요. 모형 실험: 어두운 방에","keywords":["지구의 자전","낮","밤"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-e6","unit":"sci-e6-04","grade":"e6"},
{"id":"sci-e6-04#c3","kind":"concept","title":"지구의 공전","text":"지구는 제자리에서 자전만 하는 것이 아니에요. 지구의 공전: 지구가 태양을 중심으로 그 둘레를 일 년에 한 바퀴씩 도는 것이에요. 공전하는 방향도 자전과 같이 서쪽에서 동쪽이에요. 지구는 자전하면서 동시에 공전해요. 팽이가 제자리에서 빙글빙글 돌면서 큰 원을 따라 이동하는 모습을 떠올리","keywords":["자전축","지구의 공전","낮","밤","별자리"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-e6","unit":"sci-e6-04","grade":"e6"},
{"id":"sci-e6-04#c4","kind":"concept","title":"계절에 따라 보이는 별자리가 달라지는 까닭","text":"봄, 여름, 가을, 겨울에 밤하늘에서 잘 보이는 별자리는 서로 달라요. 예를 들어 겨울 밤하늘에서는 오리온자리가 잘 보이지만, 여름 밤에는 보기 어려워요. 까닭: 지구가 태양 둘레를 공전하면서 지구의 위치가 계절마다 달라져요. 밤에는 우리가 태양의 반대쪽 하늘을 보게 돼요. 그래서 밤에","keywords":["낮","밤","별자리"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-e6","unit":"sci-e6-04","grade":"e6"},
{"id":"sci-e6-04#t0","kind":"term","title":"자전축","text":"지구의 북극과 남극을 이은 가상의 직선이에요. 지구의 자전축은 기울어져 있어요.","keywords":["자전축"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-e6","unit":"sci-e6-04","grade":"e6"},
{"id":"sci-e6-04#t1","kind":"term","title":"지구의 자전","text":"지구가 자전축을 중심으로 서쪽에서 동쪽으로 하루에 한 바퀴씩 도는 것이에요.","keywords":["지구의 자전"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-e6","unit":"sci-e6-04","grade":"e6"},
{"id":"sci-e6-04#t2","kind":"term","title":"지구의 공전","text":"지구가 태양을 중심으로 서쪽에서 동쪽으로 일 년에 한 바퀴씩 도는 것이에요.","keywords":["지구의 공전"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-e6","unit":"sci-e6-04","grade":"e6"},
{"id":"sci-e6-04#t3","kind":"term","title":"낮","text":"지구에서 태양 빛을 받는 쪽이에요. 지구가 자전하면서 낮과 밤이 번갈아 나타나요.","keywords":["낮"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-e6","unit":"sci-e6-04","grade":"e6"},
{"id":"sci-e6-04#t4","kind":"term","title":"밤","text":"지구에서 태양 빛을 받지 못하는 쪽이에요.","keywords":["밤"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-e6","unit":"sci-e6-04","grade":"e6"},
{"id":"sci-e6-04#t5","kind":"term","title":"별자리","text":"밤하늘에서 밝은 별들을 이어 동물, 물건, 사람 모양 등으로 이름을 붙인 것이에요. 예: 오리온자리, 북두칠성이 있는 큰곰자리","keywords":["별자리"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-e6","unit":"sci-e6-04","grade":"e6"},
{"id":"sci-e6-04#f0","kind":"faq","title":"지구가 그렇게 빨리 도는데 왜 우리는 어지럽지 않아요?","text":"지구는 아주 크고 일정한 빠르기로 부드럽게 돌아요. 우리와 공기, 땅, 바다가 모두 함께 돌기 때문에 도는 것을 느끼지 못해요. 흔들림 없이 달리는 기차 안에서 눈을 감으면 움직이는지 잘 모르는 것과 비슷해요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-e6","unit":"sci-e6-04","grade":"e6"},
{"id":"sci-e6-04#f1","kind":"faq","title":"태양이 지구 둘레를 도는 거 아니에요?","text":"태양이 지구 둘레를 도는 것처럼 보이지만, 실제로는 지구가 자전하기 때문에 그렇게 보이는 거예요. 옛날 사람들도 오랫동안 태양이 지구 둘레를 돈다고 생각했지만, 과학자들이 관찰과 연구로 지구가 돈다는 것을 밝혀냈어요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-e6","unit":"sci-e6-04","grade":"e6"},
{"id":"sci-e6-04#f2","kind":"faq","title":"낮에도 하늘에 별이 있어요?","text":"네, 있어요. 낮에도 별은 하늘에 떠 있지만 햇빛이 훨씬 밝아서 보이지 않아요. 밝은 방에서 작은 손전등 불빛이 잘 안 보이는 것과 같아요.","keywords":["낮"],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-e6","unit":"sci-e6-04","grade":"e6"},
{"id":"sci-e6-04#f3","kind":"faq","title":"자전축이 기울어져 있으면 무엇이 달라져요?","text":"자전축이 기울어진 채로 지구가 공전하기 때문에 계절이 생겨요. 자세한 까닭은 2학기 \"계절의 변화\" 단원에서 배워요.","keywords":["자전축"],"ref":{"tab":"faq","idx":3},"subject":"sci","course":"sci-e6","unit":"sci-e6-04","grade":"e6"},
{"id":"sci-e6-04#m0","kind":"mistake","title":"자주 하는 실수","text":"태양이 동쪽에서 서쪽으로 움직이니 지구도 동쪽에서 서쪽으로 돈다고 생각하는 실수 — 지구는 서쪽에서 동쪽으로 자전해서, 태양이 반대 방향으로 움직이는 것처럼 보여요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e6","unit":"sci-e6-04","grade":"e6"},
{"id":"sci-e6-04#m1","kind":"mistake","title":"자주 하는 실수","text":"낮과 밤이 공전 때문이라고 생각하는 실수 — 낮과 밤은 자전(하루) 때문이고, 계절마다 별자리가 바뀌는 것이 공전(일 년) 때문이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e6","unit":"sci-e6-04","grade":"e6"},
{"id":"sci-e6-04#m2","kind":"mistake","title":"자주 하는 실수","text":"남쪽 하늘을 볼 때 동쪽과 서쪽을 거꾸로 생각하는 실수 — 남쪽을 보면 왼쪽이 동쪽, 오른쪽이 서쪽이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e6","unit":"sci-e6-04","grade":"e6"},
{"id":"sci-e6-05","kind":"unit","title":"계절의 변화","text":"하루 동안 태양 고도와 그림자 길이·기온이 어떻게 함께 변하는지 알고, 계절이 바뀌는 까닭을 기울어진 자전축으로 설명해요. 태양 고도의 뜻을 알고 태양 고도 측정기로 안전하게 잴 수 있어요. 하루 동안 태양 고도·그림자 길이·기온의 관계를 설명할 수 있어요. 계절에 따라 태양의 남중 고도·낮의 길이·기온이 어떻게 달라지는지 말할 수 있어요. 계절이 바뀌는…","keywords":["태양 고도","남중","남중 고도","태양 고도 측정기","자전축","자전","공전"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e6","unit":"sci-e6-05","grade":"e6"},
{"id":"sci-e6-05#c0","kind":"concept","title":"태양 고도와 재는 방법","text":"태양 고도는 태양이 지표면(땅)과 이루는 각이에요. 태양이 땅 가까이 낮게 있으면 태양 고도가 작고, 하늘 높이 떠 있으면 태양 고도가 커요. 태양 고도는 0°부터 90°까지예요. 태양 고도는 태양 고도 측정기로 재요. 평평한 판 위에 막대를 똑바로 세우고 햇빛이 드는 곳에 놓아요. 막","keywords":["태양 고도","태양 고도 측정기"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e6","unit":"sci-e6-05","grade":"e6"},
{"id":"sci-e6-05#c1","kind":"concept","title":"하루 동안 태양 고도·그림자 길이·기온","text":"아침에 태양이 동쪽에서 뜰 때는 태양 고도가 낮아요. 태양 고도는 점점 높아지다가 태양이 정남쪽에 왔을 때 가장 높아요. 이것을 태양이 남중했다고 하고, 이때의 태양 고도를 태양의 남중 고도라고 해요. 우리나라에서는 낮 12시 30분 무렵이에요. 그 뒤로 태양 고도는 다시 낮아져요. 태","keywords":["태양 고도","남중","남중 고도"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-e6","unit":"sci-e6-05","grade":"e6"},
{"id":"sci-e6-05#c2","kind":"concept","title":"계절에 따른 남중 고도·낮의 길이·기온","text":"하루 중 가장 높은 태양 고도인 남중 고도는 계절마다 달라요. · 여름 · 봄·가을 · 겨울 태양의 남중 고도 · 가장 높다 · 중간 · 가장 낮다 낮의 길이 · 가장 길다 · 중간 · 가장 짧다 기온 · 가장 높다 · 중간 · 가장 낮다 예를 들어 서울에서 태양의 남중 고도는 여름(6","keywords":["태양 고도","남중","남중 고도"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-e6","unit":"sci-e6-05","grade":"e6"},
{"id":"sci-e6-05#c3","kind":"concept","title":"남중 고도가 높으면 왜 더울까?","text":"태양의 남중 고도가 높을수록 기온이 높은 까닭은 같은 넓이의 땅에 도달하는 태양 에너지의 양이 많아지기 때문이에요. 손전등으로 확인할 수 있어요. 손전등을 종이에 똑바로(수직으로) 비추면 빛이 좁은 곳에 모여 밝아요. 비스듬히 비추면 같은 빛이 넓은 곳에 퍼져서 어두워요. 태양 고도가 ","keywords":["태양 고도","남중","남중 고도"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-e6","unit":"sci-e6-05","grade":"e6"},
{"id":"sci-e6-05#c4","kind":"concept","title":"계절이 바뀌는 까닭","text":"지구는 자전축(지구가 스스로 도는 축)이 약 23.5° 기울어진 채로 태양 둘레를 한 바퀴씩 돌아요(공전, 1년에 한 바퀴). 자전축이 기울어져 있어서 지구가 공전하며 위치가 바뀌면, 우리나라에서 보는 태양의 남중 고도가 달라져요. 북쪽 땅(북반구)이 태양 쪽으로 기울어진 위치에서는 남","keywords":["남중","남중 고도","자전축","자전","공전"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-e6","unit":"sci-e6-05","grade":"e6"},
{"id":"sci-e6-05#t0","kind":"term","title":"태양 고도","text":"태양이 지표면과 이루는 각이에요. 태양이 높이 떠 있을수록 커요. 예: 한낮에는 아침보다 태양 고도가 높아요.","keywords":["태양 고도"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-e6","unit":"sci-e6-05","grade":"e6"},
{"id":"sci-e6-05#t1","kind":"term","title":"남중","text":"태양이 하루 중 정남쪽에 와서 가장 높이 떠 있는 것이에요. 우리나라에서는 낮 12시 30분 무렵이에요.","keywords":["남중"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-e6","unit":"sci-e6-05","grade":"e6"},
{"id":"sci-e6-05#t2","kind":"term","title":"남중 고도","text":"태양이 남중했을 때의 태양 고도예요. 하루 중 가장 높은 태양 고도이고, 여름에 높고 겨울에 낮아요.","keywords":["남중 고도"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-e6","unit":"sci-e6-05","grade":"e6"},
{"id":"sci-e6-05#t3","kind":"term","title":"태양 고도 측정기","text":"막대를 세운 판이에요. 그림자 끝과 막대 끝을 실로 이어, 실과 그림자가 이루는 각을 각도기로 재서 태양 고도를 알아내요.","keywords":["태양 고도 측정기"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-e6","unit":"sci-e6-05","grade":"e6"},
{"id":"sci-e6-05#t4","kind":"term","title":"자전축","text":"지구가 스스로 도는(자전하는) 중심이 되는 축이에요. 북극과 남극을 이은 선이고, 약 23.5° 기울어져 있어요.","keywords":["자전축"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-e6","unit":"sci-e6-05","grade":"e6"},
{"id":"sci-e6-05#t5","kind":"term","title":"자전","text":"지구가 자전축을 중심으로 하루에 한 바퀴씩 스스로 도는 것이에요. 낮과 밤이 생기는 까닭이에요.","keywords":["자전"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-e6","unit":"sci-e6-05","grade":"e6"},
{"id":"sci-e6-05#t6","kind":"term","title":"공전","text":"지구가 태양 둘레를 1년에 한 바퀴씩 도는 것이에요. 자전축이 기울어진 채 공전해서 계절이 바뀌어요.","keywords":["공전"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-e6","unit":"sci-e6-05","grade":"e6"},
{"id":"sci-e6-05#f0","kind":"faq","title":"여름에는 태양이 지구에 더 가까워서 더운 거 아니에요?","text":"아니에요. 지구가 태양에 가장 가까워지는 때는 1월 초, 가장 멀어지는 때는 7월 초예요. 우리나라는 태양에 가장 가까운 1월에 겨울이지요. 더구나 지구와 태양 사이의 거리 차이는 아주 작아서 계절을 만들 만큼은 아니에요. 계절은 자전축이 기울어진 채 공전해서 태양의 남중 고도와 낮의 길이가 달라지기 때문에 생겨요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-e6","unit":"sci-e6-05","grade":"e6"},
{"id":"sci-e6-05#f1","kind":"faq","title":"태양은 왜 낮 12시가 아니라 12시 30분쯤에 가장 높이 떠요?","text":"우리나라에서 쓰는 시각은 우리나라보다 조금 동쪽에 있는 곳의 태양을 기준으로 정했어요. 그래서 서울에서는 시계가 12시를 가리킬 때 태양이 아직 정남쪽에 오지 않았고, 30분쯤 뒤에 남중해요. 같은 우리나라 안에서도 동쪽 지역은 조금 일찍, 서쪽 지역은 조금 늦게 남중해요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-e6","unit":"sci-e6-05","grade":"e6"},
{"id":"sci-e6-05#f2","kind":"faq","title":"그림자가 가장 짧은 때가 가장 더운 때 아니에요?","text":"그림자가 가장 짧은 때는 태양이 남중한 낮 12시 30분 무렵이지만, 가장 더운 때는 오후 2시~3시 무렵이에요. 햇빛이 땅을 데우고, 데워진 땅이 다시 공기를 데우는 데 시간이 걸리기 때문이에요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-e6","unit":"sci-e6-05","grade":"e6"},
{"id":"sci-e6-05#m0","kind":"mistake","title":"자주 하는 실수","text":"여름이 더운 까닭을 \"지구가 태양에 가까워져서\"라고 생각하는 실수 — 계절은 자전축이 기울어진 채 공전해서 남중 고도와 낮의 길이가 달라지기 때문에 생겨요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e6","unit":"sci-e6-05","grade":"e6"},
{"id":"sci-e6-05#m1","kind":"mistake","title":"자주 하는 실수","text":"태양 고도가 가장 높을 때 기온도 가장 높다고 생각하는 실수 — 기온은 남중 시각(12시 30분 무렵)보다 늦은 오후 2시~3시 무렵 가장 높아요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e6","unit":"sci-e6-05","grade":"e6"},
{"id":"sci-e6-05#m2","kind":"mistake","title":"자주 하는 실수","text":"태양 고도를 재려고 태양을 직접 바라보는 실수 — 눈을 다쳐요. 막대의 그림자를 이용해 재요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e6","unit":"sci-e6-05","grade":"e6"},
{"id":"sci-e6-06","kind":"unit","title":"물질의 연소","text":"물질의 성질이 바뀌는 변화와 바뀌지 않는 변화를 구별하고, 연소의 조건과 연소 후 생기는 물질, 연소로 생긴 이산화 탄소의 영향을 알아봐요. 물질의 성질이 달라지는 변화와 달라지지 않는 변화를 구별할 수 있어요. 물질이 탈 때 나타나는 공통 현상과 연소의 세 가지 조건을 말할 수 있어요. 연소의 조건을 이용해 불을 끄는 방법을 설명할 수 있어요. 연소 후…","keywords":["연소","발화점","소화","산소","이산화 탄소","석회수","푸른색 염화 코발트 종이","화석 연료","지구 온난화"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e6","unit":"sci-e6-06","grade":"e6"},
{"id":"sci-e6-06#c0","kind":"concept","title":"성질이 달라지는 변화와 달라지지 않는 변화","text":"물질이 변할 때에는 두 가지 경우가 있어요. · 성질이 달라지지 않는 변화 · 성질이 달라지는 변화 뜻 · 모양·크기·상태만 바뀌고 물질은 그대로 · 처음과 성질이 다른 새로운 물질이 생김 예 · 종이 자르기, 얼음이 녹기, 설탕을 물에 녹이기 · 종이 태우기, 베이킹 소다와 식초 섞기","keywords":["이산화 탄소"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e6","unit":"sci-e6-06","grade":"e6"},
{"id":"sci-e6-06#c1","kind":"concept","title":"물질이 탈 때 나타나는 현상","text":"양초, 알코올, 나무가 탈 때를 관찰하면 공통점이 있어요. 빛과 열이 나요. 주위가 밝아지고, 손을 가까이 대면 따뜻해요. 탈 물질의 양이 줄어들어요. 양초는 짧아지고, 알코올램프의 알코올은 줄어들고, 나무는 재만 조금 남아요. 이처럼 물질이 산소와 빠르게 반응하여 빛과 열을 내는 현상","keywords":["연소","산소"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-e6","unit":"sci-e6-06","grade":"e6"},
{"id":"sci-e6-06#c2","kind":"concept","title":"연소의 세 가지 조건","text":"물질이 타려면 다음 세 가지가 모두 있어야 해요. 탈 물질 — 나무, 종이, 양초, 알코올, 가스 등 산소 — 공기 속에 들어 있어요. 발화점 이상의 온도 — 발화점은 불을 직접 붙이지 않아도 물질이 스스로 타기 시작하는 가장 낮은 온도예요. 물질마다 발화점이 달라요. 실험으로 확인하기","keywords":["연소","발화점","산소"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-e6","unit":"sci-e6-06","grade":"e6"},
{"id":"sci-e6-06#c3","kind":"concept","title":"불을 끄는 방법","text":"연소의 세 조건 가운데 하나라도 없애면 불이 꺼져요. 불을 끄는 것을 소화라고 해요. 없애는 조건 · 불을 끄는 방법 탈 물질 · 가스레인지의 밸브 잠그기, 촛불의 심지 자르기, 산불이 번질 곳의 나무 베어 내기 산소 · 알코올램프 뚜껑 덮기, 모래나 흙 덮기, 소화기 분말 뿌리기 발화","keywords":["연소","발화점","소화","산소"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-e6","unit":"sci-e6-06","grade":"e6"},
{"id":"sci-e6-06#c4","kind":"concept","title":"연소 후 생기는 물질","text":"물질이 연소하면 물과 이산화 탄소가 생겨요. 다음처럼 확인해요(불을 쓰므로 어른과 함께). 물 확인: 촛불을 투명한 통으로 덮고 불이 꺼진 뒤 통 안쪽 벽에 푸른색 염화 코발트 종이를 대면 붉은색으로 변해요. 염화 코발트 종이는 물에 닿으면 붉게 변하는 성질이 있어요. 통 안쪽 벽이 뿌","keywords":["연소","이산화 탄소","석회수","푸른색 염화 코발트 종이"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-e6","unit":"sci-e6-06","grade":"e6"},
{"id":"sci-e6-06#c5","kind":"concept","title":"연소로 생긴 이산화 탄소와 생태계","text":"사람들은 석탄·석유·가스 같은 화석 연료를 태워 전기를 만들고, 자동차를 움직이고, 집을 데워요. 이때 많은 이산화 탄소가 공기 중으로 나와요. 기후변화: 공기 중 이산화 탄소가 늘어나면 지구의 열이 우주로 잘 빠져나가지 못해 지구의 평균 기온이 올라가요(지구 온난화). 빙하가 녹아 바","keywords":["연소","이산화 탄소","화석 연료","지구 온난화"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-e6","unit":"sci-e6-06","grade":"e6"},
{"id":"sci-e6-06#t0","kind":"term","title":"연소","text":"물질이 산소와 빠르게 반응하여 빛과 열을 내는 현상이에요. 예: 양초가 타는 것","keywords":["연소"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-e6","unit":"sci-e6-06","grade":"e6"},
{"id":"sci-e6-06#t1","kind":"term","title":"발화점","text":"불을 직접 붙이지 않아도 물질이 스스로 타기 시작하는 가장 낮은 온도예요. 물질마다 달라요. 예: 성냥 머리는 나무보다 발화점이 낮아요.","keywords":["발화점"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-e6","unit":"sci-e6-06","grade":"e6"},
{"id":"sci-e6-06#t2","kind":"term","title":"소화","text":"불을 끄는 것이에요. 연소의 세 조건 가운데 하나 이상을 없애면 불이 꺼져요.","keywords":["소화"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-e6","unit":"sci-e6-06","grade":"e6"},
{"id":"sci-e6-06#t3","kind":"term","title":"산소","text":"공기 속에 들어 있는 기체로, 물질이 탈 때 꼭 필요해요.","keywords":["산소"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-e6","unit":"sci-e6-06","grade":"e6"},
{"id":"sci-e6-06#t4","kind":"term","title":"이산화 탄소","text":"물질이 연소할 때 생기는 기체예요. 석회수를 뿌옇게 흐리게 해요.","keywords":["이산화 탄소"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-e6","unit":"sci-e6-06","grade":"e6"},
{"id":"sci-e6-06#t5","kind":"term","title":"석회수","text":"이산화 탄소를 만나면 뿌옇게 흐려지는 액체예요. 이산화 탄소가 있는지 확인할 때 써요.","keywords":["석회수"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-e6","unit":"sci-e6-06","grade":"e6"},
{"id":"sci-e6-06#t6","kind":"term","title":"푸른색 염화 코발트 종이","text":"물에 닿으면 붉은색으로 변하는 종이예요. 물이 있는지 확인할 때 써요.","keywords":["푸른색 염화 코발트 종이"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-e6","unit":"sci-e6-06","grade":"e6"},
{"id":"sci-e6-06#t7","kind":"term","title":"화석 연료","text":"아주 오래전 생물이 땅속에 묻혀 만들어진 석탄·석유·천연가스 같은 연료예요. 태우면 이산화 탄소가 많이 나와요.","keywords":["화석 연료"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-e6","unit":"sci-e6-06","grade":"e6"},
{"id":"sci-e6-06#t8","kind":"term","title":"지구 온난화","text":"공기 중 이산화 탄소 같은 기체가 늘어나 지구의 평균 기온이 올라가는 현상이에요.","keywords":["지구 온난화"],"ref":{"tab":"terms","idx":8},"subject":"sci","course":"sci-e6","unit":"sci-e6-06","grade":"e6"},
{"id":"sci-e6-06#f0","kind":"faq","title":"불에서 어떻게 물이 생겨요? 불이랑 물은 반대 아니에요?","text":"양초나 알코올을 이루는 성분이 산소와 반응하면 물이 새로 만들어져요. 불꽃이 뜨거워서 물은 처음에 수증기(기체)로 나오고, 차가운 통 벽에 닿으면 작은 물방울로 맺혀요. 그래서 촛불을 덮은 통 안쪽이 뿌옇게 흐려지고, 푸른색 염화 코발트 종이를 대면 붉게 변해요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-e6","unit":"sci-e6-06","grade":"e6"},
{"id":"sci-e6-06#f1","kind":"faq","title":"불이 났을 때 무조건 물을 뿌리면 되지 않아요?","text":"물은 온도를 낮춰 불을 끄는 좋은 방법이지만, 모든 불에 쓰면 안 돼요. 기름에 붙은 불에 물을 부으면 기름이 튀어 불이 더 크게 번지고, 전기 기구에 붙은 불에 물을 뿌리면 감전될 수 있어요. 불이 나면 먼저 크게 알리고 대피한 뒤 119에 신고해요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-e6","unit":"sci-e6-06","grade":"e6"},
{"id":"sci-e6-06#f2","kind":"faq","title":"이산화 탄소는 나쁜 기체인가요?","text":"이산화 탄소 자체가 나쁜 기체는 아니에요. 식물은 이산화 탄소를 이용해 양분을 만들고, 우리가 내쉬는 숨에도 들어 있어요. 문제는 화석 연료를 많이 태워서 공기 중 이산화 탄소가 지나치게 빨리 늘어나는 것이에요. 그래서 기후변화와 바다의 산성화 같은 피해가 생겨요.","keywords":["이산화 탄소"],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-e6","unit":"sci-e6-06","grade":"e6"},
{"id":"sci-e6-06#m0","kind":"mistake","title":"자주 하는 실수","text":"양초가 타서 짧아지면 양초가 \"사라졌다\"고 생각하는 실수 — 양초를 이루던 물질이 물과 이산화 탄소 같은 다른 물질로 바뀌어 공기 중으로 퍼져 나간 거예요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e6","unit":"sci-e6-06","grade":"e6"},
{"id":"sci-e6-06#m1","kind":"mistake","title":"자주 하는 실수","text":"얼음이 녹거나 설탕이 물에 녹는 것을 성질이 달라지는 변화라고 하는 실수 — 상태나 모습만 바뀌고 물질은 그대로예요. 새로운 물질이 생겨야 성질이 달라지는 변화예요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e6","unit":"sci-e6-06","grade":"e6"},
{"id":"sci-e6-06#m2","kind":"mistake","title":"자주 하는 실수","text":"기름이나 전기 기구에 붙은 불에도 물을 뿌리는 실수 — 불이 번지거나 감전될 수 있어요. 산소를 막거나 탈 물질을 없애는 방법을 쓰고, 먼저 어른에게 알려요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e6","unit":"sci-e6-06","grade":"e6"},
{"id":"sci-e6-07","kind":"unit","title":"전기의 이용","text":"전지·전구·전선으로 전기 회로를 만들고, 전지를 연결하는 방법에 따른 전구의 밝기, 전자석의 성질, 전기를 안전하고 아껴 쓰는 방법을 배워요. 전기 회로를 꾸미고 전구에 불이 켜지는 조건을 말할 수 있어요. 전기가 통하는 물질과 통하지 않는 물질을 구별할 수 있어요. 전지 한 개와 전지 두 개를 직렬로 연결한 회로의 전구 밝기를 비교할 수 있어요. 전자석…","keywords":["전기 회로","전지","스위치","전류","전지의 직렬연결","전자석","영구 자석","대기 전력"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e6","unit":"sci-e6-07","grade":"e6"},
{"id":"sci-e6-07#c0","kind":"concept","title":"전기 회로와 전구에 불이 켜지는 조건","text":"전지, 전구, 전선, 스위치 같은 전기 부품을 서로 연결해 전기가 흐르도록 한 것을 전기 회로라고 해요. 부품 · 하는 일 전지 · 전기를 흐르게 해요. (+)극과 (−)극이 있어요. 전구 · 전기가 흐르면 빛을 내요. 꼭지와 꼭지쇠 두 곳에 전선을 연결해요. 전선 · 전기가 지나가는 ","keywords":["전기 회로","전지","스위치"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e6","unit":"sci-e6-07","grade":"e6"},
{"id":"sci-e6-07#c1","kind":"concept","title":"전기가 통하는 물질과 통하지 않는 물질","text":"전기 회로 중간에 여러 물체를 끼워 보면, 전구에 불이 켜지는 물체와 켜지지 않는 물체가 있어요. 전기가 잘 통하는 물질 · 전기가 잘 통하지 않는 물질 철, 구리, 알루미늄 같은 금속 · 플라스틱, 나무, 고무, 유리, 종이, 천 예: 철 못, 구리선, 알루미늄 포일 · 예: 플라스틱","keywords":["전기 회로","전지"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-e6","unit":"sci-e6-07","grade":"e6"},
{"id":"sci-e6-07#c2","kind":"concept","title":"전지 한 개와 전지 두 개를 직렬로 연결할 때","text":"전지 두 개를 서로 다른 극끼리 한 줄로 이어(한 전지의 (+)극을 다른 전지의 (−)극에) 연결하는 것을 전지의 직렬연결이라고 해요. 같은 전구를 쓸 때, 회로 · 전구의 밝기 전지 한 개를 연결한 회로 · 보통 전지 두 개를 직렬로 연결한 회로 · 더 밝다 전지 두 개를 직렬로 연결","keywords":["전지","전지의 직렬연결"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-e6","unit":"sci-e6-07","grade":"e6"},
{"id":"sci-e6-07#c3","kind":"concept","title":"전자석 만들기와 성질","text":"전선에 전기가 흐르는 것을 전류라고 해요. 전류가 흐르는 전선 둘레에는 자석처럼 나침반 바늘을 움직이는 성질이 생겨요. 이 성질을 이용해 만든 자석이 전자석이에요. 만드는 방법: 둥근머리 볼트(철)에 에나멜선을 한 방향으로 여러 번 감고, 에나멜선의 양 끝을 사포로 문질러 겉의 막을 벗","keywords":["전지","스위치","전류","전자석"],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-e6","unit":"sci-e6-07","grade":"e6"},
{"id":"sci-e6-07#c4","kind":"concept","title":"영구 자석과 전자석 비교, 생활 속 전자석","text":"막대자석처럼 늘 자석의 성질을 가진 자석을 영구 자석이라고 해요. · 영구 자석 · 전자석 자석의 성질 · 늘 있어요 · 전류가 흐를 때만 있어요 극 바꾸기 · 바꿀 수 없어요 · 전지의 방향을 바꾸면 바뀌어요 세기 조절 · 조절할 수 없어요 · 전지의 수 등으로 조절할 수 있어요 같은","keywords":["전지","전류","전자석","영구 자석"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-e6","unit":"sci-e6-07","grade":"e6"},
{"id":"sci-e6-07#c5","kind":"concept","title":"전기를 안전하고 효율적으로 쓰기","text":"안전하게 쓰기 과학 실험은 건전지로만 해요. 콘센트 구멍에 젓가락·핀 같은 물건을 넣거나 손을 대지 않아요. 젖은 손으로 플러그나 전기 기구를 만지지 않아요. 플러그를 뽑을 때는 전선을 잡아당기지 말고 플러그 머리를 잡고 뽑아요. 멀티탭 하나에 여러 전기 기구를 한꺼번에 꽂아 쓰지 않아","keywords":["전지","대기 전력"],"ref":{"tab":"concepts","idx":5},"subject":"sci","course":"sci-e6","unit":"sci-e6-07","grade":"e6"},
{"id":"sci-e6-07#t0","kind":"term","title":"전기 회로","text":"전지, 전구, 전선, 스위치 같은 전기 부품을 연결해 전기가 흐르도록 한 것이에요.","keywords":["전기 회로"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-e6","unit":"sci-e6-07","grade":"e6"},
{"id":"sci-e6-07#t1","kind":"term","title":"전지","text":"전기 회로에 전기를 흐르게 하는 부품이에요. (+)극과 (−)극이 있어요. 예: 건전지","keywords":["전지"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-e6","unit":"sci-e6-07","grade":"e6"},
{"id":"sci-e6-07#t2","kind":"term","title":"스위치","text":"회로를 이었다 끊었다 하여 전기가 흐르게 하거나 멈추게 하는 부품이에요.","keywords":["스위치"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-e6","unit":"sci-e6-07","grade":"e6"},
{"id":"sci-e6-07#t3","kind":"term","title":"전류","text":"전기 회로에서 전기가 흐르는 것이에요. 전류가 흘러야 전구에 불이 켜지고, 전자석이 자석이 돼요.","keywords":["전류"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-e6","unit":"sci-e6-07","grade":"e6"},
{"id":"sci-e6-07#t4","kind":"term","title":"전지의 직렬연결","text":"전지 두 개 이상을 서로 다른 극끼리 한 줄로 이어 연결하는 방법이에요. 전지 한 개일 때보다 전구가 더 밝아요.","keywords":["전지의 직렬연결"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-e6","unit":"sci-e6-07","grade":"e6"},
{"id":"sci-e6-07#t5","kind":"term","title":"전자석","text":"전류가 흐를 때만 자석이 되는 자석이에요. 전지의 방향으로 극을 바꾸고, 전지의 수로 세기를 조절할 수 있어요.","keywords":["전자석"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-e6","unit":"sci-e6-07","grade":"e6"},
{"id":"sci-e6-07#t6","kind":"term","title":"영구 자석","text":"막대자석처럼 늘 자석의 성질을 가지고 있는 자석이에요.","keywords":["영구 자석"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-e6","unit":"sci-e6-07","grade":"e6"},
{"id":"sci-e6-07#t7","kind":"term","title":"대기 전력","text":"전기 기구를 꺼 두었어도 플러그가 꽂혀 있어서 조금씩 쓰이는 전기예요. 플러그를 뽑으면 줄일 수 있어요.","keywords":["대기 전력"],"ref":{"tab":"terms","idx":7},"subject":"sci","course":"sci-e6","unit":"sci-e6-07","grade":"e6"},
{"id":"sci-e6-07#f0","kind":"faq","title":"건전지 실험은 괜찮은데 콘센트는 왜 위험해요?","text":"건전지 한 개는 전기를 흐르게 하는 힘이 아주 약해서 손으로 만져도 거의 느낄 수 없어요. 하지만 집의 콘센트 전기는 건전지보다 훨씬 강해서, 몸에 흐르면 크게 다치거나 목숨을 잃을 수도 있어요. 그래서 과학 실험은 반드시 건전지로만 하고, 콘센트에는 플러그 말고는 아무것도 넣지 않아요.","keywords":["전지"],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-e6","unit":"sci-e6-07","grade":"e6"},
{"id":"sci-e6-07#f1","kind":"faq","title":"전지를 많이 연결하면 전구가 계속 더 밝아져요?","text":"전지를 직렬로 더 연결할수록 전구는 더 밝아지지만, 전구가 견딜 수 있는 정도를 넘으면 전구 속 필라멘트가 끊어져 불이 꺼져요. 전자석도 전지를 많이 연결하면 에나멜선이 뜨거워져 위험해요. 실험은 교과서에서 안내하는 전지 수(한두 개)로만 해요.","keywords":["전지"],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-e6","unit":"sci-e6-07","grade":"e6"},
{"id":"sci-e6-07#f2","kind":"faq","title":"에나멜선 끝은 왜 사포로 문질러요?","text":"에나멜선은 구리선 겉에 얇은 막(에나멜)을 입힌 것이에요. 이 막은 전기가 통하지 않아요. 감은 선끼리는 막 덕분에 서로 전기가 새지 않지만, 전지와 연결하는 양 끝은 막을 벗겨야 구리선이 드러나 전류가 흘러요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-e6","unit":"sci-e6-07","grade":"e6"},
{"id":"sci-e6-07#m0","kind":"mistake","title":"자주 하는 실수","text":"전지 두 개를 같은 극끼리 맞대어 연결하는 실수 — 직렬연결은 서로 다른 극((+)극과 (−)극)끼리 이어야 전구가 더 밝아져요. 같은 극끼리 맞대면 불이 켜지지 않아요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e6","unit":"sci-e6-07","grade":"e6"},
{"id":"sci-e6-07#m1","kind":"mistake","title":"자주 하는 실수","text":"전구를 전지의 한쪽 극에만 연결하는 실수 — 전구의 두 곳이 (+)극과 (−)극에 각각 연결되어 끊김 없이 한 바퀴 이어져야 해요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e6","unit":"sci-e6-07","grade":"e6"},
{"id":"sci-e6-07#m2","kind":"mistake","title":"자주 하는 실수","text":"전자석은 늘 자석이라고 생각하는 실수 — 전자석은 전류가 흐를 때만 자석이에요. 전류를 끊으면 자석의 성질이 사라져요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e6","unit":"sci-e6-07","grade":"e6"},
{"id":"sci-e6-08","kind":"unit","title":"과학과 나의 진로","text":"자료를 바탕으로 미래 사회의 문제를 예상하고, 과학기술이 그 문제를 푸는 데 어떻게 도울 수 있는지 알아봐요. 내가 바라는 직업 속 과학을 찾아 진로를 그려 봐요. 자료를 바탕으로 미래 사회에 생길 수 있는 문제를 예상할 수 있어요. 과학기술이 미래 사회의 문제를 해결하는 데 기여하는 방법과 그 한계를 말할 수 있어요. 여러 직업 속에 숨어 있는 과학을 …","keywords":["진로","기후변화","감염병","인공지능","로봇","재생에너지","백신"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e6","unit":"sci-e6-08","grade":"e6"},
{"id":"sci-e6-08#c0","kind":"concept","title":"자료로 미래 사회의 문제 예상하기","text":"미래는 정확히 알 수 없지만, 지금까지 모은 자료를 보면 앞으로 어떻게 될지 예상할 수 있어요. 자료가 꾸준히 오르거나 내리는 경향이 있으면 그 경향이 이어질 때 어떤 일이 생길지 생각해 보는 거예요. 과학자들이 예상하는 미래 사회의 문제에는 이런 것이 있어요. 문제 · 근거가 되는 자","keywords":["기후변화","감염병"],"ref":{"tab":"concepts","idx":0},"subject":"sci","course":"sci-e6","unit":"sci-e6-08","grade":"e6"},
{"id":"sci-e6-08#c1","kind":"concept","title":"문제 해결에 기여하는 과학기술","text":"과학기술은 미래 사회의 문제를 푸는 데 큰 도움을 줄 수 있어요. 과학기술 · 하는 일 · 도움이 되는 문제 인공지능 · 많은 자료에서 규칙을 찾아 예측하거나 판단을 도와요. · 날씨·재해 예측, 질병 진단 돕기 로봇 · 사람 대신 힘들거나 위험한 일을 해요. · 노인 돌봄, 재난 현장","keywords":["기후변화","감염병","인공지능","로봇","재생에너지","백신"],"ref":{"tab":"concepts","idx":1},"subject":"sci","course":"sci-e6","unit":"sci-e6-08","grade":"e6"},
{"id":"sci-e6-08#c2","kind":"concept","title":"과학만으로 모든 문제를 풀 수는 없어요","text":"과학기술은 강력한 도구지만, 과학기술만으로 모든 문제를 해결할 수는 없어요. 사람들의 실천이 함께 필요해요. 재생에너지 시설을 지어도 사람들이 전기를 마구 쓰면 에너지 문제가 풀리지 않아요. 백신이 있어도 손 씻기 같은 생활 습관은 여전히 중요해요. 함께 정한 약속과 제도가 필요해요. ","keywords":["재생에너지","백신"],"ref":{"tab":"concepts","idx":2},"subject":"sci","course":"sci-e6","unit":"sci-e6-08","grade":"e6"},
{"id":"sci-e6-08#c3","kind":"concept","title":"직업 속에 숨어 있는 과학","text":"과학자나 기술자만 과학을 쓰는 것이 아니에요. 여러 직업 속에 과학이 숨어 있어요. 직업 · 숨어 있는 과학 요리사 · 불의 세기와 열이 전달되는 방법, 설탕·소금이 물에 녹는 양, 빵·김치를 만드는 작은 생물(효모·세균) 운동선수 · 우리 몸의 뼈와 근육, 숨쉬기와 심장, 영양소, 공","keywords":[],"ref":{"tab":"concepts","idx":3},"subject":"sci","course":"sci-e6","unit":"sci-e6-08","grade":"e6"},
{"id":"sci-e6-08#c4","kind":"concept","title":"좋아하는 일과 과학을 연결해 진로 그리기","text":"진로는 앞으로 내가 나아갈 길, 곧 어떤 일을 하며 살아갈지를 말해요. 진로는 이렇게 그려 볼 수 있어요. 내가 좋아하는 일·잘하는 일 찾기 — 그림 그리기, 몸 움직이기, 동물 돌보기, 만들기 … 그 일과 관련된 직업 알아보기 — 그림을 좋아한다면 디자이너, 만화가, 건축가 … 그 직","keywords":["진로"],"ref":{"tab":"concepts","idx":4},"subject":"sci","course":"sci-e6","unit":"sci-e6-08","grade":"e6"},
{"id":"sci-e6-08#t0","kind":"term","title":"진로","text":"앞으로 내가 나아갈 길, 곧 어떤 일을 하며 살아갈지를 말해요.","keywords":["진로"],"ref":{"tab":"terms","idx":0},"subject":"sci","course":"sci-e6","unit":"sci-e6-08","grade":"e6"},
{"id":"sci-e6-08#t1","kind":"term","title":"기후변화","text":"오랜 기간에 걸쳐 지구의 평균 기온이 오르고 이상 기후가 잦아지는 것처럼 기후가 바뀌는 현상이에요.","keywords":["기후변화"],"ref":{"tab":"terms","idx":1},"subject":"sci","course":"sci-e6","unit":"sci-e6-08","grade":"e6"},
{"id":"sci-e6-08#t2","kind":"term","title":"감염병","text":"세균이나 바이러스 같은 병원체가 몸에 들어와 생기고, 다른 사람에게 옮을 수 있는 병이에요.","keywords":["감염병"],"ref":{"tab":"terms","idx":2},"subject":"sci","course":"sci-e6","unit":"sci-e6-08","grade":"e6"},
{"id":"sci-e6-08#t3","kind":"term","title":"인공지능","text":"많은 자료에서 규칙을 찾아 예측하거나 판단을 돕도록 만든 컴퓨터 기술이에요.","keywords":["인공지능"],"ref":{"tab":"terms","idx":3},"subject":"sci","course":"sci-e6","unit":"sci-e6-08","grade":"e6"},
{"id":"sci-e6-08#t4","kind":"term","title":"로봇","text":"사람이 시킨 일을 스스로 움직이며 해내는 기계예요. 힘들거나 위험한 일을 대신하기도 해요.","keywords":["로봇"],"ref":{"tab":"terms","idx":4},"subject":"sci","course":"sci-e6","unit":"sci-e6-08","grade":"e6"},
{"id":"sci-e6-08#t5","kind":"term","title":"재생에너지","text":"햇빛·바람·물처럼 써도 다시 생기는 자원으로 만드는 에너지예요. 예: 태양광 발전, 풍력 발전","keywords":["재생에너지"],"ref":{"tab":"terms","idx":5},"subject":"sci","course":"sci-e6","unit":"sci-e6-08","grade":"e6"},
{"id":"sci-e6-08#t6","kind":"term","title":"백신","text":"병에 걸리기 전에 우리 몸이 병원체를 이겨 낼 힘을 기르도록 돕는 약이에요. 감염병 예방에 쓰여요.","keywords":["백신"],"ref":{"tab":"terms","idx":6},"subject":"sci","course":"sci-e6","unit":"sci-e6-08","grade":"e6"},
{"id":"sci-e6-08#f0","kind":"faq","title":"과학자가 될 게 아니면 과학을 왜 배워요?","text":"요리사, 운동선수, 디자이너, 소방관처럼 과학자가 아닌 직업에도 과학이 숨어 있어요. 불을 조절하고, 몸을 관리하고, 재료를 고르는 일에 과학 지식이 쓰이지요. 또 과학을 배우며 기르는 \"자료를 보고 근거를 들어 생각하는 힘\"은 어떤 일을 하든 도움이 돼요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"sci","course":"sci-e6","unit":"sci-e6-08","grade":"e6"},
{"id":"sci-e6-08#f1","kind":"faq","title":"인공지능이나 로봇이 앞으로 사람의 일을 모두 하게 되나요?","text":"인공지능과 로봇이 어떤 일을 돕거나 대신하게 될 수는 있어요. 하지만 다른 사람의 마음을 헤아리기, 여럿이 함께 결정하기, 새로운 것을 상상하기처럼 사람이 중요한 역할을 하는 일이 많고, 기술이 발전하면서 새로운 직업도 생겨나요. 그래서 기술을 두려워하기보다 잘 이해하고 바르게 쓰는 법을 배우는 것이 중요해요.","keywords":["인공지능","로봇"],"ref":{"tab":"faq","idx":1},"subject":"sci","course":"sci-e6","unit":"sci-e6-08","grade":"e6"},
{"id":"sci-e6-08#f2","kind":"faq","title":"아직 좋아하는 일이나 꿈이 없어요. 괜찮아요?","text":"괜찮아요. 많은 사람이 자라면서 여러 경험을 하며 좋아하는 일을 찾아가요. 지금은 궁금한 것을 해 보고, 재미있었던 일을 기록해 두는 것부터 시작해 보세요. 그 기록이 나중에 진로를 그리는 좋은 자료가 돼요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"sci","course":"sci-e6","unit":"sci-e6-08","grade":"e6"},
{"id":"sci-e6-08#m0","kind":"mistake","title":"자주 하는 실수","text":"과학기술만 발전하면 모든 문제가 저절로 풀린다고 생각하는 실수 — 사람들의 실천과 함께 정한 약속이 필요하고, 과학기술이 새로운 문제를 만들기도 해요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e6","unit":"sci-e6-08","grade":"e6"},
{"id":"sci-e6-08#m1","kind":"mistake","title":"자주 하는 실수","text":"자료 없이 느낌만으로 미래를 예상하는 실수 — 지금까지 모은 자료의 변화 경향을 근거로 예상해요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e6","unit":"sci-e6-08","grade":"e6"},
{"id":"sci-e6-08#m2","kind":"mistake","title":"자주 하는 실수","text":"과학은 과학자만 쓰는 것이라고 생각하는 실수 — 요리사·운동선수·디자이너 등 많은 직업에 과학이 숨어 있어요.","keywords":[],"ref":{"tab":"faq"},"subject":"sci","course":"sci-e6","unit":"sci-e6-08","grade":"e6"}
]);
